INSERT INTO _teaser_card_plan (site_id, column_name, old_value, new_value, change_key, reason, premise, evidence) VALUES
    ('b07d443c-8ef1-460a-900d-dc4113ce03e3'::uuid, 'card_description', 'Pompeii''s most important religious building, dedicated to Apollo since 120 BC. Bronze statues of Apollo and Diana flanked the main altar.', 'On a high podium in Pompeii, up an imposing set of steps, stood the Temple of Apollo with its 48 Ionic columns. First excavated in 1817, it was mistaken for a temple of Venus.', 'teaser-card-s020:b07d443c-8ef1-460a-900d-dc4113ce03e3:card_description', 'teaser-card-s020 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '5ecbb534688ff020990cfb9f434d13b31b1c7e457bff892db5d9e1afbfa2db84|a7d06727ed5f29db9fcf34c9a84c63919a12578b8f10cf446bc662d7fb850644|a7d06727ed5f29db9fcf34c9a84c63919a12578b8f10cf446bc662d7fb850644', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a high podium in Pompeii, up an imposing set of steps, stood the Temple of Apollo with its 48 Ionic columns. First excavated in 1817, it was mistaken for a temple of Venus."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the temple stood on a high podium [S3]; it is in Pompeii [S1]; it was entered up an imposing set of steps [S3]; it is the Temple of Apollo [S1]; it had 48 Ionic columns [S3]; excavation began in 1817 [S4]; it was mistakenly identified as a temple of Venus [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Temple of Apollo is a temple in the ancient Roman town of Pompeii [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Pompeii)]; Pompeii, where the temple stands, is in Italy [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Pompeii)]; The temple is dedicated to Apollo [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Pompeii)]; The temple stood on a high podium [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Pompeii)]; The temple was entered up an imposing set of steps [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Pompeii)]; The temple had 48 columns [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Pompeii)]; The columns were of the Ionic order [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Pompeii)]; The temple was first excavated in 1817 [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Pompeii)]; When excavated it was mistaken for a temple of Venus [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Apollo_(Pompeii)]"}]'::jsonb),
    ('b0f8cf11-8472-422b-9e00-cf45b1d80683'::uuid, 'card_description', 'A circular Iron Age fort covering 2.8 hectares, linked to the Catuvellauni and Trinovantes tribes. Its rampart and steep bank survive today.', 'A rampart and steep banked slope ringed South Weald Camp in Essex, a 2.8 hectare hillfort thought to be late Iron Age, later part of a deer-park and then a WWII training ground.', 'teaser-card-s020:b0f8cf11-8472-422b-9e00-cf45b1d80683:card_description', 'teaser-card-s020 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'ff42c6f965e280fc691817bf5615883e91770be3a5ab7d413e1e96759115e53a|7eb8e8a372e6a22d014269a537773cabe0ba4650eca1682c99ae55822bd93a60|7eb8e8a372e6a22d014269a537773cabe0ba4650eca1682c99ae55822bd93a60', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A rampart and steep banked slope ringed South Weald Camp in Essex, a 2.8 hectare hillfort thought to be late Iron Age, later part of a deer-park and then a WWII training ground."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the defences were a rampart and a steep banked slope [S4]; the rampart and slope ringed the (roughly circular) camp [S2, S4]; South Weald Camp is in Essex [S1]; it is a hillfort [S1]; it covers 2.8 hectares [S2]; it is thought (suggested date) to be late Iron Age [S2]; it was later part of a deer-park [S5]; it was then a WWII training ground [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "South Weald Camp is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/South_Weald_Camp]; South Weald Camp is in Essex [SUPPORTED: https://en.wikipedia.org/wiki/South_Weald_Camp]; The hillfort covers 2.8 hectares [SUPPORTED: https://en.wikipedia.org/wiki/South_Weald_Camp]; The fort is thought to date to the late Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/South_Weald_Camp]; Its defences included a rampart [SUPPORTED: https://en.wikipedia.org/wiki/South_Weald_Camp]; Its defences included a steep banked slope [SUPPORTED: https://en.wikipedia.org/wiki/South_Weald_Camp]; The defences ringed the camp (the fort is roughly circular in plan) [SUPPORTED: https://en.wikipedia.org/wiki/South_Weald_Camp]; The site was later used as part of a deer-park [SUPPORTED: https://en.wikipedia.org/wiki/South_Weald_Camp]; The site was then used as a WWII training ground [SUPPORTED: https://en.wikipedia.org/wiki/South_Weald_Camp]"}]'::jsonb),
    ('b0fed6c8-fd75-44e0-b57b-65ed6215f46d'::uuid, 'card_description', 'A Cucuteni-Trypillia mega-settlement from 3200-2700 BC covering 120 hectares. One of 2,440 proto-cities from this culture found across the region.', 'In a burnt house at Kosenivka, a Cucuteni–Trypillia mega-settlement of 3800–3600BC, lay the remains of seven individuals, the find that gave this ancient site its importance.', 'teaser-card-s020:b0fed6c8-fd75-44e0-b57b-65ed6215f46d:card_description', 'teaser-card-s020 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '911a0a7606eec13721697b4023a80ba929d0dd83c48a5458f7fd19af3e36ef51|115e0ac9f04a5a4bc211c4a9157a446e4ff4588222c5d2c1edddc116b2666c25|115e0ac9f04a5a4bc211c4a9157a446e4ff4588222c5d2c1edddc116b2666c25', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In a burnt house at Kosenivka, a Cucuteni–Trypillia mega-settlement of 3800–3600BC, lay the remains of seven individuals, the find that gave this ancient site its importance."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "remains were found in a burnt house at Kosenivka [S2]; Kosenivka is a Cucuteni-Trypillia mega-settlement [S1]; it dates to 3800-3600BC [S1]; the remains were of seven individuals [S2]; that find gave the site its importance [S2]; the site is ancient [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kosenivka is the site of an ancient mega-settlement [SUPPORTED: https://en.wikipedia.org/wiki/Kosenivka]; Kosenivka is in Ukraine [SUPPORTED: https://en.wikipedia.org/wiki/Kosenivka]; The settlement belongs to the Cucuteni–Trypillia culture [SUPPORTED: https://en.wikipedia.org/wiki/Kosenivka]; The settlement dates to 3800–3600 BC [SUPPORTED: https://en.wikipedia.org/wiki/Kosenivka]; The remains of seven individuals were found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Kosenivka]; The seven individuals lay in a burnt house [SUPPORTED: https://en.wikipedia.org/wiki/Kosenivka]; That find is what gave the site its importance [SUPPORTED: https://en.wikipedia.org/wiki/Kosenivka]"}]'::jsonb),
    ('b10bc2a8-f979-4096-a3e2-2e9c88c814ef'::uuid, 'card_description', 'Univallate Iron Age hill fort in Somerset. A 1968 trench through its bank and ditch produced Iron Age pottery, confirming occupation in the Late Prehistoric or early Roman period.', 'Approximately 0.6 miles south-east of Broomfield village, in Somerset, lies Broomfield Camp, or Higher Castles enclosure: a univallate Iron Age hill fort of late prehistoric or Roman times.', 'teaser-card-s020:b10bc2a8-f979-4096-a3e2-2e9c88c814ef:card_description', 'teaser-card-s020 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'b0c46edf6f036f3c4e354c9573d1dcc28764d73de9cddf6a4e2ad41beee72a9f|c1f041aa29e5ef74fd220b172ef3c1a74bf7d284cb69a477aeb9a0381c0b6ae2|c1f041aa29e5ef74fd220b172ef3c1a74bf7d284cb69a477aeb9a0381c0b6ae2', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Approximately 0.6 miles south-east of Broomfield village, in Somerset, lies Broomfield Camp, or Higher Castles enclosure: a univallate Iron Age hill fort of late prehistoric or Roman times."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "it lies approximately 0.6 miles south-east of Broomfield village [S2]; it is in Somerset [S1]; it is also known as Higher Castles enclosure [S1]; it is a univallate Iron Age hill fort [S1]; it dates from late prehistoric or Roman times [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Broomfield Camp is an Iron Age hill fort in Somerset, England [SUPPORTED: https://en.wikipedia.org/wiki/Broomfield_Camp]; Broomfield Camp is also known as Higher Castles enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Broomfield_Camp]; It lies approximately 0.6 miles from the village of Broomfield [SUPPORTED: https://en.wikipedia.org/wiki/Broomfield_Camp]; It lies to the south-east of the village of Broomfield [SUPPORTED: https://en.wikipedia.org/wiki/Broomfield_Camp]; It is a univallate (single rampart) hill fort [SUPPORTED: https://en.wikipedia.org/wiki/Broomfield_Camp]; It dates from late prehistoric or Roman times [SUPPORTED: https://en.wikipedia.org/wiki/Broomfield_Camp]"}]'::jsonb),
    ('b1b150e6-ebca-4c21-ad56-ddccd8c9afcc'::uuid, 'card_description', 'Pre-dating colonist arrival in the 7th century BC, Samothrace''s sanctuary centred on the Great Mother — a chthonic deity. Its Kabeiric mysteries drew initiates from across the ancient world.', 'Samothrace Temple Complex, celebrated throughout Ancient Greece for its Mystery religion, occupies three narrow terraces separated by two steep-banked torrents on mount Hagios Georgios.', 'teaser-card-s020:b1b150e6-ebca-4c21-ad56-ddccd8c9afcc:card_description', 'teaser-card-s020 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '56dd6ae9d1811f30116cfd5cc260feb77e19cf4637651f63044a219b137db073|06ca6c28eb67ac0f5cad9778c6fd597533123e28d267b2a66fe56e284ff6bdba|06ca6c28eb67ac0f5cad9778c6fd597533123e28d267b2a66fe56e284ff6bdba', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Samothrace Temple Complex, celebrated throughout Ancient Greece for its Mystery religion, occupies three narrow terraces separated by two steep-banked torrents on mount Hagios Georgios."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the complex was celebrated throughout Ancient Greece [S3]; it was celebrated for its Mystery religion [S3]; the complex (the sanctuary) occupies three narrow terraces [S1, S8]; the terraces are separated by two steep-banked torrents [S8]; the terraces are on mount Hagios Georgios [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-061 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Samothrace Temple Complex is a religious sanctuary (temple complex) [SUPPORTED: https://en.wikipedia.org/wiki/Samothrace_temple_complex]; It was celebrated throughout Ancient Greece [SUPPORTED: https://en.wikipedia.org/wiki/Samothrace_temple_complex]; It was celebrated for its Mystery religion [SUPPORTED: https://en.wikipedia.org/wiki/Samothrace_temple_complex]; The sanctuary occupies three narrow terraces [SUPPORTED: https://en.wikipedia.org/wiki/Samothrace_temple_complex]; The terraces lie on mount Hagios Georgios [SUPPORTED: https://en.wikipedia.org/wiki/Samothrace_temple_complex]; The terraces are separated by two torrents [SUPPORTED: https://en.wikipedia.org/wiki/Samothrace_temple_complex]; The torrents have steep banks [SUPPORTED: https://en.wikipedia.org/wiki/Samothrace_temple_complex]"}]'::jsonb),
    ('b25977e0-0c67-4b01-96e4-d720919676ac'::uuid, 'card_description', 'Settled for over 7,000 years, from Neolithic cave-dwellers to Phoenician traders by 1000 BC. The Phocaean Greeks called it Akra Leuka — "White Summit" — for the limestone bluff above the harbour.', 'Around Alicante, on the Mediterranean, people have lived for over 7,000 years; here, it is generally presumed, Hamilcar Barca founded the fortified Akra Leuké in the mid-230s BC.', 'teaser-card-s020:b25977e0-0c67-4b01-96e4-d720919676ac:card_description', 'teaser-card-s020 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '3f45fcd450830358bdea1aa9594190581188a664ea8d70263b35b52fe33d8007|352e76c7b15095857d6feef1918c34814d451a583df611451879c2787bafb9a0|352e76c7b15095857d6feef1918c34814d451a583df611451879c2787bafb9a0', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Around Alicante, on the Mediterranean, people have lived for over 7,000 years; here, it is generally presumed, Hamilcar Barca founded the fortified Akra Leuké in the mid-230s BC."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the area around Alicante has been inhabited for over 7,000 years [S1]; Alicante is on the Mediterranean [S4]; it is generally presumed that Akra Leuke stood on the site of Alicante [S3]; Hamilcar Barca founded Akra Leuke [S3]; Akra Leuke was a fortified settlement [S3]; it was founded in the mid-230s BC [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Alicante is a city (a settlement) in Spain [SUPPORTED: https://en.wikipedia.org/wiki/Alicante]; Alicante lies on the Mediterranean [SUPPORTED: https://en.wikipedia.org/wiki/Alicante]; People have lived around Alicante for over 7,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Alicante]; Hamilcar Barca founded Akra Leuké [SUPPORTED: https://en.wikipedia.org/wiki/Alicante]; Akra Leuké was a fortified settlement [SUPPORTED: https://en.wikipedia.org/wiki/Alicante]; Akra Leuké was founded in the mid-230s BC [SUPPORTED: https://en.wikipedia.org/wiki/Alicante]; Akra Leuké is generally presumed (not certain) to have stood on the site of modern Alicante [SUPPORTED: https://en.wikipedia.org/wiki/Alicante]"}]'::jsonb),
    ('b269e1ad-573d-4cd1-8bb2-581a74b5f565'::uuid, 'card_description', 'The oval fort is about 160 metres north–south and 140 metres east–west, enclosing an area of 1.8 hectares.', 'Moel Arthur, an oval Iron Age hillfort of 1.8 hectares, has two large banks and ditches to the north and a narrow inturned entrance at the north-east. Inside, building platforms were found.', 'teaser-card-s020:b269e1ad-573d-4cd1-8bb2-581a74b5f565:card_description', 'teaser-card-s020 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'e176c024df3235ffff784dc07c8a476820a18fd5d2613bbfbf3eac665e2f0ce0|af516fa1e6d50b76638fe62fc83e2a0132ab367763cf2b0d0dd9d11fe877f00f|af516fa1e6d50b76638fe62fc83e2a0132ab367763cf2b0d0dd9d11fe877f00f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Moel Arthur, an oval Iron Age hillfort of 1.8 hectares, has two large banks and ditches to the north and a narrow inturned entrance at the north-east. Inside, building platforms were found."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Moel Arthur is an Iron Age hillfort [S1]; the fort is oval [S3]; it encloses 1.8 hectares [S3]; it has two large banks and ditches to the north [S4]; it has a narrow inturned entrance at the north-east [S5]; building platforms have been found in the interior [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Moel Arthur is an Iron Age hillfort in Wales [SUPPORTED: https://en.wikipedia.org/wiki/Moel_Arthur]; The fort is oval and encloses 1.8 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Moel_Arthur]; The fort has an oval plan [SUPPORTED: https://en.wikipedia.org/wiki/Moel_Arthur]; There are two large banks and ditches to the north [SUPPORTED: https://en.wikipedia.org/wiki/Moel_Arthur]; There is a narrow inturned entrance at the north-east [SUPPORTED: https://en.wikipedia.org/wiki/Moel_Arthur]; Building platforms were found inside the fort [SUPPORTED: https://en.wikipedia.org/wiki/Moel_Arthur]"}]'::jsonb),
    ('b27d56e3-58e8-4ee7-b32f-2f7d58d737ed'::uuid, 'card_description', 'In a series of excavations between 1984 and 1985 Palaeolithic stone artifacts and Pleistocene faunal remains were uncovered.', 'Trou de l''Abîme, a cave by the Eau Noire, yielded Palaeolithic flint brought from a mine at least 30 km away and a partial human molar no one could then call Homo sapiens or Neanderthal.', 'teaser-card-s020:b27d56e3-58e8-4ee7-b32f-2f7d58d737ed:card_description', 'teaser-card-s020 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '723e0aa385b86df2ff8940af9bf9ea02c938cbed5c4e93c2227e4490c4de6a6b|5fbe269b0abf4b415dcbafa93fad19c7709e3c22b3c1f3725b4334a48366f4c7|5fbe269b0abf4b415dcbafa93fad19c7709e3c22b3c1f3725b4334a48366f4c7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Trou de l''Abîme, a cave by the Eau Noire, yielded Palaeolithic flint brought from a mine at least 30 km away and a partial human molar no one could then call Homo sapiens or Neanderthal."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is a cave [S1]; it is by the Eau Noire [S1]; it yielded Palaeolithic stone artifacts, mostly flint [S4, S5]; the flint was brought from a mine at least 30 km away [S5]; it yielded a partial human molar [S6]; at the time of its finding scientists could not determine whether the molar was Homo sapiens or Neanderthal (an unresolved identification) [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Trou de l''Abîme is a cave [SUPPORTED: https://en.wikipedia.org/wiki/Trou_de_l%27Ab%C3%AEme]; The cave lies by the Eau Noire (river, in Couvin, Belgium) [SUPPORTED: https://en.wikipedia.org/wiki/Trou_de_l%27Ab%C3%AEme]; Excavation yielded Palaeolithic stone artefacts [SUPPORTED: https://en.wikipedia.org/wiki/Trou_de_l%27Ab%C3%AEme]; The flint was brought from a mine at least 30 km away [SUPPORTED: https://en.wikipedia.org/wiki/Trou_de_l%27Ab%C3%AEme]; A partial human molar was found [SUPPORTED: https://en.wikipedia.org/wiki/Trou_de_l%27Ab%C3%AEme]; When found, scientists could not tell whether the molar was Homo sapiens or Neanderthal [SUPPORTED: https://en.wikipedia.org/wiki/Trou_de_l%27Ab%C3%AEme]"}]'::jsonb),
    ('b2943cf3-26cd-437e-bdc6-0232105b38b6'::uuid, 'card_description', 'Saxon Shore fort at Caister-on-Sea built around 200 AD — the Gariannonum of Roman records. Perimeter walls 4–5 metres thick enclosed 3.5 hectares until abandonment around 370–390 AD.', 'Caister Roman Site, a Saxon Shore fort constructed around AD 200 for units of the Roman army and navy: a pebbled street would have led from its south gate to a harbour or docks.', 'teaser-card-s020:b2943cf3-26cd-437e-bdc6-0232105b38b6:card_description', 'teaser-card-s020 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', '75e7ab35d49c3c2a5c53dbc8982c599ce1d0d3afb13fb81d3b3ba8ca400186a8|51e5d1d0ff3b7c5a0b80e9dada09b53483e5002ec12010eb7610492f0469e77d|51e5d1d0ff3b7c5a0b80e9dada09b53483e5002ec12010eb7610492f0469e77d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Caister Roman Site, a Saxon Shore fort constructed around AD 200 for units of the Roman army and navy: a pebbled street would have led from its south gate to a harbour or docks."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is a Saxon Shore fort [S1]; it was constructed around AD 200 [S2]; it was built for units of the Roman army and navy [S2]; a pebbled street would have led (hedged: would have) from its south gate to a harbour or docks [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Caister Roman Site is a Roman Saxon Shore fort (at Caister-on-Sea, Norfolk) [SUPPORTED: https://en.wikipedia.org/wiki/Caister_Roman_Site]; The fort was constructed around AD 200 [SUPPORTED: https://www.english-heritage.org.uk/visit/places/caister-roman-site/history/]; It was built for units of the Roman army and navy [SUPPORTED: https://en.wikipedia.org/wiki/Caister_Roman_Site]; A pebbled street would have led from the fort''s south gate to a harbour or docks [SUPPORTED: https://en.wikipedia.org/wiki/Caister_Roman_Site]"}]'::jsonb),
    ('b319970d-efcd-4f5c-9d9b-55535771676b'::uuid, 'card_description', 'The same Iron Age hillfort as Wandlebury Ring, first constructed around 400 BC. A later rebuild added a flat-bottomed ditch and new rampart, showing two phases of defense.', 'Overlooking the ancient Icknield Way, Wandlebury Hill Fort began in about 400 BC as a ditch and a rampart of chalk rubble and soil; its inner ring had a wooden palisade to deter invaders.', 'teaser-card-s020:b319970d-efcd-4f5c-9d9b-55535771676b:card_description', 'teaser-card-s020 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'bb0b011f6c7dde2de1cbfd70a7f304a61e02eed3221f6f27c11d5563c061ca60|afed49040fa8ccdf4ea4c0ed26bc4852fdbcbc51596a7b3efc1e1b71e4a9bb26|afed49040fa8ccdf4ea4c0ed26bc4852fdbcbc51596a7b3efc1e1b71e4a9bb26', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Overlooking the ancient Icknield Way, Wandlebury Hill Fort began in about 400 BC as a ditch and a rampart of chalk rubble and soil; its inner ring had a wooden palisade to deter invaders."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Wandlebury overlooked the ancient Icknield Way [S2]; the first hillfort was built in about 400 BC [S3]; it consisted of a ditch and a rampart of chalk rubble and soil [S3]; the inner ring had a wooden palisade [S4]; the palisade was to deter invaders [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-062 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Wandlebury Hill Fort is an Iron Age hillfort (Gog Magog Hills, Cambridgeshire, England) [SUPPORTED: https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort]; It overlooks the ancient Icknield Way [SUPPORTED: https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort]; The first hillfort began in about 400 BC [SUPPORTED: https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort]; It began as a ditch and a rampart of chalk rubble and soil [SUPPORTED: https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort]; Its inner ring had a wooden palisade [SUPPORTED: https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort]; The palisade was meant to deter invaders [SUPPORTED: https://en.wikipedia.org/wiki/Wandlebury_Hill_Fort]"}]'::jsonb),
    ('b347415b-f65c-4377-bbf2-3c4f553f8804'::uuid, 'card_description', 'The whole site is a scheduled monument and is believed to have been occupied as a significant hill fort both before and during the Roman invasion.', 'On Anglesey, a 164-metre flat-topped limestone hill rises at the eastern end of Red Wharf Bay: Bwrdd Arthur, believed to have been a hill fort before and during the Roman invasion.', 'teaser-card-s020:b347415b-f65c-4377-bbf2-3c4f553f8804:card_description', 'teaser-card-s020 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '35a0c2b60ea5d6be1c8f267e08ebce2bb006120e42c1870fea03cfa6a81e56a9|3ff6cbad257f31c1ba7b8a0c5d32aa6f955cef775a2b59328850a7ebb44597f7|3ff6cbad257f31c1ba7b8a0c5d32aa6f955cef775a2b59328850a7ebb44597f7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Anglesey, a 164-metre flat-topped limestone hill rises at the eastern end of Red Wharf Bay: Bwrdd Arthur, believed to have been a hill fort before and during the Roman invasion."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "it is on Anglesey [S1]; it is a 164-metre flat-topped limestone hill [S1]; it lies at the eastern end of Red Wharf Bay [S2]; it is called Bwrdd Arthur [S1]; it is believed to have been a hill fort before and during the Roman invasion [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Bwrdd Arthur is a hill fort (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Bwrdd_Arthur]; Bwrdd Arthur lies on Anglesey (Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Bwrdd_Arthur]; The hill is 164 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Bwrdd_Arthur]; The hill is flat-topped and of limestone [SUPPORTED: https://en.wikipedia.org/wiki/Bwrdd_Arthur]; The hill rises at the eastern end of Red Wharf Bay [SUPPORTED: https://en.wikipedia.org/wiki/Bwrdd_Arthur]; It is believed (not certain) to have been a hill fort before and during the Roman invasion [SUPPORTED: https://en.wikipedia.org/wiki/Bwrdd_Arthur]"}]'::jsonb),
    ('b38b0f66-79cb-40db-9881-215e01196d2b'::uuid, 'card_description', 'Occupied since the 3rd millennium BC, this headland served as a major Iron Age port trading with Gaul. Purple dye production here rivaled Mediterranean workshops.', 'Jutting into the English Channel, Hengistbury Head held a Creswellian settlement around 14,100 years ago, and later a Late-Iron Age port trading iron, silver and bronze for figs and glass.', 'teaser-card-s020:b38b0f66-79cb-40db-9881-215e01196d2b:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'd72ff6a93fbe40e09ca3e20007f0d8699e6a3763584a9ab6fa90fce1ea38be63|e5c7542dcebce5d36b86938f381d9205c993fbeb324ec27a9be66eddae77b248|e5c7542dcebce5d36b86938f381d9205c993fbeb324ec27a9be66eddae77b248', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Jutting into the English Channel, Hengistbury Head held a Creswellian settlement around 14,100 years ago, and later a Late-Iron Age port trading iron, silver and bronze for figs and glass."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Hengistbury Head juts into the English Channel [S1]; it held a Creswellian settlement [S4]; the Creswellian settlement dates to around 14,100 years ago [S4]; it later became a Late-Iron Age port [S6]; the port traded iron, silver and bronze [S6]; the trade was in return for figs and glass [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Hengistbury Head is a headland (an archaeological site of a settlement and port) in England (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Hengistbury_Head]; Hengistbury Head juts into the English Channel [SUPPORTED: https://en.wikipedia.org/wiki/Hengistbury_Head]; The Head held a Creswellian settlement [SUPPORTED: https://en.wikipedia.org/wiki/Hengistbury_Head]; The Creswellian settlement dates to around 14,100 years ago [SUPPORTED: https://en.wikipedia.org/wiki/Hengistbury_Head]; Later the Head was a Late-Iron Age port [SUPPORTED: https://en.wikipedia.org/wiki/Hengistbury_Head]; The port traded worked metal of iron, silver and bronze [SUPPORTED: https://en.wikipedia.org/wiki/Hengistbury_Head]; It traded these metals in return for figs and glass [SUPPORTED: https://en.wikipedia.org/wiki/Hengistbury_Head]"}]'::jsonb),
    ('b54580b3-4201-4cc6-9588-785d365974d6'::uuid, 'card_description', 'The Roman temple of Alcántara is located at one side of the Alcántara Bridge, Cáceres.', 'Offered to Trajan beside the Alcántara Bridge, the Roman Temple of Alcántara is one of only two Roman temples preserved nearly complete in Spain, its entrance flanked by two Tuscan columns.', 'teaser-card-s020:b54580b3-4201-4cc6-9588-785d365974d6:card_description', 'teaser-card-s020 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'b6c1e282d475b1f0a5be3029c752939fa9ae621f9e061e466e67a9dd19dadc3b|f837b7e4f017c57dad394ce7cbcc7434ee2e14ca2c1ccd7d5f72c644af805c19|f837b7e4f017c57dad394ce7cbcc7434ee2e14ca2c1ccd7d5f72c644af805c19', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Offered to Trajan beside the Alcántara Bridge, the Roman Temple of Alcántara is one of only two Roman temples preserved nearly complete in Spain, its entrance flanked by two Tuscan columns."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the temple was offered to Trajan [S3, S7]; it stands beside the Alcántara Bridge [S1]; it is a Roman temple [S1]; it is one of only two Roman temples preserved nearly complete in Spain [S2]; its entrance is flanked by two Tuscan columns [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Roman Temple of Alcántara is a Roman temple (central claim: the kind of place), in Alcántara, Extremadura, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Roman_temple_of_Alc%C3%A1ntara]; The temple stands beside the Alcántara Bridge [SUPPORTED: https://en.wikip