    ('b5958bf8-444c-4966-8d9b-2a6ad8197350'::uuid, 'card_description', 'The Grey Mare and her Colts is a megalithic chambered long barrow located near Abbotsbury in Dorset.', 'Near Abbotsbury lies the Grey Mare and her Colts, a Neolithic chambered long barrow of 3400-2400 BC; partly excavated in the early nineteenth century, it held human bones and pottery.', 'teaser-card-s020:b5958bf8-444c-4966-8d9b-2a6ad8197350:card_description', 'teaser-card-s020 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '8c01aa4cbdbb19ecdbd9241b79ca6c83e33636666c3aeb4bc7783c8226213192|65b6ac0525739b41ad9a7d73de22f7a90690ebdd1c57978f32ecd3c57eb83b8c|65b6ac0525739b41ad9a7d73de22f7a90690ebdd1c57978f32ecd3c57eb83b8c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Abbotsbury lies the Grey Mare and her Colts, a Neolithic chambered long barrow of 3400-2400 BC; partly excavated in the early nineteenth century, it held human bones and pottery."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "it lies near Abbotsbury [S1]; it is a Neolithic monument [S2]; it is a chambered long barrow [S1]; it dates to 3400-2400 BC [S2]; it was partly excavated in the early nineteenth century [S3]; it held human bones and pottery [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Grey Mare and her Colts is a chambered long barrow (a tomb), near Abbotsbury, Dorset, England (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/The_Grey_Mare_and_her_Colts]; It lies near Abbotsbury [SUPPORTED: https://en.wikipedia.org/wiki/The_Grey_Mare_and_her_Colts]; It is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/The_Grey_Mare_and_her_Colts]; It dates to 3400-2400 BC [SUPPORTED: https://en.wikipedia.org/wiki/The_Grey_Mare_and_her_Colts]; It was partly excavated in the early nineteenth century [SUPPORTED: https://en.wikipedia.org/wiki/The_Grey_Mare_and_her_Colts]; It held human bones and pottery [SUPPORTED: https://en.wikipedia.org/wiki/The_Grey_Mare_and_her_Colts]"}]'::jsonb),
    ('b7020e91-a80b-46cc-8624-878be1713336'::uuid, 'card_description', 'A 1200–400 BC site famous for massive stone carvings in a unique Olmec-influenced style. Reliefs depict humans, jaguars, and rain rituals on exposed rock faces.', 'Near two large granodiorite hills, Chalcatzingo holds Olmec-style monumental art and, on Monument 21, what may be the earliest representation of a woman in Mesoamerican monumental art.', 'teaser-card-s020:b7020e91-a80b-46cc-8624-878be1713336:card_description', 'teaser-card-s020 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '07016667f6fdfe6765eb40b3cf68a5f86b47d2db846f121bc61432430f1a7e05|6abedaaaa46984fec41df0e81cb0354de2e8871cf63e1f15fdc302561a9704c3|6abedaaaa46984fec41df0e81cb0354de2e8871cf63e1f15fdc302561a9704c3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-021", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near two large granodiorite hills, Chalcatzingo holds Olmec-style monumental art and, on Monument 21, what may be the earliest representation of a woman in Mesoamerican monumental art."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-021 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Chalcatzingo is near two large granodiorite hills [S7]; it holds Olmec-style monumental art [S2]; Monument 21 may be the earliest representation of a woman in Mesoamerican monumental art [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-063 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Chalcatzingo is a Mesoamerican archaeological site in Morelos, Mexico (central claim: the kind of place) [SUPPORTED: https://en.wikipedia.org/wiki/Chalcatzingo]; Chalcatzingo lies near two large granodiorite hills [SUPPORTED: https://en.wikipedia.org/wiki/Chalcatzingo]; The site holds Olmec-style monumental art [SUPPORTED: https://en.wikipedia.org/wiki/Chalcatzingo]; Monument 21 may be the earliest representation of a woman in Mesoamerican monumental art [SUPPORTED: https://en.wikipedia.org/wiki/Chalcatzingo]"}]'::jsonb),
    ('b7319c81-70e7-4c3b-9b06-b39bf9cc7dd0'::uuid, 'card_description', 'Two crosses carved into the wall flank the inner doorway of this 4th-century AD church near the Gulf coast. Physical evidence of Christian practice this early and this far east is extremely scarce.', 'Two crosses, still visible, are carved beside the inner doorway from nave to sanctuary of the Jubail Church near the Persian Gulf coast. Its date is contentious: fourth century or seventh?', 'teaser-card-s020:b7319c81-70e7-4c3b-9b06-b39bf9cc7dd0:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'ad0969bb72f67989800ae5d65873c27032cba9fb8641d40bbc110cbc0e66eec1|d87842ced9d68ef0417ef2547a62253223462a91af6fc0b10de3863e854d276f|d87842ced9d68ef0417ef2547a62253223462a91af6fc0b10de3863e854d276f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Two crosses, still visible, are carved beside the inner doorway from nave to sanctuary of the Jubail Church near the Persian Gulf coast. Its date is contentious: fourth century or seventh?"}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "two crosses are carved into the wall [S5]; the two crosses are still visible [S5]; the crosses lie on either side of the inner doorway leading from the nave towards the sanctuary [S5]; the site is the Jubail Church, an ancient church building near Jubail [S1]; the church lies near the Persian Gulf coast [S1]; the date of the church is contentious [S2]; some place it in the fourth century, others in the seventh [S3]; the question implies the date is disputed (unsettled) [S2, S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Jubail Church is an ancient church building (central claim: a church) [SUPPORTED: https://en.wikipedia.org/wiki/Jubail_Church]; The church is near the Persian Gulf coast (near Jubail, a city on the Persian Gulf coast of Saudi Arabia) [SUPPORTED: https://en.wikipedia.org/wiki/Jubail_Church]; There are two crosses at the church [SUPPORTED: https://en.wikipedia.org/wiki/Jubail_Church]; The crosses are still visible [SUPPORTED: https://en.wikipedia.org/wiki/Jubail_Church]; The crosses are carved (into the wall) [SUPPORTED: https://en.wikipedia.org/wiki/Jubail_Church]; The crosses are beside the inner doorway (one on either side of it) [SUPPORTED: https://en.wikipedia.org/wiki/Jubail_Church]; That inner doorway leads from the nave towards the sanctuary [SUPPORTED: https://en.wikipedia.org/wiki/Jubail_Church]; The date of the church is contentious [SUPPORTED: https://en.wikipedia.org/wiki/Jubail_Church]; Some sources place the church in the fourth century [SUPPORTED: https://en.wikipedia.org/wiki/Jubail_Church]; Other sources place the church in the seventh century [SUPPORTED: https://en.wikipedia.org/wiki/Jubail_Church]"}]'::jsonb),
    ('b7cc5073-ffca-4cd3-a168-3062908d4959'::uuid, 'card_description', 'A hilltop enclosure from the Late Bronze Age whose defences were renewed in the Late Iron Age. The single rampart and ditch protected a settlement for centuries.', NULL, 'teaser-card-s020:b7cc5073-ffca-4cd3-a168-3062908d4959:card_description', 'teaser-card-s020 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||ca9aa13116848c72b888924d605b5c9d230a2484f59f6598b9ca57f2797bbaa8', '[{"source": "lane WB run wb-ws-2026-09-27-06: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The web check contradicts: The Anglo-Saxon burial mound still exists as a mound in the hillfort (implied by the present tense ''lie'' a burial mound) (https://en.wikipedia.org/wiki/Beacon_Hill,_West_Sussex: \"This burial mound has been destroyed by modern ploughing.\"); The web check could not prove: The enclosure dates to the 8th to 6th centuries BC (heritage register); The web check could not prove: Its rampart was once faced with timber; The web check could not prove: The telegraph station stands within the enclosure and dates to the late 18th century (heritage register)"}]'::jsonb),
    ('b7deb2fd-c322-4c36-a4b5-7b6551ade780'::uuid, 'card_description', 'A walled Maya port city built atop 12-meter cliffs on the Caribbean coast. One of the last Maya cities inhabited -- occupied for 70 years after the Spanish arrived.', 'On 12-meter-tall cliffs above the Caribbean Sea stand the walls of Tulum, a Maya port whose murals depict the Diving or Descending god, one of the last cities the Maya built.', 'teaser-card-s020:b7deb2fd-c322-4c36-a4b5-7b6551ade780:card_description', 'teaser-card-s020 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '785352f466dda50bbc266d2061c39a19bdf29f0547a7cdb3f88efb04078751d6|4c94ee1148789652cbfdbd501c3089455ded8ec7ea8eb5e8b8ac70cf1fdd6afd|4c94ee1148789652cbfdbd501c3089455ded8ec7ea8eb5e8b8ac70cf1fdd6afd', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On 12-meter-tall cliffs above the Caribbean Sea stand the walls of Tulum, a Maya port whose murals depict the Diving or Descending god, one of the last cities the Maya built."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tulum stands on 12-meter-tall cliffs [S2]; the cliffs are above the Caribbean Sea, on its coast [S2, S8]; Tulum had walls [S1, S8]; Tulum was a Maya port [S1]; murals at the site depict the Diving or Descending god [S7]; Tulum was one of the last cities the Maya built [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tulum is a pre-Columbian Maya walled city that served as a major port (central claim: a walled Maya port city, in Quintana Roo, Mexico) [SUPPORTED: https://en.wikipedia.org/wiki/Tulum]; The ruins stand on 12-meter-tall cliffs [SUPPORTED: https://en.wikipedia.org/wiki/Tulum]; The cliffs/site face the Caribbean Sea [SUPPORTED: https://en.wikipedia.org/wiki/Tulum]; Tulum has walls [SUPPORTED: https://en.wikipedia.org/wiki/Tulum]; Murals at Tulum depict the Diving or Descending god [SUPPORTED: https://en.wikipedia.org/wiki/Tulum]; Tulum was one of the last cities the Maya built [SUPPORTED: https://en.wikipedia.org/wiki/Tulum]"}]'::jsonb),
    ('b9609879-342b-4fae-8dd5-5f6a6ac155d1'::uuid, 'card_description', 'A Talaiotic settlement from the 2nd millennium BC featuring a talaiot tower 12 metres across on the outside but only 6 inside. Walls this thick were built to last.', 'Until 2016 and 2017, bushes and trees covered Na Nova on Mallorca. Its talaiot, a megalithic tower 12 metres across, still keeps its polylithic column and an entrance under a stone lintel.', 'teaser-card-s020:b9609879-342b-4fae-8dd5-5f6a6ac155d1:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'c038f24589afff2bcd400fa707f2c64d71e0271286c14bc410290501c84dd582|cd56edcf1fdfe7fcf459fd618d1eac93b7c910e8c7d4e9dec5431c470064c8cd|cd56edcf1fdfe7fcf459fd618d1eac93b7c910e8c7d4e9dec5431c470064c8cd', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Until 2016 and 2017, bushes and trees covered Na Nova on Mallorca. Its talaiot, a megalithic tower 12 metres across, still keeps its polylithic column and an entrance under a stone lintel."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "bushes and trees covered Na Nova until 2016 and 2017 (its first cleaning) [S8]; Na Nova is on Mallorca [S1]; the site has a talaiot [S3]; the talaiot is a megalithic, tower-shaped structure [S3]; the talaiot is 12 metres across (outside diameter) [S4]; the polylithic column still stands [S6]; the entrance with its stone lintel is still there [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Na Nova is a Talaiotic (Iron Age) settlement (central claim: a settlement with a talaiot) [SUPPORTED: https://en.wikipedia.org/wiki/Na_Nova]; Na Nova is on Mallorca (Spain) [SUPPORTED: https://en.wikipedia.org/wiki/Na_Nova]; The site was covered by bushes and trees [SUPPORTED: https://en.wikipedia.org/wiki/Na_Nova]; The cover of bushes and trees lasted until the first cleaning in 2016 and 2017 [SUPPORTED: https://en.wikipedia.org/wiki/Na_Nova]; The talaiot is a megalithic tower [SUPPORTED: https://en.wikipedia.org/wiki/Na_Nova]; The talaiot is 12 metres across (outside diameter) [SUPPORTED: https://en.wikipedia.org/wiki/Na_Nova]; The talaiot still keeps its polylithic column [SUPPORTED: https://en.wikipedia.org/wiki/Na_Nova]; The talaiot keeps an entrance under a stone lintel [SUPPORTED: https://en.wikipedia.org/wiki/Na_Nova]"}]'::jsonb),
    ('ba23010b-c042-4557-a580-384f2262febf'::uuid, 'card_description', 'Built at the start of the 25th century BC by Userkaf, founder of the Fifth Dynasty. Called Nekhen-Re — Stronghold of Ra — standing between Abusir and Abu Gorab, declaring solar devotion in stone.', 'On a low hill at the desert edge, reached by a causeway from a valley temple, stood the Sun Temple of Userkaf, built for the sun god Ra and anciently named Nekhen-Re, the Stronghold of Ra.', 'teaser-card-s020:ba23010b-c042-4557-a580-384f2262febf:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'ba928f152009879c6e76295c80134a2d0b83d41110fcc2c82279ab305c2874d0|426b2c61074adfdd74236c2d9d80f16642b524d3a8fbf3689135ce8bc45091a4|426b2c61074adfdd74236c2d9d80f16642b524d3a8fbf3689135ce8bc45091a4', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a low hill at the desert edge, reached by a causeway from a valley temple, stood the Sun Temple of Userkaf, built for the sun god Ra and anciently named Nekhen-Re, the Stronghold of Ra."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the main temple stood on a low hill at the desert edge [S4]; it was reached by a causeway from a valley temple [S4]; the site is the Sun Temple of Userkaf [S1]; it was built for (dedicated to) the sun god Ra [S1]; its ancient name was Nekhen-Re [S3]; Nekhen-Re means the Stronghold of Ra [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-064 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Sun Temple of Userkaf was an ancient Egyptian temple (central claim: a sun temple in Egypt) [SUPPORTED: https://en.wikipedia.org/wiki/Sun_Temple_of_Userkaf]; It was built for the sun god Ra (by Pharaoh Userkaf) [SUPPORTED: https://en.wikipedia.org/wiki/Sun_Temple_of_Userkaf]; The main temple stood on a low hill [SUPPORTED: https://en.wikipedia.org/wiki/Sun_Temple_of_Userkaf]; The low hill is at the desert edge [SUPPORTED: https://en.wikipedia.org/wiki/Sun_Temple_of_Userkaf]; The main temple was reached by a causeway [SUPPORTED: https://en.wikipedia.org/wiki/Sun_Temple_of_Userkaf]; The causeway led from a valley temple [SUPPORTED: https://en.wikipedia.org/wiki/Sun_Temple_of_Userkaf]; The temple''s ancient name was Nekhen-Re [SUPPORTED: https://en.wikipedia.org/wiki/Sun_Temple_of_Userkaf]; Nekhen-Re means the Stronghold of Ra [SUPPORTED: https://en.wikipedia.org/wiki/Sun_Temple_of_Userkaf]"}]'::jsonb),
    ('ba2e2b75-be17-4c77-9f6c-b0cd4d282aa5'::uuid, 'card_description', 'A 3rd-century AD Roman temple perched on a hill in the Beqaa Valley. Part of a complex blending Roman imperial religion with local Phoenician traditions.', 'The Hosn Niha Roman Temple site lies at the base of a steep slope near the Beqaa Valley. Its Upper Great Temple faces east from a podium: four columns, a cella, then an elevated adytum.', 'teaser-card-s020:ba2e2b75-be17-4c77-9f6c-b0cd4d282aa5:card_description', 'teaser-card-s020 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '52640318690c75d4cb1e670a8992d7d43bc3e54a68f7c6ac92a1298cb503a21a|a6f0950119867ba02f40e806ddedef7a94fa5cc30db0cd0167ff362f1549b286|a6f0950119867ba02f40e806ddedef7a94fa5cc30db0cd0167ff362f1549b286', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Hosn Niha Roman Temple site lies at the base of a steep slope near the Beqaa Valley. Its Upper Great Temple faces east from a podium: four columns, a cella, then an elevated adytum."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is Hosn Niha (Roman Temple), an archaeological site [S1]; the site lies at the base of a steep slope [S2]; the site is near the Beqaa Valley [S2]; the Upper Great Temple faces east [S6]; the Upper Great Temple is built on a podium [S6]; the temple has a portico with four columns, then a cella, then an elevated adytum [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Hosn Niha is a temple site (an archaeological site of temples in Lebanon, outskirts of Niha village) [SUPPORTED: https://en.wikipedia.org/wiki/Hosn_Niha]; The temples are Roman (built 1st to 3rd century AD) [SUPPORTED: https://en.wikipedia.org/wiki/Hosn_Niha]; The site lies at the base of a steep slope [SUPPORTED: https://en.wikipedia.org/wiki/Hosn_Niha]; The site is near the Beqaa Valley [SUPPORTED: https://en.wikipedia.org/wiki/Hosn_Niha]; The Upper Great Temple faces east [SUPPORTED: https://en.wikipedia.org/wiki/Hosn_Niha]; The Upper Great Temple stands on a podium [SUPPORTED: https://en.wikipedia.org/wiki/Hosn_Niha]; The Upper Great Temple has a portico of four columns [SUPPORTED: https://en.wikipedia.org/wiki/Hosn_Niha]; Behind the columns come a cella, then an elevated adytum [SUPPORTED: https://en.wikipedia.org/wiki/Hosn_Niha]"}]'::jsonb),
    ('ba877057-f093-46ef-80b9-762e1859b320'::uuid, 'card_description', 'The Villa of the Papyri was an ancient Roman villa in Herculaneum, in what is now Ercolano.', 'Farmers digging a well in 1750 found the Villa of the Papyri, a Roman villa on the coast below Vesuvius with a unique library of papyrus scrolls, covered by the eruption of AD 79.', 'teaser-card-s020:ba877057-f093-46ef-80b9-762e1859b320:card_description', 'teaser-card-s020 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', 'b9f07b0eb051f9d5c57ddf0330df0a3a0b57817f2db73682c2e2666221d059a6|02799fa93688d4494c48dfb5080ae852e413fdea9fad9d7a0d3f88f0f97d26e8|02799fa93688d4494c48dfb5080ae852e413fdea9fad9d7a0d3f88f0f97d26e8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Farmers digging a well in 1750 found the Villa of the Papyri, a Roman villa on the coast below Vesuvius with a unique library of papyrus scrolls, covered by the eruption of AD 79."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "farmers digging a well found the villa [S8]; the villa was found in 1750 [S8]; it is the Villa of the Papyri, a Roman villa [S1]; it stood on the coast below Vesuvius [S5]; it is named for a unique library of papyrus scrolls [S2]; the villa was covered by the eruption of AD 79 [S1, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Villa of the Papyri is a Roman villa [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_the_Papyri]; The villa stood on the coast below Vesuvius [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_the_Papyri]; It was found in 1750, by farmers digging a well [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_the_Papyri]; It held a unique library of papyrus scrolls [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_the_Papyri]; The library is unique as the only surviving library of the Graeco-Roman world that exists in its entirety [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_the_Papyri]; The villa was covered by the eruption of Vesuvius in AD 79 [SUPPORTED: https://en.wikipedia.org/wiki/Villa_of_the_Papyri]"}]'::jsonb),
    ('baf13030-1578-4edc-a351-ca627828a326'::uuid, 'card_description', 'Almost all moai were carved from compressed, easily worked solidified volcanic ash or tuff, found at a single site on the side of the extinct volcano Rano Raraku.', 'On Easter Island, the native carvers of the moai used only stone hand chisels, mainly basalt toki, which lie in place all over the quarry. Of 313 known ahu, 125 carried moai, usually one.', 'teaser-card-s020:baf13030-1578-4edc-a351-ca627828a326:card_description', 'teaser-card-s020 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'd1b024b01cb0746b69d2b2a90474470a0f84c444805ea4c536e62a9e9e37c932|e39b221da6480a7a3a9bf272a542240e40a866200c04cdf7b42bd0f4983f432c|e39b221da6480a7a3a9bf272a542240e40a866200c04cdf7b42bd0f4983f432c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Easter Island, the native carvers of the moai used only stone hand chisels, mainly basalt toki, which lie in place all over the quarry. Of 313 known ahu, 125 carried moai, usually one."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the moai are on Easter Island [S1]; the native islanders carved the moai [S5]; the carvers used only stone hand chisels [S5]; the chisels were mainly basalt toki [S5]; the toki lie in place all over the quarry [S5]; there are 313 known ahu [S6]; 125 of the ahu carried moai [S6]; an ahu usually carried just one moai [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Easter Island (Chile) is an island whose moai were carved at a quarry on it [SUPPORTED: https://en.wikipedia.org/wiki/Rano_Raraku]; The moai were carved in a quarry (Rano Raraku) on Easter Island [SUPPORTED: https://en.wikipedia.org/wiki/Rano_Raraku]; The moai were carved by the native islanders of Easter Island [SUPPORTED: https://en.wikipedia.org/wiki/Easter_Island]; The native carvers of the moai used only stone hand chisels [SUPPORTED: https://en.wikipedia.org/wiki/Easter_Island]; The chisels were mainly basalt toki, which lie in place all over the quarry [SUPPORTED: https://en.wikipedia.org/wiki/Easter_Island]; There are 313 known ahu on Easter Island [SUPPORTED: https://en.wikipedia.org/wiki/Easter_Island]; 125 of the known ahu carried moai [SUPPORTED: https://en.wikipedia.org/wiki/Easter_Island]; The ahu that carried moai usually carried just one [SUPPORTED: https://en.wikipedia.org/wiki/Easter_Island]"}]'::jsonb),
    ('bbfd5685-5e03-4a18-8625-9435c4cf8e7b'::uuid, 'card_description', 'A Minoan settlement with a "Royal Villa" near the palace of Phaistos. It yielded the famous Harvester Vase and a trove of Linear A tablets that remain undeciphered.', 'Not a palace but an upscale Minoan town in south central Crete, Hagia Triada gave up the Harvester Vase and about 150 Linear A tablets, the largest cache at any Minoan site.', 'teaser-card-s020:bbfd5685-5e03-4a18-8625-9435c4cf8e7b:card_description', 'teaser-card-s020 (teaser-card): teaser card, 173 characters, checked PASS, web-verified VERIFIED', '1fdb8ebeb13e3e6eacd86c91d48c95e9956ed7453e5bce6975d1b85475d669ae|899038febbc6c359927e2946ddef1c54057bc86ad1585d8bcc7b733df9304ffa|899038febbc6c359927e2946ddef1c54057bc86ad1585d8bcc7b733df9304ffa', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Not a palace but an upscale Minoan town in south central Crete, Hagia Triada gave up the Harvester Vase and about 150 Linear A tablets, the largest cache at any Minoan site."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Hagia Triada was not a palace [S8]; it was an upscale Minoan town [S1, S8]; it lies in south central Crete [S7]; the Harvester Vase was found there [S2]; about 150 Linear A tablets were found [S3]; that is the largest cache at any Minoan site [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Hagia Triada is a Minoan archaeological site (a settlement) in Crete [SUPPORTED: https://en.wikipedia.org/wiki/Hagia_Triada]; Hagia Triada lies in south central Crete [SUPPORTED: https://en.wikipedia.org/wiki/Hagia_Triada]; It was not a Minoan palace [SUPPORTED: https://en.wikipedia.org/wiki/Hagia_Triada]; It was an upscale town [SUPPORTED: https://en.wikipedia.org/wiki/Hagia_Triada]; The Harvester Vase was found at Hagia Triada [SUPPORTED: https://en.wikipedia.org/wiki/Harvester_Vase]; About 150 Linear A tablets were found there [SUPPORTED: https://en.wikipedia.org/wiki/Hagia_Triada]; Hagia Triada yielded 147 Linear A tablets, consistent with about 150 [SUPPORTED: https://en.wikipedia.org/wiki/Linear_A]; That is the largest cache of Linear A tablets at any Minoan site [SUPPORTED: https://en.wikipedia.org/wiki/Hagia_Triada]"}]'::jsonb),
    ('bc85d3d5-a47e-4c4d-be70-aaa1c18915d1'::uuid, 'card_description', '5th-millennium BC Vinča culture settlement near Belgrade. Research since 1962 gives unprecedented scope to study an uninterrupted Neolithic occupation; declared a cultural monument in 2014.', 'Between the creeks of Izvorac and Trstenica, the houses of Crkvine stood in street-like rows, a Vinča culture settlement of the 5th millennium BC that has yielded almost 50,000 artifacts.', 'teaser-card-s020:bc85d3d5-a47e-4c4d-be70-aaa1c18915d1:card_description', 'teaser-card-s020 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', '5f3ff9c4feaca9685031d4582ff5558e9799f9b739d0f3e5bdb21e1b0fbf3b02|e24af960a86dc1c84cf376be6fd7f21a43d4b666c8c12fa2c73e5b0ab0b0c744|e24af960a86dc1c84cf376be6fd7f21a43d4b666c8c12fa2c73e5b0ab0b0c744', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Between the creeks of Izvorac and Trstenica, the houses of Crkvine stood in street-like rows, a Vinča culture settlement of the 5th millennium BC that has yielded almost 50,000 artifacts."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies between the creeks of Izvorac and Trstenica [S4]; the houses stood in street-like rows [S5]; Crkvine is a Vinča culture settlement [S2]; the settlement dates to the 5th millennium BC [S2]; almost 50,000 artifacts have been found [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-065 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Crkvine (Stubline, Serbia) is a settlement of the Vinca culture [SUPPORTED: https://en.wikipedia.org/wiki/Crkvine_(Stubline)]; It is a Vinca settlement with houses (a large settlement, at least 218 houses) [SUPPORTED: https://en.wikipedia.org/wiki/Crkvine_(Stubline)]; The settlement dates to the 5th millennium BC [SUPPORTED: https://en.wikipedia.org/wiki/Crkvine_(Stubline)]; The site lies between the creeks of Izvorac and Trstenica [SUPPORTED: https://en.wikipedia.org/wiki/Crkvine_(Stubline)]; The houses stood in street-like rows [SUPPORTED: https://en.wikipedia.org/wiki/Crkvine_(Stubline)]; Almost 50,000 artifacts have been found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Crkvine_(Stubline)]"}]'::jsonb),
    ('bc936eb9-20d2-4d52-9637-cca891a4b6e8'::uuid, 'card_description', 'A possible Iron Age through Roman fortress on a plateau. A single rampart and ditch enclosed 1.6 hectares of what is now dense woodland.', 'Castle Wood covers the rampart and ditch of Kenwalch''s Castle, probably an Iron Age hill fort, perhaps later a Roman fortress, and believed to be named after Cenwalh of Wessex.', 'teaser-card-s020:bc936eb9-20d2-4d52-9637-cca891a4b6e8:card_description', 'teaser-card-s020 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', '8aedb038fa2d6212279706509605c7525631d0c39d0a28f5cd2bc25d83c110de|daa3adddf92e495a3d034c00cefdf4462b581cb3239262e72c4c0d527c3793b5|daa3adddf92e495a3d034c00cefdf4462b581cb3239262e72c4c0d527c3793b5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castle Wood covers the rampart and ditch of Kenwalch''s Castle, probably an Iron Age hill fort, perhaps later a Roman fortress, and believed to be named after Cenwalh of Wessex."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castle Wood covers the defences (rampart and ditch) of Kenwalch''s Castle [S4, S6]; the site is probably an Iron Age hill fort [S1]; it may later have been converted into a Roman fortress [S1]; it is believed to be named after Cenwalh of Wessex [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kenwalch''s Castle is a hill fort (an earthwork fort), the central claim of the text [SUPPORTED: https://en.wikipedia.org/wiki/Kenwalch%27s_Castle]; The hill fort is probably Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Kenwalch%27s_Castle]; It was perhaps later (converted into) a Roman fortress [SUPPORTED: https://en.wikipedia.org/wiki/Kenwalch%27s_Castle]; Castle Wood covers the defences of the site [SUPPORTED: https://en.wikipedia.org/wiki/Kenwalch%27s_Castle]; The site has a rampart and a ditch [SUPPORTED: https://en.wikipedia.org/wiki/Kenwalch%27s_Castle]; The castle is believed to be named after Cenwalh of Wessex [SUPPORTED: https://en.wikipedia.org/wiki/Kenwalch%27s_Castle]"}]'::jsonb),
    ('bdbe5ee5-28a4-4f75-9777-e9d733738451'::uuid, 'card_description', 'From the 8th century BC, this Oxfordshire hillfort has two earth banks, a ditch, and an original western entrance. A second eastern entrance was deliberately blocked a few centuries later.', 'Uffington Castle, an early Iron Age hillfort in Oxfordshire, once wore a parapet of sarsen stones on its inner rampart, and in 1882 was among the first 68 sites to receive legal protection.', 'teaser-card-s020:bdbe5ee5-28a4-4f75-9777-e9d733738451:card_description', 'teaser-card-s020 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'f34888b08a4cd77b4f561544d13c98ca1dde0908c3e85ce72d33a3f1bbfd6c07|3a972a3c89ba80c1f69aa700a303d1a0857df0a012547515be36d4590549bf14|3a972a3c89ba80c1f69aa700a303d1a0857df0a012547515be36d4590549bf14', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Uffington Castle, an early Iron Age hillfort in Oxfordshire, once wore a parapet of sarsen stones on its inner rampart, and in 1882 was among the first 68 sites to receive legal protection."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Uffington Castle is an early Iron Age hillfort [S1]; it lies in Oxfordshire [S1]; a parapet of sarsen stones once lined the inner (innermost) rampart [S6]; it was included in the 1882 Act [S8]; it was among the first 68 sites to receive legal protection [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Uffington Castle is a hillfort, the central claim of the text [SUPPORTED: https://en.wikipedia.org/wiki/Uffington_Castle]; The hillfort is in Oxfordshire [SUPPORTED: https://en.wikipedia.org/wiki/Uffington_Castle]; The hillfort is early Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Uffington_Castle]; A parapet of sarsen stones once lined its inner rampart [SUPPORTED: https://en.wikipedia.org/wiki/Uffington_Castle]; It received legal protection in 1882 (Ancient Monuments Protection Act 1882) [SUPPORTED: https://en.wikipedia.org/wiki/Uffington_Castle]; It was among the first 68 sites to receive legal protection [SUPPORTED: https://en.wikipedia.org/wiki/Uffington_Castle]"}]'::jsonb),
    ('be5e8af5-aaee-4119-9572-a66ee691f455'::uuid, 'card_description', 'Occupied from ~48,000 BC. Three ground bone beads found here — dating to 19,000 BP — are among the oldest evidence of symbolic behaviour in Australia. Over 100 distinct sediment layers record it all.', 'Named for the Tasmanian devil remains found inside, Devil''s Lair is a limestone cave in Western Australia whose occupation dates back more than 40,000 years, with hearths and bone beads.', 'teaser-card-s020:be5e8af5-aaee-4119-9572-a66ee691f455:card_description', 'teaser-card-s020 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'fbe12e185303807a186c4e8137b59b66a15132d09a2b096ee86769e976e8295f|27e92ddad61ec3f0c1e07a4b0d91918e8d6c4f0b6c2c28145588c3443e7eb146|27e92ddad61ec3f0c1e07a4b0d91918e8d6c4f0b6c2c28145588c3443e7eb146', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Named for the Tasmanian devil remains found inside, Devil''s Lair is a limestone cave in Western Australia whose occupation dates back more than 40,000 years, with hearths and bone beads."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is named for the Tasmanian devil remains found there [S3]; Devil''s Lair is a cave formed in limestone [S1]; it is in Western Australia [S1]; occupation dates back more than 40,000 years [S5]; hearths were found [S2]; bone beads were found [S6, S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Devil''s Lair is a cave in Western Australia, the central claim of the text [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Lair]; The cave lies in Western Australia [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Lair]; It is a limestone cave [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Lair]; It is named for the Tasmanian devil remains found inside [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Lair]; Occupation of the cave dates back more than 40,000 years [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Lair]; Hearths were found in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Lair]; Bone beads were found in the cave [SUPPORTED: https://en.wikipedia.org/wiki/Devil%27s_Lair]"}]'::jsonb),
    ('be92ce6c-0c0e-43da-b5b8-be9137f0e151'::uuid, 'card_description', 'Pachataka is a pre-Inca astronomical observatory formed by a lintel made of two parallel stone blocks.', 'Known as the Inca Gallows, Pachat''aqa crowns Mount Kesanani near Lake Titicaca: a lintel of two parallel stone blocks, a pre-Inca observatory used to track the moon and predict eclipses.', 'teaser-card-s020:be92ce6c-0c0e-43da-b5b8-be9137f0e151:card_description', 'teaser-card-s020 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', 'c5283f00b257736b2a6c8694802bac6f3017a96b76c27016d18b214462321630|0687dac5d1fdbd67c5c9c68ceca55f3cebe982136ed399325474d1065f9c4b3d|0687dac5d1fdbd67c5c9c68ceca55f3cebe982136ed399325474d1065f9c4b3d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Known as the Inca Gallows, Pachat''aqa crowns Mount Kesanani near Lake Titicaca: a lintel of two parallel stone blocks, a pre-Inca observatory used to track the moon and predict eclipses."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pachat''aqa is known as the Inca Gallows [S1]; it is at the summit of Mount Kesanani [S4]; it is near Lake Titicaca [S1]; it is formed by a lintel of two parallel stone blocks [S2]; it is a pre-Inca observatory [S2]; it was used to track lunar movements [S3]; it was used to predict eclipses [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pachat''aqa is an archaeological site in Bolivia, the central claim of the text [SUPPORTED: https://en.wikipedia.org/wiki/Pachat%27aqa]; It lies near Lake Titicaca [SUPPORTED: https://en.wikipedia.org/wiki/Pachat%27aqa]; It is known as the Inca Gallows [SUPPORTED: https://en.wikipedia.org/wiki/Pachat%27aqa]; It lies at the summit of Mount Kesanani [SUPPORTED: https://en.wikipedia.org/wiki/Pachat%27aqa]; It is a lintel of two parallel stone blocks [SUPPORTED: https://en.wikipedia.org/wiki/Pachat%27aqa]; It is a pre-Inca observatory [SUPPORTED: https://en.wikipedia.org/wiki/Pachat%27aqa]; It was used to track the moon [SUPPORTED: https://en.wikipedia.org/wiki/Pachat%27aqa]; It was used to predict eclipses [SUPPORTED: https://en.wikipedia.org/wiki/Pachat%27aqa]"}]'::jsonb),
    ('bebeb092-4bf8-41da-accd-cf2a8b640343'::uuid, 'card_description', 'A Roman villa built inside the ramparts of a larger Iron Age fortress. A bath suite with mosaic floors was among the rooms uncovered during 19th-century excavations.', 'Within the ramparts of an Iron Age fortress near Daventry lies Borough Hill Roman Villa, a single storey of marlstone rooms running from north to south, a bath suite among them.', 'teaser-card-s020:bebeb092-4bf8-41da-accd-cf2a8b640343:card_description', 'teaser-card-s020 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'a25fd46f2ede940d8e54c97772f74a3801ee9963105d3884644acd3b81ad3bdd|7ef10153ab24164d04daebf3f743d64a09532eea1f0a7b92bc69ae44168385d7|7ef10153ab24164d04daebf3f743d64a09532eea1f0a7b92bc69ae44168385d7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-022", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Within the ramparts of an Iron Age fortress near Daventry lies Borough Hill Roman Villa, a single storey of marlstone rooms running from north to south, a bath suite among them."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-022 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the villa lies within the ramparts of an Iron Age fortress [S2]; it is near Daventry [S1]; it is Borough Hill Roman Villa [S1]; the villa was a single storey [S8]; it was built of marlstone [S8]; its rooms ran from north to south [S5]; a bath suite was part of the rooms [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-066 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Borough Hill Roman Villa is a Roman villa, the central claim of the text [SUPPORTED: https://en.wikipedia.org/wiki/Borough_Hill_Roman_villa]; The villa is near Daventry [SUPPORTED: https://en.wikipedia.org/wiki/Borough_Hill_Roman_villa]; The villa lies within the ramparts of an Iron Age fortress [SUPPORTED: https://en.wikipedia.org/wiki/Borough_Hill_Roman_villa]; The villa consisted of a single storey [SUPPORTED: https://en.wikipedia.org/wiki/Borough_Hill_Roman_villa]; The villa was built of marlstone [SUPPORTED: https://en.wikipedia.org/wiki/Borough_Hill_Roman_villa]; Its rooms ran from north to south [SUPPORTED: https://en.wikipedia.org/wiki/Borough_Hill_Roman_villa]; A bath suite was among the rooms [SUPPORTED: https://en.wikipedia.org/wiki/Borough_Hill_Roman_villa]"}]'::jsonb),
    ('bf6f967e-3161-45c3-840d-d68ebff231b7'::uuid, 'card_description', 'Caves used as a necropolis from the Paleolithic through the Neolithic. Finds are split across two museums — the caves themselves are rarely open to the public.', 'In Cascais, evidence points to use of the Caves of Poço Velho as a necropolis, with around 115 burials identified. Finds include limestone votive offerings and decorated schist slabs.', 'teaser-card-s020:bf6f967e-3161-45c3-840d-d68ebff231b7:card_description', 'teaser-card-s020 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'abe0683541274a0eca477b50713d598de694d3865c466b8398fb2b066850a5d1|1f7073752ab6409af65c554af494529e35281a9fa60a097fa7fa647618fffd46|1f7073752ab6409af65c554af494529e35281a9fa60a097fa7fa647618fffd46', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Cascais, evidence points to use of the Caves of Poço Velho as a necropolis, with around 115 burials identified. Finds include limestone votive offerings and decorated schist slabs."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the caves are in Cascais [S1]; evidence points to their use as a necropolis (hedged: evidence points to) [S4]; around 115 burials have been identified [S4]; finds include limestone votive offerings [S5]; finds include decorated schist slabs [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Caves of Poço Velho are a cave site used as a necropolis (burial place) [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Po%C3%A7o_Velho]; The caves are located in Cascais, Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Po%C3%A7o_Velho]; Around 115 burials have been identified [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Po%C3%A7o_Velho]; Finds include limestone votive offerings [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Po%C3%A7o_Velho]; Finds include decorated schist slabs [SUPPORTED: https://en.wikipedia.org/wiki/Caves_of_Po%C3%A7o_Velho]"}]'::jsonb),
    ('bf81babd-58bf-4bac-b5e9-fac36c10c95c'::uuid, 'card_description', 'A pyramid with a circular base aligned to the spring and fall equinoxes. Built by the Otomi people between the 6th and 9th centuries AD.', 'Cañada de la Virgen, an Otomi site in Guanajuato, was dedicated to the Moon, the Sun and Venus, as archaeoastronomical studies show. Its last occupation may tie to the Toltec expansion.', 'teaser-card-s020:bf81babd-58bf-4bac-b5e9-fac36c10c95c:card_description', 'teaser-card-s020 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', '05c33552c82232aab6cdbb491945c86b39699f9d24a23b116a4cd698df61a504|31c911f4b8cba3523a93a2ee5c6bd45ce6e58a590a7589cdf6d32bf1e5b1920a|31c911f4b8cba3523a93a2ee5c6bd45ce6e58a590a7589cdf6d32bf1e5b1920a', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cañada de la Virgen, an Otomi site in Guanajuato, was dedicated to the Moon, the Sun and Venus, as archaeoastronomical studies show. Its last occupation may tie to the Toltec expansion."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cañada de la Virgen is an Otomi site [S1]; the site is in Guanajuato [S2]; the site was dedicated to the Moon, the Sun and Venus [S3]; archaeoastronomical studies show this dedication [S3]; its last occupation may be tied to the Toltec expansion (a hedge) [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cañada de la Virgen is an archaeological site in Mexico [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1ada_de_la_Virgen]; The site is Otomi (built and used by the Otomi people) [SUPPORTED: https://lugares.inah.gob.mx/en/lugar-344]; The site is in Guanajuato [SUPPORTED: https://lugares.inah.gob.mx/en/lugar-344]; The site was dedicated to the Moon, the Sun and Venus [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1ada_de_la_Virgen]; Archaeoastronomical studies show this dedication [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1ada_de_la_Virgen]; Its last occupation may tie to the Toltec expansion [SUPPORTED: https://en.wikipedia.org/wiki/Ca%C3%B1ada_de_la_Virgen]"}]'::jsonb),
    ('bfa3495a-39f7-4ba8-a110-eff95d15f05c'::uuid, 'card_description', 'Dating 3700–3500 BC on Whitehawk Hill, this causewayed enclosure has ditches broken by deliberate gaps. Such earthworks served as meeting places or ritual arenas — the gaps remain unexplained.', 'Four roughly concentric ditches ring Whitehawk Camp near Brighton, a Neolithic causewayed enclosure probably built between 3650 and 3500 BC, where most pottery is plain or decorated bowls.', 'teaser-card-s020:bfa3495a-39f7-4ba8-a110-eff95d15f05c:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '5cb6d53d4cbe2ef946b9dca3ba1eff6f00db9d6947acc89e0fc342c3b56fa490|a15a11467e30600da5aed07bd64b7c6b6918ced562ad3792ff0bd244d5b0517c|a15a11467e30600da5aed07bd64b7c6b6918ced562ad3792ff0bd244d5b0517c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Four roughly concentric ditches ring Whitehawk Camp near Brighton, a Neolithic causewayed enclosure probably built between 3650 and 3500 BC, where most pottery is plain or decorated bowls."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site has four roughly concentric ditches [S2]; the ditches ring the camp [S2]; Whitehawk Camp is near Brighton [S1]; it is a causewayed enclosure [S1]; it is Neolithic [S5]; it was probably built between 3650 and 3500 BC (a hedge) [S5]; most of the pottery found there is plain or decorated bowls [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-067 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Whitehawk Camp is a causewayed enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Whitehawk_Camp]; It lies near Brighton [SUPPORTED: https://en.wikipedia.org/wiki/Whitehawk_Camp]; It is a Neolithic site (causewayed enclosures are early Neolithic earthworks) [SUPPORTED: https://en.wikipedia.org/wiki/Whitehawk_Camp]; It has four ditches [SUPPORTED: https://en.wikipedia.org/wiki/Whitehawk_Camp]; The four ditches are roughly concentric [SUPPORTED: https://en.wikipedia.org/wiki/Whitehawk_Camp]; It was probably built between 3650 and 3500 BC [SUPPORTED: https://en.wikipedia.org/wiki/Whitehawk_Camp]; Most of the pottery found is of the plain bowl type [SUPPORTED: https://en.wikipedia.org/wiki/Whitehawk_Camp]; Most of the pottery found is of the decorated bowl type [SUPPORTED: https://en.wikipedia.org/wiki/Whitehawk_Camp]"}]'::jsonb),
    ('c0526e60-577b-4f28-9a07-e3c5739984bd'::uuid, 'card_description', '1st-3rd century AD Roman encampment on the Old Rhine -- the northern frontier of the Empire. Named after Vipsania Agrippina, mother of Emperor Caligula. A key fort in the Cananefates tribal territory.', 'On the Old Rhine, on the northern border of the Roman Empire, Praetorium Agrippinae was an army camp at first fortified by a palisaded earthen wall and three moats. Digs found storehouses.', 'teaser-card-s020:c0526e60-577b-4f28-9a07-e3c5739984bd:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'dd319bea10696dd7bf0390a94b4e99d7b31c0a13042d7461308860c180694a2a|821616985229f3dccef0d4597ea17359833ea6c44cc1554b845733c1fa6ea974|821616985229f3dccef0d4597ea17359833ea6c44cc1554b845733c1fa6ea974', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the Old Rhine, on the northern border of the Roman Empire, Praetorium Agrippinae was an army camp at first fortified by a palisaded earthen wall and three moats. Digs found storehouses."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Praetorium Agrippinae lay on the Old Rhine [S2]; it lay on the northern border of the Roman Empire [S2]; it was an army camp [S2]; it was at first fortified by a palisaded earthen wall [S4]; it was at first fortified by three moats [S4]; excavations found storehouses [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-008 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Praetorium Agrippinae was an army camp (encampment, castellum) of the Roman Empire at modern Valkenburg, Netherlands [SUPPORTED: https://en.wikipedia.org/wiki/Praetorium_Agrippinae]; The camp lay on the Old Rhine [SUPPORTED: https://en.wikipedia.org/wiki/Praetorium_Agrippinae]; The camp lay on the northern border of the Roman Empire [SUPPORTED: https://en.wikipedia.org/wiki/Praetorium_Agrippinae]; The camp was at first fortified by a palisaded earthen wall [SUPPORTED: https://en.wikipedia.org/wiki/Praetorium_Agrippinae]; The first fortification also had three moats [SUPPORTED: https://nl.wikipedia.org/wiki/Praetorium_Agrippinae]; Excavations (digs) at the site found storehouses [SUPPORTED: https://en.wikipedia.org/wiki/Praetorium_Agrippinae]"}]'::jsonb),
    ('c0dce315-a1ed-4be6-8dd2-df515e754875'::uuid, 'card_description', 'The first buildings on the site were granaries, over 33 m long, apparently a supply base for the Roman army constructed in the early part of the conquest in 43 AD.', 'Near Chichester, Fishbourne Roman Palace was built around 75–80 AD, four wings around a formal courtyard garden. Many of its black and white mosaics were later overlaid with coloured work.', 'teaser-card-s020:c0dce315-a1ed-4be6-8dd2-df515e754875:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '0b6f78dc829b2b7bbd59e0c4175e32b62f6f52195fd727c3b830283ffa3e5e32|2a74b14735937cb35195fb72dc12e3735098e6d080d0e3d116f5a03c5fc70e33|2a74b14735937cb35195fb72dc12e3735098e6d080d0e3d116f5a03c5fc70e33', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Chichester, Fishbourne Roman Palace was built around 75–80 AD, four wings around a formal courtyard garden. Many of its black and white mosaics were later overlaid with coloured work."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Fishbourne Roman Palace is near Chichester [S1]; the palace was built around 75-80 AD [W1]; the palace has four wings [W1]; the wings surround a formal courtyard garden [W1]; many of the black and white mosaics were overlaid with coloured work [S2]; the overlaying came later than the original mosaics [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-009 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Fishbourne Roman Palace is a Roman palace (villa) [SUPPORTED: https://en.wikipedia.org/wiki/Fishbourne_Roman_Palace]; The palace is near Chichester [SUPPORTED: https://en.wikipedia.org/wiki/Fishbourne_Roman_Palace]; The palace was built around 75–80 AD [SUPPORTED: https://en.wikipedia.org/wiki/Fishbourne_Roman_Palace]; The palace had four wings [SUPPORTED: https://en.wikipedia.org/wiki/Fishbourne_Roman_Palace]; The four wings surrounded a courtyard garden that was formal [SUPPORTED: https://en.wikipedia.org/wiki/Fishbourne_Roman_Palace]; The palace had black and white mosaics [SUPPORTED: https://en.wikipedia.org/wiki/Fishbourne_Roman_Palace]; The black and white mosaics were later overlaid with coloured work (alterations in the second and third centuries AD) [SUPPORTED: https://en.wikipedia.org/wiki/Fishbourne_Roman_Palace]; Many (not all) of the black and white mosaics were overlaid [SUPPORTED: https://en.wikipedia.org/wiki/Fishbourne_Roman_Palace]"}, {"source": "web fact W1", "url": "https://en.wikipedia.org/wiki/Fishbourne_Roman_Palace", "quote": "The full-size palace with four residential wings surrounding a formal courtyard garden of 250 by 320 feet (75 by 100 metres) was built in around 75–80 AD"}]'::jsonb),
    ('c18ed010-6938-4961-83ff-0e9e6ec640c7'::uuid, 'card_description', 'The main part consists of a temple like structure used for religious and astronomical purposes.', 'Sóndor, its name possibly from the Quechua for meeting, was built by the Chanka people. Its main part is a temple-like structure used for religious and astronomical purposes.', 'teaser-card-s020:c18ed010-6938-4961-83ff-0e9e6ec640c7:card_description', 'teaser-card-s020 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', 'dbde87ba1ff0a4bd0ceff6fab22cf35a7f347c401d92a4879d03c71c450ad089|6eb0a3d69e9ce0f9ea835701983062d09fb8ff196fc07a7aca3b5815b7bdfac0|6eb0a3d69e9ce0f9ea835701983062d09fb8ff196fc07a7aca3b5815b7bdfac0', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Sóndor, its name possibly from the Quechua for meeting, was built by the Chanka people. Its main part is a temple-like structure used for religious and astronomical purposes."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the name Sóndor is possibly from the Quechua (a hedge) [S1]; the Quechua word means meeting [S1]; the site was built by the Chanka people [S1]; its main part is a temple-like structure [S2]; the structure was used for religious purposes [S2]; the structure was used for astronomical purposes [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Sóndor is an archaeological site in Peru (the central claim: an archaeological site, here a temple-like complex) [SUPPORTED: https://en.wikipedia.org/wiki/S%C3%B3ndor]; Sóndor''s name is possibly from the Quechua for meeting [SUPPORTED: https://en.wikipedia.org/wiki/S%C3%B3ndor]; Sóndor was built by the Chanka people [SUPPORTED: https://en.wikipedia.org/wiki/S%C3%B3ndor]; The main part of Sóndor is a temple-like structure [SUPPORTED: https://en.wikipedia.org/wiki/S%C3%B3ndor]; The temple-like structure was used for religious purposes [SUPPORTED: https://en.wikipedia.org/wiki/S%C3%B3ndor]; The temple-like structure was used for astronomical purposes [SUPPORTED: https://en.wikipedia.org/wiki/S%C3%B3ndor]"}]'::jsonb),
    ('c2984c15-07c8-4109-ad99-0ecc2e2e2d82'::uuid, 'card_description', 'Three stone circles set in a precise line on Bodmin Moor. The alignment is so deliberate it implies astronomical or ritual purpose, but which remains debated.', 'Three stone circles lie in a line on the eastern flank of Bodmin Moor: The Hurlers Stone Circles, their stones hammered smooth, with two standing stones called the Pipers just to the west.', 'teaser-card-s020:c2984c15-07c8-4109-ad99-0ecc2e2e2d82:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '893f1621b91a3e545d4959b98a8a8a2a4dbfab46f999046c326589e1914eb1b0|2dd4424bd0ff1f1f2afa6b46060b3cdda38acc0989b2a7c47388ab9cb12bd8ad|2dd4424bd0ff1f1f2afa6b46060b3cdda38acc0989b2a7c47388ab9cb12bd8ad', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Three stone circles lie in a line on the eastern flank of Bodmin Moor: The Hurlers Stone Circles, their stones hammered smooth, with two standing stones called the Pipers just to the west."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site consists of three stone circles [S1, S4]; the circles lie in a line [S4]; the site is on the eastern flank of Bodmin Moor [S2]; the stones are hammered smooth [S7]; two standing stones called the Pipers stand just to the west of the circles [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Hurlers Stone Circles are a group of three stone circles in Cornwall, England (the central claim: a prehistoric stone circle group) [SUPPORTED: https://en.wikipedia.org/wiki/The_Hurlers]; There are three stone circles [SUPPORTED: https://en.wikipedia.org/wiki/The_Hurlers]; The three stone circles lie in a line [SUPPORTED: https://en.wikipedia.org/wiki/The_Hurlers]; The site lies on the eastern flank of Bodmin Moor [SUPPORTED: https://en.wikipedia.org/wiki/The_Hurlers]; The stones of the circles were hammered smooth [SUPPORTED: https://en.wikipedia.org/wiki/The_Hurlers]; Two standing stones called the Pipers exist at the site [SUPPORTED: https://en.wikipedia.org/wiki/The_Hurlers]; The two Pipers stand just to the west of the circles [SUPPORTED: https://en.wikipedia.org/wiki/The_Hurlers]"}]'::jsonb),
    ('c2bbac8e-a9d7-44be-a639-1920ef0dc640'::uuid, 'card_description', 'A Hellenistic mausoleum built from an estimated 2,500 cubic metres of marble quarried locally near Ephesus. The sheer volume of stone rivals some of the grandest ancient tombs.', 'On an isolated hillside sits the Belevi Mausoleum, a Hellenistic tomb of two stories, second in size in Anatolia only to the Mausoleum of Halicarnassus, which it resembles.', 'teaser-card-s020:c2bbac8e-a9d7-44be-a639-1920ef0dc640:card_description', 'teaser-card-s020 (teaser-card): teaser card, 172 characters, checked PASS, web-verified VERIFIED', '8c30b497ccfd1c46592297063bc43edc028495dfd32a93a5ca3e5097c91543a9|543eae6b39031b13cba215a3a1886d00c623b79204eb3232d2a8e6f18e1f2a07|543eae6b39031b13cba215a3a1886d00c623b79204eb3232d2a8e6f18e1f2a07', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On an isolated hillside sits the Belevi Mausoleum, a Hellenistic tomb of two stories, second in size in Anatolia only to the Mausoleum of Halicarnassus, which it resembles."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the mausoleum sits on an isolated hillside [S2]; it is a Hellenistic monument tomb [S1]; it has two stories [S5]; it is the second largest mausoleum in Anatolia, after the Mausoleum of Halicarnassus [S3]; it resembles the Mausoleum of Halicarnassus [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Belevi Mausoleum is a tomb (a monument tomb) in Türkiye (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Belevi_Mausoleum]; The Belevi Mausoleum is Hellenistic [SUPPORTED: https://en.wikipedia.org/wiki/Belevi_Mausoleum]; The mausoleum sits on an isolated hillside [SUPPORTED: https://en.wikipedia.org/wiki/Belevi_Mausoleum]; The mausoleum has two stories [SUPPORTED: https://en.wikipedia.org/wiki/Belevi_Mausoleum]; It is the second largest mausoleum in Anatolia, after the Mausoleum of Halicarnassus [SUPPORTED: https://en.wikipedia.org/wiki/Belevi_Mausoleum]; It resembles the Mausoleum of Halicarnassus [SUPPORTED: https://en.wikipedia.org/wiki/Belevi_Mausoleum]"}]'::jsonb),
    ('c345810f-7f8d-4845-88c7-64c652fa34d1'::uuid, 'card_description', 'The earliest known settlement at Knossos dates to about 7000 BC, during the early Neolithic period.', 'Knossos lies on Kephala hill; its earliest known settlement dates to about 7000 BC and its first palace was built around 1900 BC. The Palace of Minos is the dominant archaeological feature.', 'teaser-card-s020:c345810f-7f8d-4845-88c7-64c652fa34d1:card_description', 'teaser-card-s020 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'ca6f23967f11f352a52d0719de80197716f50ea5601066664017581cf93d7b35|1851b7f2ed9bb0a826b6c1b29e08202830cbaa36c3cd1fd5c753d078efb54505|1851b7f2ed9bb0a826b6c1b29e08202830cbaa36c3cd1fd5c753d078efb54505', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Knossos lies on Kephala hill; its earliest known settlement dates to about 7000 BC and its first palace was built around 1900 BC. The Palace of Minos is the dominant archaeological feature."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Knossos lies on Kephala hill [S1]; its earliest known settlement dates to about 7000 BC [S2]; its first palace was built around 1900 BC [S3]; the Palace of Minos is the dominant archaeological feature [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Knossos is an archaeological site and ancient urban centre (a Minoan settlement with a palace) in Crete, Greece (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/Knossos]; Knossos lies on Kephala hill [SUPPORTED: https://en.wikipedia.org/wiki/Knossos]; The earliest known settlement at Knossos dates to about 7000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Knossos]; The first palace at Knossos was built around 1900 BC [SUPPORTED: https://en.wikipedia.org/wiki/Knossos]; The Palace of Minos is the dominant archaeological feature of the site [SUPPORTED: https://en.wikipedia.org/wiki/Knossos]"}]'::jsonb),
    ('c34bf073-ed1e-4626-8cc8-8cbd724d9b93'::uuid, 'card_description', 'The largest and heaviest prehistoric standing stone in Cornwall, weighing 16.5 tonnes. Made of Devonian shale with striking feldspar veining.', 'On the summit of St Breock Downs stands the St Breock Downs Monolith, the largest and heaviest prehistoric menhir in Cornwall, around 16.5 tonnes of shale set among quartz pebbles.', 'teaser-card-s020:c34bf073-ed1e-4626-8cc8-8cbd724d9b93:card_description', 'teaser-card-s020 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'd537f01d9662c02b42a35a97cbe4429092b5c7d4586cb09a7369c4bcdc955ae2|9b37fe1152c8a4d9d9d99625380bd698b36c363377cfaa6fcbadb492ba101abf|9b37fe1152c8a4d9d9d99625380bd698b36c363377cfaa6fcbadb492ba101abf', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the summit of St Breock Downs stands the St Breock Downs Monolith, the largest and heaviest prehistoric menhir in Cornwall, around 16.5 tonnes of shale set among quartz pebbles."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the monolith stands on the summit of St Breock Downs [S2]; it is the largest and heaviest prehistoric menhir in Cornwall [S1]; it weighs around 16.5 tonnes [S3]; it is made of shale [S3]; it is set among quartz pebbles [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-068 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The St Breock Downs Monolith is a prehistoric menhir (standing stone) in Cornwall, England (the central claim) [SUPPORTED: https://en.wikipedia.org/wiki/St_Breock_Downs_Monolith]; The monolith stands on the summit of St Breock Downs [SUPPORTED: https://en.wikipedia.org/wiki/St_Breock_Downs_Monolith]; It is the largest and heaviest prehistoric menhir in Cornwall [SUPPORTED: https://en.wikipedia.org/wiki/St_Breock_Downs_Monolith]; The stone is prehistoric [SUPPORTED: https://en.wikipedia.org/wiki/St_Breock_Downs_Monolith]; The stone weighs around 16.5 tonnes [SUPPORTED: https://en.wikipedia.org/wiki/St_Breock_Downs_Monolith]; The stone is made of shale [SUPPORTED: https://en.wikipedia.org/wiki/St_Breock_Downs_Monolith]; The stone is set among quartz pebbles [SUPPORTED: https://en.wikipedia.org/wiki/St_Breock_Downs_Monolith]"}]'::jsonb),
    ('c4ee2569-7555-47a2-8d4c-71fcae8468fb'::uuid, 'card_description', 'Two Neolithic long barrows near the Dorset Cursus. The unexcavated one, 44 by 18 m, still holds its secrets—its contents remain unknown.', 'On a ridge near the end of the Dorset Cursus lie the Thickthorn Down Long Barrows, two Neolithic mounds, each 2.4 metres high, one still unexcavated, both aligned north-west to south-east.', 'teaser-card-s020:c4ee2569-7555-47a2-8d4c-71fcae8468fb:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '2d1d9bf24afbec8cc321ca5f217159b80da0698b9c967eb18267ac70ccd06162|42781683d906d9493b758e4044908b44e4160ad9c9f80239f746c7a3fec833c0|42781683d906d9493b758e4044908b44e4160ad9c9f80239f746c7a3fec833c0', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a ridge near the end of the Dorset Cursus lie the Thickthorn Down Long Barrows, two Neolithic mounds, each 2.4 metres high, one still unexcavated, both aligned north-west to south-east."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the barrows lie on a ridge [S3]; they are near the end of the Dorset Cursus [S2, S5]; there are two long barrows [S1]; they are Neolithic [S1]; each is 2.4 metres high [S4, S7]; one is unexcavated [S4]; both are aligned north-west to south-east [S5, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Thickthorn Down Long Barrows are two Neolithic mounds (long barrows, a tomb type) in Dorset, England [SUPPORTED: https://en.wikipedia.org/wiki/Thickthorn_Down_Long_Barrows]; The barrows lie near the end of the Dorset Cursus [SUPPORTED: https://en.wikipedia.org/wiki/Thickthorn_Down_Long_Barrows]; The barrows lie on a ridge [SUPPORTED: https://en.wikipedia.org/wiki/Thickthorn_Down_Long_Barrows]; The north-western barrow is 2.4 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Thickthorn_Down_Long_Barrows]; The south-eastern barrow is also 2.4 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Thickthorn_Down_Long_Barrows]; One of the two barrows is still unexcavated [SUPPORTED: https://en.wikipedia.org/wiki/Thickthorn_Down_Long_Barrows]; The north-western barrow is aligned north-west to south-east [SUPPORTED: https://en.wikipedia.org/wiki/Thickthorn_Down_Long_Barrows]; The south-eastern barrow is also aligned north-west to south-east (so both are) [SUPPORTED: https://en.wikipedia.org/wiki/Thickthorn_Down_Long_Barrows]"}]'::jsonb),
    ('c50a5a61-0ce6-4e28-a525-b19a21140a30'::uuid, 'card_description', 'A diamond-shaped standing stone 3.7 metres tall and 2.8 metres wide, carved from local red sandstone conglomerate. Its age and purpose remain unknown — it stands alone on open moorland.', 'On moorland in the Brecon Beacons, Maen Llia rises 3.7 m high, a roughly diamond-shaped, partly moss-covered stone of conglomerate set on a purpose made mound of stone and earth.', 'teaser-card-s020:c50a5a61-0ce6-4e28-a525-b19a21140a30:card_description', 'teaser-card-s020 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '551cf723ee9800e54b0fdefb2bc8746e9e4837b77d031e7383861a3f1f137725|cfd8bc8ede1c7eacf1db20121043f153fc16a2588c3675fcff2b89f1a0c5e1c6|cfd8bc8ede1c7eacf1db20121043f153fc16a2588c3675fcff2b89f1a0c5e1c6', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On moorland in the Brecon Beacons, Maen Llia rises 3.7 m high, a roughly diamond-shaped, partly moss-covered stone of conglomerate set on a purpose made mound of stone and earth."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the stone stands on moorland [S1]; it is in the Brecon Beacons [S1]; it is 3.7 m high [S2]; it is roughly diamond-shaped [S3]; it is partly moss-covered [S3]; it is made of conglomerate [S2]; it sits on a purpose made mound of stone and earth [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Maen Llia is a standing stone (a megalithic monument) [SUPPORTED: https://en.wikipedia.org/wiki/Maen_Llia]; It stands on moorland in the Brecon Beacons [SUPPORTED: https://en.wikipedia.org/wiki/Maen_Llia]; The stone is 3.7 m high [SUPPORTED: https://en.wikipedia.org/wiki/Maen_Llia]; The stone is of conglomerate [SUPPORTED: https://en.wikipedia.org/wiki/Maen_Llia]; The stone is roughly diamond-shaped [SUPPORTED: https://en.wikipedia.org/wiki/Maen_Llia]; The stone is partly moss-covered [SUPPORTED: https://en.wikipedia.org/wiki/Maen_Llia]; The stone is set on a purpose-made mound of stone and earth [SUPPORTED: https://en.wikipedia.org/wiki/Maen_Llia]"}]'::jsonb),
    ('c65e3fb2-4e1d-43ca-8dab-1e751019985e'::uuid, 'card_description', 'A ringfort with 95 houses inside a 300-metre limestone wall with nine gates, built around 200 AD. Never permanently occupied -- only used occasionally.', 'On Öland, a limestone wall approximately 300 meters long, pierced by nine gates, rings Ismantorp Fortress, where 95 houses lie in 12 blocks around a central open area.', 'teaser-card-s020:c65e3fb2-4e1d-43ca-8dab-1e751019985e:card_description', 'teaser-card-s020 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', 'eb82f093b50aa977329c68fa64d455ccb29b350d96a71e1d9aa0c04cb1788357|821bd9a1d1ffcd5b4c3bcfb5446388fd52baca34dcaad4f51025d4a520106562|821bd9a1d1ffcd5b4c3bcfb5446388fd52baca34dcaad4f51025d4a520106562', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Öland, a limestone wall approximately 300 meters long, pierced by nine gates, rings Ismantorp Fortress, where 95 houses lie in 12 blocks around a central open area."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is on Öland [S1]; a limestone wall approximately 300 meters long rings the fortress [S2]; the wall has nine gates [S2]; there are 95 houses inside [S3]; the houses are arranged in 12 blocks [S3]; the blocks surround a central open area [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ismantorp Fortress is a ringfort (fortress) [SUPPORTED: https://en.wikipedia.org/wiki/Ismantorp_Fortress]; It is located on Öland [SUPPORTED: https://en.wikipedia.org/wiki/Ismantorp_Fortress]; The fortress is ringed by a limestone wall [SUPPORTED: https://en.wikipedia.org/wiki/Ismantorp_Fortress]; The wall is approximately 300 meters long [SUPPORTED: https://en.wikipedia.org/wiki/Ismantorp_Fortress]; The wall is pierced by nine gates [SUPPORTED: https://en.wikipedia.org/wiki/Ismantorp_Fortress]; Inside are 95 houses [SUPPORTED: https://en.wikipedia.org/wiki/Ismantorp_Fortress]; The houses lie in 12 blocks around a central open area [SUPPORTED: https://en.wikipedia.org/wiki/Ismantorp_Fortress]"}]'::jsonb),
    ('c663e466-6644-4d97-9fb5-24d85eddb646'::uuid, 'card_description', 'Paleolithic rock shelter with an engraved figure — trapezoid head ending in branch-like points, tail and erect phallus — interpreted as a sorcerer. Similar carvings appear in Spain and France.', 'At the Rock Shelter of Solhapa, an engraved human figure whose head ends in points like a pair of branches has been interpreted as a sorcerer, and bars inside run almost labyrinthine.', 'teaser-card-s020:c663e466-6644-4d97-9fb5-24d85eddb646:card_description', 'teaser-card-s020 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'b0cbe03b04f8f8764b4fdafc86af3bb64fb8735c4313885c8b79fdbebc3b67f5|fa5655637b1ff3b90319b55e757278cc4140be663c057801a51035c5ded0e3ce|fa5655637b1ff3b90319b55e757278cc4140be663c057801a51035c5ded0e3ce', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At the Rock Shelter of Solhapa, an engraved human figure whose head ends in points like a pair of branches has been interpreted as a sorcerer, and bars inside run almost labyrinthine."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the shelter has an engraved human figure [S2, S3]; the figure''s head ends in points resembling a pair of branches [S3]; the figure has been interpreted as a sorcerer [S2]; there are bars inside the shelter (interior walls or floor) [S4, S5]; the bars are almost labyrinthine [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Rock Shelter of Solhapa is a rock shelter (rock-art cave site) in Portugal [SUPPORTED: https://en.wikipedia.org/wiki/Rock_shelter_of_Solhapa]; It has an engraved human figure whose head ends in points like a pair of branches [SUPPORTED: https://en.wikipedia.org/wiki/Rock_shelter_of_Solhapa]; The engraved figure has been interpreted as a sorcerer [SUPPORTED: https://en.wikipedia.org/wiki/Rock_shelter_of_Solhapa]; Bars on the interior walls or floor run almost labyrinthine [SUPPORTED: https://en.wikipedia.org/wiki/Rock_shelter_of_Solhapa]; The interior carvings include straight, interconnected bars described as almost labyrinthine [SUPPORTED: https://en.wikipedia.org/wiki/Rock_shelter_of_Solhapa]"}]'::jsonb),
    ('c6ad2aac-55ba-4cce-92eb-86f9e72c8781'::uuid, 'card_description', 'Set on a western spur of the Clwydian Range near Llanbedr, this fort belongs to a chain of six where each summit could signal to the next — a coordinated warning network across the ridgeline.', 'On a spur of the Clwydian Range, Moel y Gaer, an Iron Age hillfort mostly ringed by a double bank and ditch, holds 15 roundhouse platforms, its inner rampart perhaps once stone-faced.', 'teaser-card-s020:c6ad2aac-55ba-4cce-92eb-86f9e72c8781:card_description', 'teaser-card-s020 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '90b0785725a6660c8bb8c9f0a37825dde94e7724901c2c224f35fe81702cbffd|a67d604ea75ee3b01a35487a815c237952e1054fbb17a1b0643e4512cf801c2d|a67d604ea75ee3b01a35487a815c237952e1054fbb17a1b0643e4512cf801c2d', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-023", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a spur of the Clwydian Range, Moel y Gaer, an Iron Age hillfort mostly ringed by a double bank and ditch, holds 15 roundhouse platforms, its inner rampart perhaps once stone-faced."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-023 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Moel y Gaer is on a spur of the Clwydian Range [S1]; it is an Iron Age hillfort [S1]; most of it is ringed by a double bank and ditch [S4]; it holds 15 roundhouse platforms [S8]; its inner rampart was perhaps once stone-faced (a hedge) [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-069 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Moel y Gaer, Llanbedr is a hillfort [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Llanbedr]; The hillfort is Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Llanbedr]; It lies on a spur of the Clwydian Range [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Llanbedr]; Most of the fort is ringed by a double bank and ditch [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Llanbedr]; The hillfort holds 15 roundhouse platforms [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Llanbedr]; The inner rampart was perhaps once stone-faced [SUPPORTED: https://en.wikipedia.org/wiki/Moel_y_Gaer,_Llanbedr]"}]'::jsonb),
    ('c70a32fa-651a-4a64-b09b-abd2bcf0974a'::uuid, 'card_description', 'A 4th-century fortress that became Goguryeo''s capital in 427 AD. The move from the old fortress signalled a shift in Korean power southward.', 'Attacked by Geunchogo of Baekje in 375, Pyongyang Castle became the Goguryeo capital in 427, when Jangsu moved it here from Gungnae Fortress. Today it is a National Treasure.', 'teaser-card-s020:c70a32fa-651a-4a64-b09b-abd2bcf0974a:card_description', 'teaser-card-s020 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '29c718a45ddfeb14ab4467aa6cae7b8db53a84bfd59bd7d232898f972b95e29c|cb48e139f00e857cbd6253924855c2308cae73d028f693cba105ce37c5254e3f|cb48e139f00e857cbd6253924855c2308cae73d028f693cba105ce37c5254e3f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Attacked by Geunchogo of Baekje in 375, Pyongyang Castle became the Goguryeo capital in 427, when Jangsu moved it here from Gungnae Fortress. Today it is a National Treasure."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pyongyang Castle was attacked by Geunchogo of Baekje [S2]; the attack happened in 375 [S2]; Pyongyang Castle became the Goguryeo capital [S3]; this happened in 427 [S3]; Jangsu moved the capital to Pyongyang Castle [S3]; the capital was moved from Gungnae Fortress [S3]; the castle is a National Treasure (of North Korea) [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pyongyang Castle is a castle (fortress) in Pyongyang, North Korea [SUPPORTED: https://en.wikipedia.org/wiki/Pyongyang_Castle]; The castle was attacked by Geunchogo of Baekje (attacker and king named) [SUPPORTED: https://en.wikipedia.org/wiki/Pyongyang_Castle]; The attack by Geunchogo happened in 375 [SUPPORTED: https://en.wikipedia.org/wiki/Pyongyang_Castle]; Pyongyang Castle became the Goguryeo capital [SUPPORTED: https://en.wikipedia.org/wiki/Pyongyang_Castle]; Pyongyang Castle became the Goguryeo capital in 427 [SUPPORTED: https://en.wikipedia.org/wiki/Pyongyang_Castle]; It was Jangsu (of Goguryeo) who moved the capital to Pyongyang Castle [SUPPORTED: https://en.wikipedia.org/wiki/Pyongyang_Castle]; The capital was moved from Gungnae Fortress [SUPPORTED: https://en.wikipedia.org/wiki/Pyongyang_Castle]; Today Pyongyang Castle is a National Treasure (of North Korea) [SUPPORTED: https://en.wikipedia.org/wiki/Pyongyang_Castle]"}]'::jsonb),
    ('c70f123f-bf31-4408-8204-1b8ef717e0dd'::uuid, 'card_description', 'Occupied 50 BC to 5th century AD, starting as a late Iron Age settlement before Roman construction created a large villa. Its finds are displayed in a deconsecrated 1851 chapel on the village edge.', 'Workmen digging for limestone in 1781 rediscovered Piddington Roman Villa, a winged-corridor villa whose 2nd-century well is probably the largest stone-lined well in Roman Britain.', 'teaser-card-s020:c70f123f-bf31-4408-8204-1b8ef717e0dd:card_description', 'teaser-card-s020 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'a4f6a1c400acb9357123f5de6650467ba72dca845b720ff5c257816f9ea0e0ee|2ed121fe4d621312e4244eac016ce9da72b7245786ee3e564fe8b75bb3ec8aed|2ed121fe4d621312e4244eac016ce9da72b7245786ee3e564fe8b75bb3ec8aed', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Workmen digging for limestone in 1781 rediscovered Piddington Roman Villa, a winged-corridor villa whose 2nd-century well is probably the largest stone-lined well in Roman Britain."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "workmen were digging for limestone when they rediscovered the site [S6]; the rediscovery happened in 1781 [S6]; the site is Piddington Roman Villa, a Roman villa [S1]; it became a winged-corridor-type villa [S5]; the villa has a 2nd-century well [S5]; the well is probably the largest stone-lined well in Roman Britain [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Piddington Roman Villa is a Roman villa at Piddington, Northamptonshire, England [SUPPORTED: https://en.wikipedia.org/wiki/Piddington_Roman_Villa]; The site was rediscovered by workmen digging for limestone [SUPPORTED: https://en.wikipedia.org/wiki/Piddington_Roman_Villa]; The rediscovery by the limestone workmen happened in 1781 [SUPPORTED: https://her.northamptonshire.gov.uk/Monument/MNN9060]; The villa is a winged-corridor villa [SUPPORTED: https://en.wikipedia.org/wiki/Piddington_Roman_Villa]; The villa has a well dating to the 2nd century [SUPPORTED: https://en.wikipedia.org/wiki/Piddington_Roman_Villa]; The well is stone-lined [SUPPORTED: https://en.wikipedia.org/wiki/Piddington_Roman_Villa]; The well is probably the largest stone-lined well in Roman Britain (superlative, hedged with probably) [SUPPORTED: https://en.wikipedia.org/wiki/Piddington_Roman_Villa]"}]'::jsonb),
    ('c8529ed4-208b-45d2-9e75-58a5c3022c82'::uuid, 'card_description', 'Capital of ancient Gandhara from 1400 BC, later an Achaemenid regional capital. Alexander the Great''s army passed through here during its march into the Indian subcontinent.', NULL, 'teaser-card-s020:c8529ed4-208b-45d2-9e75-58a5c3022c82:card_description', 'teaser-card-s020 (card-clear-unproven-after-verify): card cleared (unproven-after-verify)', '||8bf9a7d0b91528211506fa1e838a7078a0829f07f96839565e459930fec39843', '[{"source": "lane WB run wb-ws-2026-09-27-06: unproven-after-verify", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The web check could not prove: Pushkalavati was once the capital of ancient Gandhara; The web check could not prove: The ruins lie on the banks of the Jindi River; The web check could not prove: Pushkalavati is an ancient city, now ruins, in Pakistan"}]'::jsonb),
    ('c87764f1-460f-46b0-8fc3-ddd115a6c9f3'::uuid, 'card_description', 'One of only two intact Assyrian obelisks ever found, dating to about 1000 BC. Its carved reliefs depict military campaigns and tribute from conquered peoples.', 'Unearthed at Nineveh in 1853, the White Obelisk is one of only two intact Assyrian obelisks to survive, its four sides carved in eight rows of panels: a king on campaign and at leisure.', 'teaser-card-s020:c87764f1-460f-46b0-8fc3-ddd115a6c9f3:card_description', 'teaser-card-s020 (teaser-card): teaser card, 185 characters, checked PASS, web-verified VERIFIED', 'ceac636b3e7d4585562ad3ca2cb28e5233465eaa1ffbefedfef2588ce8697fda|1e3e41153308863b9e2b5c44594fd3aef512289bb7f6b3522b9ce62e31a108ad|1e3e41153308863b9e2b5c44594fd3aef512289bb7f6b3522b9ce62e31a108ad', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Unearthed at Nineveh in 1853, the White Obelisk is one of only two intact Assyrian obelisks to survive, its four sides carved in eight rows of panels: a king on campaign and at leisure."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the White Obelisk was unearthed at Nineveh [S1, S2]; it was unearthed in 1853 [S2]; it is one of only two intact Assyrian obelisks to survive [S2]; it has four sides [S4, S6]; its sides are carved (relief carvings) [S4, S5]; each side has eight rows of panels [S6]; the carvings show a king on campaign [S5]; the carvings show the king at leisure (recreational activities) [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-070 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The White Obelisk is a carved stone obelisk found at Nineveh, Iraq [SUPPORTED: https://en.wikipedia.org/wiki/White_Obelisk]; The White Obelisk is an Assyrian monument (Neo-Assyrian) [SUPPORTED: https://en.wikipedia.org/wiki/White_Obelisk]; It was unearthed at Nineveh [SUPPORTED: https://en.wikipedia.org/wiki/White_Obelisk]; The White Obelisk was unearthed in 1853 [SUPPORTED: https://en.wikipedia.org/wiki/White_Obelisk]; It is one of only two intact Assyrian obelisks to survive [SUPPORTED: https://en.wikipedia.org/wiki/White_Obelisk]; The obelisk has four carved sides [SUPPORTED: https://en.wikipedia.org/wiki/White_Obelisk]; Each side carries eight rows of panels [SUPPORTED: https://en.wikipedia.org/wiki/White_Obelisk]; The panels show a king on campaign [SUPPORTED: https://en.wikipedia.org/wiki/White_Obelisk]; The panels show the king at leisure (recreational activities, hunting, banquets) [SUPPORTED: https://en.wikipedia.org/wiki/White_Obelisk]"}]'::jsonb),
    ('c889f267-d523-4253-8bc4-ec3eec0244c2'::uuid, 'card_description', 'Called the "fourth pyramid of Giza," this two-stepped Fourth Dynasty tomb was built for Queen Khentkawes I — whose royal title "King of Upper and Lower Kemet" still divides scholars.', 'At Giza, the Tomb of Queen Khentkawes I was encased in fine white Tura limestone, and a chapel built into its superstructure had a large granite entrance bearing the queen''s name and titles.', 'teaser-card-s020:c889f267-d523-4253-8bc4-ec3eec0244c2:card_description', 'teaser-card-s020 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', 'd5b52b60215d9b50fa5b3963890f22e19f4615b3446ba92d680e432b04a19808|cdc22ccf22b1113ae9cb866fa413c78ad5d74d82c6e3c0a3329608a70f5f7ba6|cdc22ccf22b1113ae9cb866fa413c78ad5d74d82c6e3c0a3329608a70f5f7ba6', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Giza, the Tomb of Queen Khentkawes I was encased in fine white Tura limestone, and a chapel built into its superstructure had a large granite entrance bearing the queen''s name and titles."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the tomb is at Giza [S1]; the tomb was encased in fine white Tura limestone [S2]; a chapel was built into the tomb superstructure [S4]; the chapel had a large granite entrance [S4]; the entrance bears the queen''s name and titles [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-009 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Tomb of Queen Khentkawes I is a tomb [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_I]; The tomb is at Giza [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_I]; The tomb was encased in fine white Tura limestone [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_I]; A chapel was built into the tomb''s superstructure [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_I]; The chapel had a large granite entrance [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_I]; The entrance bore the queen''s name and titles [SUPPORTED: https://en.wikipedia.org/wiki/Pyramid_of_Khentkaus_I]"}]'::jsonb),
    ('c97527d0-4640-4b04-9bd6-132fcb6fd17d'::uuid, 'card_description', 'A massive temple complex from 1400 BC dedicated not to a god but to the rejuvenation of kingship itself. A mosque built inside it during the Medieval period is still in active use today.', 'On the Nile''s east bank, Luxor Temple was built around 1400 BC of sandstone from the Gebel el-Silsila area, with parts by Tutankhamun. In the Roman era it was a legionary fortress.', 'teaser-card-s020:c97527d0-4640-4b04-9bd6-132fcb6fd17d:card_description', 'teaser-card-s020 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '58d5cf7a650fe3a34f8391a00adbb212dd0ef6d9581d8e719d4aa3adfdbaf301|1e16a6966d41084a416104e2d7266f70d3a1ce399f1599de7dd8256bdd85ec4f|1e16a6966d41084a416104e2d7266f70d3a1ce399f1599de7dd8256bdd85ec4f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the Nile''s east bank, Luxor Temple was built around 1400 BC of sandstone from the Gebel el-Silsila area, with parts by Tutankhamun. In the Roman era it was a legionary fortress."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the temple is on the Nile''s east bank [S1]; it was built around 1400 BC [S1]; it was built of sandstone from the Gebel el-Silsila area [S7]; parts of it were built by Tutankhamun [S5]; in the Roman era it was a legionary fortress [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Luxor Temple is an ancient Egyptian temple (complex) on the east bank of the Nile, in Luxor [SUPPORTED: https://en.wikipedia.org/wiki/Luxor_Temple]; Luxor Temple was built around 1400 BC [SUPPORTED: https://en.wikipedia.org/wiki/Luxor_Temple]; Luxor Temple was built of sandstone from the Gebel el-Silsila area [SUPPORTED: https://en.wikipedia.org/wiki/Luxor_Temple]; Parts of Luxor Temple were built by Tutankhamun [SUPPORTED: https://en.wikipedia.org/wiki/Luxor_Temple]; In the Roman era Luxor Temple was a legionary fortress [SUPPORTED: https://en.wikipedia.org/wiki/Luxor_Temple]"}]'::jsonb),
    ('cb2aa656-31dd-41f5-915c-f946d5bbfefd'::uuid, 'card_description', 'Kuntur Wasi is thought to have been occupied between 1100-50 BCE, being initially constructed around 1100-900 BCE.', 'On La Copa hill, roughly 2,300 meters up in the Andean highlands, the ruins of Kuntur Wasi hold a hill-top temple and a sunken courtyard. Its first excavation uncovered four more monoliths.', 'teaser-card-s020:cb2aa656-31dd-41f5-915c-f946d5bbfefd:card_description', 'teaser-card-s020 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '22f694b2956a51a83e2868ea75dd99af5501229a0dcb0b3f164366183e67d8e3|5f5823a285fa1786cce91abf82fa10760ea75b32dab98fa27a12d0f0ba7f9c6e|5f5823a285fa1786cce91abf82fa10760ea75b32dab98fa27a12d0f0ba7f9c6e', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On La Copa hill, roughly 2,300 meters up in the Andean highlands, the ruins of Kuntur Wasi hold a hill-top temple and a sunken courtyard. Its first excavation uncovered four more monoliths."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is on La Copa hill [S2]; it lies roughly 2,300 meters above sea level [S3]; it is in the Andean highlands [S1, S2]; Kuntur Wasi consists of ruins [S1]; the ruins hold a hill-top temple [S4]; the ruins hold a sunken courtyard [S4]; the first (initial) excavation uncovered four more monoliths [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Kuntur Wasi is the ruins of a religious center (a temple site) in the Andean highlands of Peru [SUPPORTED: https://en.wikipedia.org/wiki/Kuntur_Wasi]; Kuntur Wasi is on La Copa hill [SUPPORTED: https://en.wikipedia.org/wiki/Kuntur_Wasi]; The site is roughly 2,300 meters above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Kuntur_Wasi]; The ruins hold a hill-top temple [SUPPORTED: https://en.wikipedia.org/wiki/Kuntur_Wasi]; The ruins hold a sunken courtyard [SUPPORTED: https://en.wikipedia.org/wiki/Kuntur_Wasi]; Monoliths were found at the site before its first excavation (the first excavation uncovered ''more'' monoliths) [SUPPORTED: https://en.wikipedia.org/wiki/Kuntur_Wasi]; The first (initial) excavation uncovered four monoliths [SUPPORTED: https://en.wikipedia.org/wiki/Kuntur_Wasi]"}]'::jsonb),
    ('cb4e0159-7d70-4981-900a-908015803e7b'::uuid, 'card_description', 'Slightly trapezoidal and roughly 70 metres long, this unchambered long barrow near Boughton Aluph was built in the Early Neolithic. No burial chamber was found — it is solid earthen fill.', 'West of the River Stour, near Boughton Aluph in Kent, Jacket''s Field Long Barrow is an earthen mound flanked by side ditches, probably raised in the fourth millennium BCE.', 'teaser-card-s020:cb4e0159-7d70-4981-900a-908015803e7b:card_description', 'teaser-card-s020 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', '5b5c1a152f5217b0d62844cbaa05b6adef8b9994ed7b4f0642e38f764f19b872|04f5d12a9ed2e0f30b387e0e258566f2532141262c314313e028c4b6fffa2ccb|04f5d12a9ed2e0f30b387e0e258566f2532141262c314313e028c4b6fffa2ccb', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "West of the River Stour, near Boughton Aluph in Kent, Jacket''s Field Long Barrow is an earthen mound flanked by side ditches, probably raised in the fourth millennium BCE."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the barrow lies west of the River Stour [S4, S5]; it is near Boughton Aluph in Kent [S1]; it is an earthen mound [S3]; it is flanked by side ditches [S3]; it was probably raised in the fourth millennium BCE [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Jacket''s Field Long Barrow is a long barrow (a tomb mound) [SUPPORTED: https://en.wikipedia.org/wiki/Jacket%27s_Field_Long_Barrow]; It is near Boughton Aluph in Kent, England [SUPPORTED: https://en.wikipedia.org/wiki/Jacket%27s_Field_Long_Barrow]; It lies west of the River Stour [SUPPORTED: https://en.wikipedia.org/wiki/Jacket%27s_Field_Long_Barrow]; It is an earthen mound (built out of earth) [SUPPORTED: https://en.wikipedia.org/wiki/Jacket%27s_Field_Long_Barrow]; The mound is flanked by side ditches [SUPPORTED: https://en.wikipedia.org/wiki/Jacket%27s_Field_Long_Barrow]; It was probably raised in the fourth millennium BCE [SUPPORTED: https://en.wikipedia.org/wiki/Jacket%27s_Field_Long_Barrow]"}]'::jsonb),
    ('cb637b1a-4f1b-4856-815f-67f2424a717f'::uuid, 'card_description', '700-1200 AD Polynesian site on Huahine, waterlogged enough to preserve wooden patu clubs, canoe parts, and adze handles — rare organic artefacts in Polynesian archaeology.', 'The waterlogged ground of Fa''ahia on Huahine kept wooden hand clubs, canoe parts and adze handles, beside the bones of birds now extinct, such as the Huahine starling and Sinoto''s lorikeet.', 'teaser-card-s020:cb637b1a-4f1b-4856-815f-67f2424a717f:card_description', 'teaser-card-s020 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', '3578fd881cccdfdf4994ca7ff4549fae55a9d841f57e65acc518ceca868be373|8c095661bbec4e0d6019f545061043c7494680a21de86545b9d8221b03e4a5bd|8c095661bbec4e0d6019f545061043c7494680a21de86545b9d8221b03e4a5bd', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The waterlogged ground of Fa''ahia on Huahine kept wooden hand clubs, canoe parts and adze handles, beside the bones of birds now extinct, such as the Huahine starling and Sinoto''s lorikeet."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Fa''ahia is on Huahine [S1]; much of the site is waterlogged [S3]; the waterlogged conditions preserved wooden hand clubs [S3]; the waterlogged conditions preserved canoe parts [S3]; the waterlogged conditions preserved adze handles [S3]; bird bones were preserved at the site [S4]; the birds are extinct [S6]; the Huahine starling and Sinoto''s lorikeet are among the extinct birds found at the site [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-071 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Fa''ahia is an early Polynesian occupation (archaeological) site on the island of Huahine [SUPPORTED: https://en.wikipedia.org/wiki/Fa%CA%BBahia]; Much of the site is waterlogged, which preserved organic artefacts [SUPPORTED: https://en.wikipedia.org/wiki/Fa%CA%BBahia]; The site kept wooden hand clubs [SUPPORTED: https://en.wikipedia.org/wiki/Fa%CA%BBahia]; The site kept canoe parts [SUPPORTED: https://en.wikipedia.org/wiki/Fa%CA%BBahia]; The site kept adze handles [SUPPORTED: https://en.wikipedia.org/wiki/Fa%CA%BBahia]; Bird bones were preserved at the site, beside those artefacts [SUPPORTED: https://en.wikipedia.org/wiki/Fa%CA%BBahia]; The Huahine starling was found at Fa''ahia [SUPPORTED: https://en.wikipedia.org/wiki/Huahine_starling]; The Huahine starling is now extinct [SUPPORTED: https://en.wikipedia.org/wiki/Huahine_starling]; Sinoto''s lorikeet was found at Fa''ahia [SUPPORTED: https://en.wikipedia.org/wiki/Fa%CA%BBahia]; Sinoto''s lorikeet is now (globally) extinct [SUPPORTED: https://en.wikipedia.org/wiki/Fa%CA%BBahia]"}]'::jsonb),
    ('cb672d70-399c-4bf5-8032-3259832f53eb'::uuid, 'card_description', 'An early Neolithic house was found that would have had wooden walls, marked by post holes.', 'At Chevdar, post holes mark an early Neolithic house that would have had wooden walls, plastered with clay. A hearth''s remains and carbonised emmer, barley and bitter vetch seeds were found.', 'teaser-card-s020:cb672d70-399c-4bf5-8032-3259832f53eb:card_description', 'teaser-card-s020 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '69eb3f1b3f51d07e7ce6e39d0289fb16f032d454afdf4d12a581fc7eb1f05c48|67e91742b03587fd5ad462b23b4e22ea9d138a62806b654562d06bdd1477d64f|67e91742b03587fd5ad462b23b4e22ea9d138a62806b654562d06bdd1477d64f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Chevdar, post holes mark an early Neolithic house that would have had wooden walls, plastered with clay. A hearth''s remains and carbonised emmer, barley and bitter vetch seeds were found."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is Chevdar [S1]; post holes mark a house [S2]; the house is early Neolithic [S2]; the house would have had wooden walls (hedged) [S2]; the house was plastered with clay [S3]; the remains of a hearth were found [S3]; carbonised emmer seeds were found [S4]; carbonised barley seeds were found [S4]; carbonised bitter vetch seeds were found [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-009 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Chevdar is a Neolithic archaeological site [SUPPORTED: https://en.wikipedia.org/wiki/Chevdar]; Chevdar is in Bulgaria [SUPPORTED: https://en.wikipedia.org/wiki/Chevdar]; An early Neolithic house was found at Chevdar [SUPPORTED: https://en.wikipedia.org/wiki/Chevdar]; Post holes mark the house [SUPPORTED: https://en.wikipedia.org/wiki/Chevdar]; The house would have had wooden walls [SUPPORTED: https://en.wikipedia.org/wiki/Chevdar]; The walls were plastered with clay [SUPPORTED: https://en.wikipedia.org/wiki/Chevdar]; The remains of a hearth were found [SUPPORTED: https://en.wikipedia.org/wiki/Chevdar]; Carbonised emmer seeds were found [SUPPORTED: https://en.wikipedia.org/wiki/Chevdar]; Carbonised barley seeds were found [SUPPORTED: https://en.wikipedia.org/wiki/Chevdar]; Carbonised bitter vetch seeds were found [SUPPORTED: https://en.wikipedia.org/wiki/Chevdar]"}]'::jsonb),
    ('cb95c838-ea7e-485c-8c7f-4f00427c04e1'::uuid, 'card_description', 'The old trading town on Helgö began to emerge around the year 200 AD, 500 years before Birka at Björkö.', 'On Helgö, an island in Lake Mälaren, a trading town rose around 200 AD. Among its finds: a small Buddha statuette from North India and a christening scoop from Egypt, both 6th century.', 'teaser-card-s020:cb95c838-ea7e-485c-8c7f-4f00427c04e1:card_description', 'teaser-card-s020 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'f1b123c0cbce2e50c8e41413b67e48e4cf9cc8393285ac73fc31412bb51b90ce|d6944bb5f256cd8ece16096e3efd75d45fb53aeade66eb350b26c81b3ca39524|d6944bb5f256cd8ece16096e3efd75d45fb53aeade66eb350b26c81b3ca39524', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On Helgö, an island in Lake Mälaren, a trading town rose around 200 AD. Among its finds: a small Buddha statuette from North India and a christening scoop from Egypt, both 6th century."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Helgö is an island [S1]; it lies in Lake Mälaren [S2]; a trading town emerged on it around 200 AD [S4]; finds include a small Buddha statuette from North India [S6]; finds include a christening scoop from Egypt [S6]; both date to the 6th century [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Helgö is an island in Lake Mälaren, Sweden [SUPPORTED: https://en.wikipedia.org/wiki/Helg%C3%B6]; The site is an ancient trading town (settlement) on Helgö [SUPPORTED: https://sv.wikipedia.org/wiki/Helg%C3%B6]; The trading town on Helgö began to emerge around 200 AD [SUPPORTED: https://en.wikipedia.org/wiki/Helg%C3%B6]; Among the finds is a small Buddha statuette from North India [SUPPORTED: https://en.wikipedia.org/wiki/Helg%C3%B6]; Among the finds is a christening scoop from Egypt [SUPPORTED: https://en.wikipedia.org/wiki/Helg%C3%B6]; The Buddha statuette and the scoop both date from the 6th century [SUPPORTED: https://sv.wikipedia.org/wiki/Helg%C3%B6]"}]'::jsonb),
    ('cca3b72c-8ad4-481b-838f-64bc69cf11a0'::uuid, 'card_description', 'The largest surviving group of Roman barrows in Britain, from the 1st–2nd century AD. Six burial mounds line the old Great North Road.', 'For almost two thousand years, travellers along the Roman road that eventually became the Great North Road have passed Six Hills, a collection of Roman barrows in Stevenage, Hertfordshire.', 'teaser-card-s020:cca3b72c-8ad4-481b-838f-64bc69cf11a0:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'd9ec87d822936ffecd443ec6e518af72521f1ebfe9c89ec09d3fc454e10088a5|8da0d34bf0105034ccce992d4ef0f4e4a533af9be9191e6083c5387f27d94de3|8da0d34bf0105034ccce992d4ef0f4e4a533af9be9191e6083c5387f27d94de3', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-003", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "For almost two thousand years, travellers along the Roman road that eventually became the Great North Road have passed Six Hills, a collection of Roman barrows in Stevenage, Hertfordshire."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-003 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "for almost two thousand years travellers have passed the Six Hills [S4]; the travellers went along a Roman road [S4]; the Roman road eventually became the Great North Road [S4]; Six Hills is a collection of Roman barrows [S1]; Six Hills is in Stevenage, Hertfordshire [S1]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-009 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Six Hills is a collection of Roman barrows [SUPPORTED: https://en.wikipedia.org/wiki/Six_Hills]; Six Hills is in Stevenage [SUPPORTED: https://en.wikipedia.org/wiki/Six_Hills]; Stevenage is in Hertfordshire [SUPPORTED: https://en.wikipedia.org/wiki/Six_Hills]; A Roman road eventually became the Great North Road [SUPPORTED: https://en.wikipedia.org/wiki/Six_Hills]; Travellers along that road have passed Six Hills for almost two thousand years [SUPPORTED: https://en.wikipedia.org/wiki/Six_Hills]"}]'::jsonb),
    ('cd8a601a-db65-43d3-82a5-afd0d7cf3e8f'::uuid, 'card_description', 'Following a sinuous path, at 85 km the aqueduct of the Gier is the longest known of the Roman aqueducts.', 'Winding 85 km from the Massif du Pilat to Lyon, the Aqueduct of the Gier passes through 11 tunnels and crosses deep river valleys on pipe bridges raised on high arches.', 'teaser-card-s020:cd8a601a-db65-43d3-82a5-afd0d7cf3e8f:card_description', 'teaser-card-s020 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', '1e65188f3f261638ed87baba44d87a2f92ee34c58ec9cc2a05dbb7aa6866e7ba|e493913ab48364eab275a67d77edad8f26fb89cf28f198b936678cbf53cc4faf|e493913ab48364eab275a67d77edad8f26fb89cf28f198b936678cbf53cc4faf', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Winding 85 km from the Massif du Pilat to Lyon, the Aqueduct of the Gier passes through 11 tunnels and crosses deep river valleys on pipe bridges raised on high arches."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Aqueduct of the Gier is an aqueduct [S1]; it follows a winding (sinuous) path [S1]; it is 85 km long [S1]; it starts from the Massif du Pilat [S2]; it runs to Lyon [S2]; it passes through 11 tunnels [S5]; it crosses deep river valleys [S6]; it crosses the valleys on pipe bridges [S6]; the pipe bridges are raised on high arches [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Aqueduct of the Gier is an ancient Roman aqueduct supplying Lyon (France) [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_the_Gier]; The aqueduct is 85 km long [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_the_Gier]; The aqueduct winds (follows a sinuous path) [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_the_Gier]; The aqueduct starts in the Massif du Pilat [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_the_Gier]; The aqueduct ends at Lyon [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_the_Gier]; The aqueduct passes through 11 tunnels [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_the_Gier]; It crosses deep river valleys [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_the_Gier]; It crosses the valleys on pipe bridges [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_the_Gier]; The pipe bridges are raised on high arches [SUPPORTED: https://en.wikipedia.org/wiki/Aqueduct_of_the_Gier]"}]'::jsonb),
    ('cdd96b01-efff-4896-acca-a97484a9f87c'::uuid, 'card_description', 'The Corieltauvi tribe — migrants from mainland Europe — built the Salt Road below Shilton Hill to move salt across Leicestershire, then settled the hill above it.', 'Earl Shilton grew up on Shilton Hill, above an ancient trackway called the Salt Road. William the Conqueror granted the village, then Scheltone, to Hugh de Grandmesnil.', 'teaser-card-s020:cdd96b01-efff-4896-acca-a97484a9f87c:card_description', 'teaser-card-s020 (teaser-card): teaser card, 168 characters, checked PASS, web-verified VERIFIED', 'c900fed40eff087e2de66ac43a3dacf3d1ec0b25b6367aeb45130fe02e233722|65c4b7717ae17a4497f8d825153cc9afd00ae521fec8c01d0d0cfa19c742c4c7|65c4b7717ae17a4497f8d825153cc9afd00ae521fec8c01d0d0cfa19c742c4c7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-024", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Earl Shilton grew up on Shilton Hill, above an ancient trackway called the Salt Road. William the Conqueror granted the village, then Scheltone, to Hugh de Grandmesnil."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-024 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the village of Earl Shilton grew up (evolved) on Shilton Hill [S1]; an ancient trackway called the Salt Road ran below the hill [S2]; William the Conqueror granted the village to Hugh de Grandmesnil [S5]; the village was then called Scheltone [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-072 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Earl Shilton is a market town (formerly village) in Leicestershire, England [SUPPORTED: https://en.wikipedia.org/wiki/Earl_Shilton]; The village of Earl Shilton grew up on Shilton Hill [SUPPORTED: https://en.wikipedia.org/wiki/Earl_Shilton]; Below the hill ran an ancient trackway called the Salt Road [SUPPORTED: https://www.genuki.org.uk/big/eng/LEI/EarlShilton]; William the Conqueror granted the village of Scheltone (now Earl Shilton) to Hugh de Grandmesnil [SUPPORTED: https://en.wikipedia.org/wiki/Earl_Shilton]; The village was then called Scheltone [SUPPORTED: https://www.genuki.org.uk/big/eng/LEI/EarlShilton]"}]'::jsonb),
    ('cdecef79-7895-4765-af67-14e60868a220'::uuid, 'card_description', '500-1445 AD. Carved 22 km from Tacna - fighting, dancing, and hunting scenes in low relief. Spanning nearly a thousand years of carving, Miculla ranks among the most-visited rock art in the region.', NULL, 'teaser-card-s020:cdecef79-7895-4765-af67-14e60868a220:card_description', 'teaser-card-s020 (card-clear-failed-after-verify-rewrite): card cleared (failed-after-verify-rewrite)', '||eb89a564e7ccc575c129507455a931badcb3de3161aaf45c8ed88b4aa8c146e5', '[{"source": "lane WB run wb-ws-2026-09-27-06: failed-after-verify-rewrite", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The web check could not prove: The site lies about 22 km from Tacna; The web check could not prove: The petroglyphs show people dancing and hunting animals; The web check could not prove: The age of the petroglyphs is uncertain (implied by the hedge ''many believe''); No sentence of the description supports the claim: the identity of the carver is unknown or unnamed (implied by ''someone cut''); No sentence of the description supports the claim: the figures are faint or hard to spot and need close looking (implied by ''Look closely, and find''); The tone rules are broken (see the checker''s reasons).; ''the figures that someone cut into the stone'' implies the carver is unknown or unnamed; no sentence says who carved the figures or that this is unknown, so say ''carved'' without an unnamed agent.; ''Look closely, and find the figures'' implies the figures are faint or hard to spot; no sentence says so, so drop that implication."}]'::jsonb),
    ('ce8a19e4-c1b3-42e6-9bf9-4eb5600c0650'::uuid, 'card_description', 'Paintings from 30,000 BC — the oldest and best-preserved figurative cave art in the world. Hundreds of animals fill the walls: lions, rhinos, mammoths, horses.', 'Rhinoceroses are painted on the walls of Chauvet Cave, where red ochre hands were stenciled by blowing pigment over them. Above a Venus figure, a bison head made some see a Minotaur.', 'teaser-card-s020:ce8a19e4-c1b3-42e6-9bf9-4eb5600c0650:card_description', 'teaser-card-s020 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '7f4426ddc89fcceae7d141d716af161d5d19be30563ad2a3ca04f985655a2d7e|d1d94c0924a4a71527305b4246c5cd4a2b758db06565ba5759e8158e7209c4e8|d1d94c0924a4a71527305b4246c5cd4a2b758db06565ba5759e8158e7209c4e8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Rhinoceroses are painted on the walls of Chauvet Cave, where red ochre hands were stenciled by blowing pigment over them. Above a Venus figure, a bison head made some see a Minotaur."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "rhinoceroses are painted in Chauvet Cave [S2]; the paintings are on the cave walls [S1, S2]; the cave holds red ochre hand imprints [S5]; the hands were stenciled by blowing pigment over them [S5]; a bison head lies above a Venus figure [S4]; the bison head led some to see a Minotaur [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Chauvet Cave is a cave in France (Ardèche) with cave paintings [SUPPORTED: https://en.wikipedia.org/wiki/Chauvet_Cave]; Rhinoceroses are painted on the walls of the cave [SUPPORTED: https://en.wikipedia.org/wiki/Chauvet_Cave]; Red ochre hands were stenciled in the cave by blowing pigment over them [SUPPORTED: https://en.wikipedia.org/wiki/Chauvet_Cave]; The cave has a Venus figure [SUPPORTED: https://en.wikipedia.org/wiki/Chauvet_Cave]; A bison head sits above the Venus figure [SUPPORTED: https://en.wikipedia.org/wiki/Chauvet_Cave]; The bison head made some see a Minotaur [SUPPORTED: https://en.wikipedia.org/wiki/Chauvet_Cave]"}]'::jsonb),
    ('ce9c68cf-97b7-4ef2-8301-0a3907d2608d'::uuid, 'card_description', 'Two Iron Age hillforts sharing one hill, barely 1 km apart. Paired hillforts are rare and may indicate rival communities or complementary functions.', 'Stockland Castle is two Iron Age hill forts on Stockland Hill, Devon: a great one on the eastern slope at 190–210 metres, and a little one on a small promontory about 1 kilometre northeast.', 'teaser-card-s020:ce9c68cf-97b7-4ef2-8301-0a3907d2608d:card_description', 'teaser-card-s020 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'b58b60bccad63652137e56974709225eb0726925b492b993ec33acd64000d6f2|1aca5ffb709c6e009d201286eb1c181ea633c02e8d9ca0e5492ae3037923f7a8|1aca5ffb709c6e009d201286eb1c181ea633c02e8d9ca0e5492ae3037923f7a8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Stockland Castle is two Iron Age hill forts on Stockland Hill, Devon: a great one on the eastern slope at 190–210 metres, and a little one on a small promontory about 1 kilometre northeast."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Stockland Castle is two hill forts [S1]; the hill forts are Iron Age [S1]; they are on Stockland Hill, Devon [S1]; the great fort lies on the eastern slope [S2]; the great fort is at 190-210 metres [S2]; the little fort occupies a small promontory [S3]; the little fort is about 1 kilometre northeast (of the great one) [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Stockland Castle consists of two hill forts (the central claim: a hill fort site) [SUPPORTED: https://en.wikipedia.org/wiki/Stockland_Castle]; The forts are Iron Age [SUPPORTED: https://en.wikipedia.org/wiki/Stockland_Castle]; The forts stand on Stockland Hill [SUPPORTED: https://en.wikipedia.org/wiki/Stockland_Castle]; The site is in Devon, England [SUPPORTED: https://en.wikipedia.org/wiki/Stockland_Castle]; The great (larger) fort lies on the eastern slope of the hill [SUPPORTED: https://en.wikipedia.org/wiki/Stockland_Castle]; The great fort lies at 190-210 metres above sea level [SUPPORTED: https://en.wikipedia.org/wiki/Stockland_Castle]; The little (smaller) fort occupies a small promontory [SUPPORTED: https://en.wikipedia.org/wiki/Stockland_Castle]; The little fort is about 1 kilometre northeast of the great one [SUPPORTED: https://en.wikipedia.org/wiki/Stockland_Castle]"}]'::jsonb),
    ('cea5eebe-1a8a-4132-8867-12102672ecc0'::uuid, 'card_description', 'Occupied from around 600 BC until the Roman conquest, this Cheshire hillfort is only seven in a county where such sites are scarce — a rarity reflecting the region''s distinctive geology.', 'On the highest point of a plateau on Bickerton Hill, Maiden Castle raised its ramparts around 600 BC. To the north and west it has no artificial defences: the steep slope stands guard.', 'teaser-card-s020:cea5eebe-1a8a-4132-8867-12102672ecc0:card_description', 'teaser-card-s020 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '5dbe7c1a8f9ef9646baddc5de48def3f141af1978f2a368d560a0389c524e74c|803356811e9322de3ae369ff41c6773f1290b4241e7a91c2da02733b7f76f89f|803356811e9322de3ae369ff41c6773f1290b4241e7a91c2da02733b7f76f89f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the highest point of a plateau on Bickerton Hill, Maiden Castle raised its ramparts around 600 BC. To the north and west it has no artificial defences: the steep slope stands guard."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Maiden Castle sits on the highest point of a plateau on Bickerton Hill [S3]; its ramparts were raised around 600 BC [S5]; to the north and west it has no artificial defences [S4]; the steep slope takes the place of defences there [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Maiden Castle is a fortified hill fort (Iron Age) in Cheshire, England (central claim: a hill fort) [SUPPORTED: https://en.wikipedia.org/wiki/Maiden_Castle,_Cheshire]; Maiden Castle stands on the highest point of a plateau [SUPPORTED: https://en.wikipedia.org/wiki/Maiden_Castle,_Cheshire]; The plateau is on Bickerton Hill [SUPPORTED: https://en.wikipedia.org/wiki/Maiden_Castle,_Cheshire]; Its ramparts were raised around 600 BC [SUPPORTED: https://en.wikipedia.org/wiki/Maiden_Castle,_Cheshire]; To the north and west it has no artificial defences [SUPPORTED: https://en.wikipedia.org/wiki/Maiden_Castle,_Cheshire]; The steep slope serves as its defence on the north and west (natural defence instead of artificial) [SUPPORTED: https://en.wikipedia.org/wiki/Maiden_Castle,_Cheshire]"}]'::jsonb),
    ('d013bd60-0008-4319-85ff-1523f13edf5b'::uuid, 'card_description', 'A hilltop with a Bronze Age barrow, a menhir, and a logan stone that supposedly could only be rocked at midnight. The menhir stands on the western slope near an old mine.', 'A round barrow crowns the summit of Trink Hill, 212 metres high near Nancledra, with a trig point set within it, and on the western slope stands a stone named after the nearby Giew Mine.', 'teaser-card-s020:d013bd60-0008-4319-85ff-1523f13edf5b:card_description', 'teaser-card-s020 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '20870ee3e7d5f623a4355ac7b51c58dda5c454c5d00d96b481b3685180dfe6c0|d51cfa43c3224aebdf22a10ebadaacfc622d7ad166955c4582c7721dc8ddf7a6|d51cfa43c3224aebdf22a10ebadaacfc622d7ad166955c4582c7721dc8ddf7a6', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A round barrow crowns the summit of Trink Hill, 212 metres high near Nancledra, with a trig point set within it, and on the western slope stands a stone named after the nearby Giew Mine."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "a round barrow exists at the summit of Trink Hill [S2]; Trink Hill is 212 metres high [S1]; it is near Nancledra [S1]; a trig point is set within the barrow [S2]; a stone stands on the western slope [S3]; the stone is named after the nearby Giew Mine [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A round barrow exists at the summit of Trink Hill (central claim: a round barrow on a hilltop) [SUPPORTED: https://en.wikipedia.org/wiki/Trink_Hill]; Trink Hill is 212 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Trink_Hill]; Trink Hill is near Nancledra [SUPPORTED: https://en.wikipedia.org/wiki/Trink_Hill]; A trig point is set within the round barrow [SUPPORTED: https://en.wikipedia.org/wiki/Trink_Hill]; A stone stands on the western slope of the hill [SUPPORTED: https://en.wikipedia.org/wiki/Trink_Hill]; The stone is named after the nearby Giew Mine [SUPPORTED: https://en.wikipedia.org/wiki/Trink_Hill]"}]'::jsonb),
    ('d030a021-0623-49bb-983a-e8f0ce66ea25'::uuid, 'card_description', NULL, 'Strabo and Plutarch called Artashat the Armenian Carthage. Founded in 176 BC on a peninsula of nine hills where two rivers meet, it still shows the remains of its great walls.', 'teaser-card-s020:d030a021-0623-49bb-983a-e8f0ce66ea25:card_description', 'teaser-card-s020 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '6cc6b4dcb1d27c8d6fbf90662e1108c34a8e7ef18f267688b38ef7929de5ffff|8e325e77e4067d33af34c4a47c76669a91d5b9b5fa1f88339c4524cc8a25d2d0|8e325e77e4067d33af34c4a47c76669a91d5b9b5fa1f88339c4524cc8a25d2d0', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Strabo and Plutarch called Artashat the Armenian Carthage. Founded in 176 BC on a peninsula of nine hills where two rivers meet, it still shows the remains of its great walls."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Strabo and Plutarch called the city the Armenian Carthage [S5]; it was founded in 176 BC [S1, S3]; it stood on a peninsula of nine hills [S3]; the peninsula lies where two rivers meet (confluence of the Araks and Metsamor) [S3]; remains of its great walls are still visible [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-073 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Artashat (Artaxata) is an ancient city, a major city and capital of the ancient Kingdom of Armenia (central claim: an ancient city) [SUPPORTED: https://en.wikipedia.org/wiki/Artaxata]; Its ruins are in Armenia [SUPPORTED: https://en.wikipedia.org/wiki/Artaxata]; Strabo and Plutarch called it the Armenian Carthage [SUPPORTED: https://en.wikipedia.org/wiki/Artaxata]; It was founded in 176 BC [SUPPORTED: https://en.wikipedia.org/wiki/Artaxata]; It was founded on a peninsula of nine hills [SUPPORTED: https://en.wikipedia.org/wiki/Artaxata]; The peninsula lies where two rivers (Araks and Metsamor) meet [SUPPORTED: https://en.wikipedia.org/wiki/Artaxata]; The remains of the great walls of the city are still visible today [SUPPORTED: https://en.wikipedia.org/wiki/Artaxata]"}]'::jsonb),
    ('d0dab028-351d-48e1-b749-821e89458654'::uuid, 'card_description', 'A group of standing stones near the Hole of Horcum on the North York Moors. The tallest stone stands 1.9 metres but is much weathered and leaning.', 'Near the Hole of Horcum, at least four of the Blakey Topping Standing Stones survive, some of uncertain status. The tallest is 1.9 metres, much-weathered and leaning.', 'teaser-card-s020:d0dab028-351d-48e1-b749-821e89458654:card_description', 'teaser-card-s020 (teaser-card): teaser card, 166 characters, checked PASS, web-verified VERIFIED', '5f99656c5b6496d012c1cdeaa21c3c90c14cd9064c1c08e47e5effcc1806152c|b1e1126c7ed79e9f58f83209bf62aadeb05af3665b813e0d3d21401d24ad8e44|b1e1126c7ed79e9f58f83209bf62aadeb05af3665b813e0d3d21401d24ad8e44', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near the Hole of Horcum, at least four of the Blakey Topping Standing Stones survive, some of uncertain status. The tallest is 1.9 metres, much-weathered and leaning."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the stones are near the Hole of Horcum [S1]; at least four standing stones survive [S3]; some of the stones are of uncertain status (hedged in the description) [S3]; the tallest stone is 1.9 metres high [S4]; the tallest stone is much-weathered and leaning [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Blakey Topping Standing Stones is a small group of standing stones near the Hole of Horcum (North York Moors, England) [SUPPORTED: https://en.wikipedia.org/wiki/Blakey_Topping_standing_stones]; At least four of the stones survive [SUPPORTED: https://en.wikipedia.org/wiki/Blakey_Topping_standing_stones]; Some of the surviving stones are of uncertain status [SUPPORTED: https://en.wikipedia.org/wiki/Blakey_Topping_standing_stones]; The tallest stone is 1.9 metres high [SUPPORTED: https://en.wikipedia.org/wiki/Blakey_Topping_standing_stones]; The tallest stone is much-weathered and leaning [SUPPORTED: https://en.wikipedia.org/wiki/Blakey_Topping_standing_stones]"}]'::jsonb),
    ('d138a529-7499-4ed5-b039-5607886bce86'::uuid, 'card_description', 'A hillfort linked to King Arthur''s legendary Camelot since the medieval period. Excavations revealed a massive timber hall and a 7.2-hectare ramparted plateau.', 'Ramparts ring a plateau of 7.28 hectares on limestone Cadbury Hill. Cadbury Castle has yielded a Great Hall, possible temples or shrines, and bones radiocarbon dated to 3500 and 3300 BC.', 'teaser-card-s020:d138a529-7499-4ed5-b039-5607886bce86:card_description', 'teaser-card-s020 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '9b4d27d611ce5367df77f99b60939886577a2d59f6fc8ec66f90d3a69943e175|73b6fe95fa90002c6ab781685d8450f953dfd11f8c177433122a728434ea8ff7|73b6fe95fa90002c6ab781685d8450f953dfd11f8c177433122a728434ea8ff7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Ramparts ring a plateau of 7.28 hectares on limestone Cadbury Hill. Cadbury Castle has yielded a Great Hall, possible temples or shrines, and bones radiocarbon dated to 3500 and 3300 BC."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "ramparts surround a plateau [S2]; the plateau is 7.28 hectares [S2]; the hill is the limestone Cadbury Hill [S2]; the site has yielded (evidence of) a Great Hall [S6]; the site has yielded a possible sequence of small temples or shrines (kept as possible) [S6]; bones from the site are radiocarbon dated to 3500 and 3300 BC [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Cadbury Castle (Somerset) is a hillfort whose ramparts ring the hill [SUPPORTED: https://en.wikipedia.org/wiki/Cadbury_Castle,_Somerset]; Ramparts ring a plateau of 7.28 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Cadbury_Castle,_Somerset]; Cadbury Hill is a limestone hill [SUPPORTED: https://en.wikipedia.org/wiki/Cadbury_Castle,_Somerset]; Excavation has yielded a Great Hall [SUPPORTED: https://en.wikipedia.org/wiki/Cadbury_Castle,_Somerset]; The site has yielded possible temples or shrines [SUPPORTED: https://en.wikipedia.org/wiki/Cadbury_Castle,_Somerset]; Bones from the site are radiocarbon dated to 3500 and 3300 BC [SUPPORTED: https://en.wikipedia.org/wiki/Cadbury_Castle,_Somerset]"}]'::jsonb),
    ('d224cdb4-5363-40c7-862e-dd7e589447b2'::uuid, 'card_description', 'The site is located on an isolated, rural hilltop rising over the Chapel of Nossa Senhora da Assunção.', 'On an isolated hilltop over the Chapel of Nossa Senhora da Assunção lies Castro de Sacóias, a destroyed fortified settlement: small stone walls, remnants of tiles, bricks and millstones.', 'teaser-card-s020:d224cdb4-5363-40c7-862e-dd7e589447b2:card_description', 'teaser-card-s020 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '088aedd1aa2a76192c08c073b4922690e23c089d56bc89232b6e498cbcdbc64b|5d1923f2f9d14c165eb3b502e1026be436d31604b046a7e6072a8ff8917ee323|5d1923f2f9d14c165eb3b502e1026be436d31604b046a7e6072a8ff8917ee323', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On an isolated hilltop over the Chapel of Nossa Senhora da Assunção lies Castro de Sacóias, a destroyed fortified settlement: small stone walls, remnants of tiles, bricks and millstones."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is on an isolated hilltop [S2]; the hilltop rises over the Chapel of Nossa Senhora da Assuncao [S2]; Castro de Sacoias is a destroyed fortified settlement [S3]; it has small walls of small stones [S3]; it has remnants of tiles, bricks and millstones [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castro de Sacóias (Portugal) is a fortified settlement (castro), now a former one [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Sac%C3%B3ias]; The fortified settlement is destroyed [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Sac%C3%B3ias]; It lies on an isolated hilltop [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Sac%C3%B3ias]; The hilltop rises over the Chapel of Nossa Senhora da Assunção [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Sac%C3%B3ias]; It has small stone walls [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Sac%C3%B3ias]; Remnants of tiles and bricks remain [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Sac%C3%B3ias]; Remnants of millstones remain [SUPPORTED: https://en.wikipedia.org/wiki/Castro_de_Sac%C3%B3ias]"}]'::jsonb),
    ('d4714397-6e73-432d-add3-c01e22cb055f'::uuid, 'card_description', 'A 2nd-century Roman double-arched city gate, one of ten that once ringed the city. It stands opposite the modern Citadel, which is built on the ancient capitol''s foundations.', 'Porta Gemina, a Roman gate in Pula, is named for the two semi-circular openings that lead into the town, probably built in the late 2nd or early 3rd century AD on an earlier gate''s remains.', 'teaser-card-s020:d4714397-6e73-432d-add3-c01e22cb055f:card_description', 'teaser-card-s020 (teaser-card): teaser card, 189 characters, checked PASS, web-verified VERIFIED', 'f0c0e484d20dafdddcfdf58c33e18b16af70b3159462106fb569a933f085d04f|20e7999655e60feae6f3ec1d338d53bc77fd15b61a7550c9854ff75f1985f6c9|20e7999655e60feae6f3ec1d338d53bc77fd15b61a7550c9854ff75f1985f6c9', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Porta Gemina, a Roman gate in Pula, is named for the two semi-circular openings that lead into the town, probably built in the late 2nd or early 3rd century AD on an earlier gate''s remains."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Porta Gemina is a Roman gate [S1]; it is in Pula [S1]; it is named for its two semi-circular openings leading into the town [S3]; it was probably built in the late 2nd or early 3rd century AD [S3]; it was probably built on the remains of an earlier gate [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Porta Gemina is a Roman city gate [SUPPORTED: https://en.wikipedia.org/wiki/Porta_Gemina]; It is in Pula, Croatia [SUPPORTED: https://en.wikipedia.org/wiki/Porta_Gemina]; It is named for its two openings that lead into the town [SUPPORTED: https://en.wikipedia.org/wiki/Porta_Gemina]; The two openings are semi-circular [SUPPORTED: https://en.wikipedia.org/wiki/Porta_Gemina]; It was probably built in the late 2nd or early 3rd century AD [SUPPORTED: https://en.wikipedia.org/wiki/Porta_Gemina]; It was built on the remains of an earlier gate [SUPPORTED: https://en.wikipedia.org/wiki/Porta_Gemina]"}]'::jsonb),
    ('d569aff2-99e0-4964-b6a5-a197bea12cda'::uuid, 'card_description', 'Iron Age earthworks consisting of a hill, a mound, and a rectangular enclosure connected by a zigzag causeway. They date to 395-205 BC and sit inside Hatfield Forest.', 'In Hatfield Forest, a zig-zag causeway formed by 2 almost parallel ditches links the mound of Portingbury Hills to an enclosure. Digs in 1964–1965 found a small flint blade 4 cm long.', 'teaser-card-s020:d569aff2-99e0-4964-b6a5-a197bea12cda:card_description', 'teaser-card-s020 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '133cd563409f90978180e73181ed5812e23e772e64828692b61dbbd9dea47305|3110c249eba2c1bd084bc0115a663990ed0fb14ad3e853a28ce66d905a89e6ab|3110c249eba2c1bd084bc0115a663990ed0fb14ad3e853a28ce66d905a89e6ab', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Hatfield Forest, a zig-zag causeway formed by 2 almost parallel ditches links the mound of Portingbury Hills to an enclosure. Digs in 1964–1965 found a small flint blade 4 cm long."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is in Hatfield Forest [S1, S4]; a zig-zag causeway formed by 2 almost parallel ditches links the mound to an enclosure [S3]; the earthworks are Portingbury Hills, with a mound [S1, S3]; digs took place in 1964-1965 [S2]; they found a small flint blade 4 cm long [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-verify-074 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Portingbury Hills is an earthwork site (a hill or mound, ditches and an enclosure) [SUPPORTED: https://en.wikipedia.org/wiki/Portingbury_Hills]; Portingbury Hills lies in Hatfield Forest [SUPPORTED: https://en.wikipedia.org/wiki/Portingbury_Hills]; A zig-zag causeway formed by 2 almost parallel ditches links the mound to an enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Portingbury_Hills]; Excavations took place in 1964-1965 [SUPPORTED: https://en.wikipedia.org/wiki/Portingbury_Hills]; The excavations found a small flint blade 4 cm long [SUPPORTED: https://en.wikipedia.org/wiki/Portingbury_Hills]"}]'::jsonb),
    ('d7cecc1a-ed47-4dd6-a335-69e1233d47aa'::uuid, 'card_description', 'As regards chronology, the remains correspond to a period between the end of the 1st century and mid-2nd century CE.', 'High above the River Tagus lie the ruins of the Roman Baths of Toledo, assumed from their scale to be public, part of the system that brought clean water to Toletum by aqueduct.', 'teaser-card-s020:d7cecc1a-ed47-4dd6-a335-69e1233d47aa:card_description', 'teaser-card-s020 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'f4dcec1611a7ebb97672990d0ac55aad81270f72128ce244692210b448d84dc8|8633adca4b1319a399147840799362a1be517b5ec80efefa0e6100a705fca6c7|8633adca4b1319a399147840799362a1be517b5ec80efefa0e6100a705fca6c7', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "High above the River Tagus lie the ruins of the Roman Baths of Toledo, assumed from their scale to be public, part of the system that brought clean water to Toletum by aqueduct."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Roman Baths of Toledo are ruins [S1]; they lie high above the River Tagus [S5]; they are assumed, from their scale, to have been public [S3]; they are part of the system that supplied clean water to the city [S2]; the city was then known as Toletum [S2]; water reached the city by aqueduct [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Roman Baths of Toledo are the ruins of Roman baths (thermae) in the city of Toledo, Spain [SUPPORTED: https://en.wikipedia.org/wiki/Roman_baths_of_Toledo]; The ruins lie high above the River Tagus [SUPPORTED: https://en.wikipedia.org/wiki/Roman_baths_of_Toledo]; From their scale the baths are assumed to have been public [SUPPORTED: https://en.wikipedia.org/wiki/Roman_baths_of_Toledo]; The baths were part of the system that supplied clean water to Toletum (Toledo) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_baths_of_Toledo]; Toletum is the Latin (Roman) name of the city of Toledo [SUPPORTED: https://en.wikipedia.org/wiki/Toledo,_Spain]; The water reached the city by aqueduct [SUPPORTED: https://en.wikipedia.org/wiki/Roman_baths_of_Toledo]"}]'::jsonb),
    ('d85b55ee-afa3-423c-99d5-84149e5f8ee9'::uuid, 'card_description', 'A long storage building from the age of Pericles, used to warehouse imported grain — mainly barley and wheat. It fed the Athenian navy based at the nearby port.', 'Built in the time of Pericles, the long Makra Stoa stored imported barley and wheat for Athens, supplied its fleet of triremes and, in times of shortage, fed the people directly.', 'teaser-card-s020:d85b55ee-afa3-423c-99d5-84149e5f8ee9:card_description', 'teaser-card-s020 (teaser-card): teaser card, 178 characters, checked PASS, web-verified VERIFIED', '5e22ed561062c04511bfbb689c977085e31439a5cbc66ba0fbe782ad88ba725e|c6cc3a46416247b24bab432c53c3cef6169c035bcfc361fbf0bce0f6d1a5fef6|c6cc3a46416247b24bab432c53c3cef6169c035bcfc361fbf0bce0f6d1a5fef6', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Built in the time of Pericles, the long Makra Stoa stored imported barley and wheat for Athens, supplied its fleet of triremes and, in times of shortage, fed the people directly."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "it was built in the time of Pericles [S1]; the Makra Stoa was a long building [S3]; it stored imported barley and wheat [S3]; the grain went to Athens [S4]; it supplied the Athenian fleet of triremes [S5]; in times of shortage it supplied the people directly [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Makra Stoa is an archaeological site, a long stoa that formed part of the ancient city of Piraeus, the port of Athens [SUPPORTED: https://en.wikipedia.org/wiki/Makra_Stoa]; The Makra Stoa was built in the time of Pericles [SUPPORTED: https://en.wikipedia.org/wiki/Makra_Stoa]; The Makra Stoa was a long building that stored imported barley and wheat [SUPPORTED: https://en.wikipedia.org/wiki/Makra_Stoa]; The grain stored there was sent on to Athens for consumption [SUPPORTED: https://en.wikipedia.org/wiki/Makra_Stoa]; The stoa supplied the Athenian fleet of triremes [SUPPORTED: https://en.wikipedia.org/wiki/Makra_Stoa]; In times of shortage the stoa supplied the people directly [SUPPORTED: https://en.wikipedia.org/wiki/Makra_Stoa]"}]'::jsonb),
    ('d8f8e827-efeb-4169-b55e-e6ee4718d3d6'::uuid, 'card_description', 'The capital town of the Iceni -- the tribe whose queen Boudica led a famous revolt against Rome in 61 AD. The town itself was built after the rebellion was crushed.', 'In 1928 a flight over a farm near Caistor St Edmund rediscovered Venta Icenorum, capital of the Iceni: not built on an Iron Age town, but a newly built frontier town on the River Tas.', 'teaser-card-s020:d8f8e827-efeb-4169-b55e-e6ee4718d3d6:card_description', 'teaser-card-s020 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', '9a2a0adef993503def6aa0e74fab996a3852ace99fe11e3b774127216ec4be97|3705444a5d85605f5a366b719a0b737357fa59ce8ae77c66cbef990edccbebe0|3705444a5d85605f5a366b719a0b737357fa59ce8ae77c66cbef990edccbebe0', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In 1928 a flight over a farm near Caistor St Edmund rediscovered Venta Icenorum, capital of the Iceni: not built on an Iron Age town, but a newly built frontier town on the River Tas."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "in 1928 a flight over a farm rediscovered the ruins of Venta Icenorum [S5]; the farm was near Caistor St Edmund [S5]; Venta Icenorum was the capital of the Iceni [S1]; it was not built on an Iron Age town [S8]; it was a newly built frontier town [S8]; it lies on the River Tas [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Venta Icenorum was a Roman-era town, the capital of the Iceni tribe [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Icenorum]; Venta Icenorum was the capital (civitas) of the Iceni tribe [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Icenorum]; Venta Icenorum lies at Caistor St Edmund in Norfolk, England [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Icenorum]; In 1928 a flight over a farm near Caistor St Edmund rediscovered the ruins of Venta Icenorum [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Icenorum]; Venta Icenorum was not built on an Iron Age town [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Icenorum]; Venta Icenorum was a newly built frontier town [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Icenorum]; The site lies on the River Tas [SUPPORTED: https://en.wikipedia.org/wiki/Venta_Icenorum]"}]'::jsonb),
    ('d953e9b3-de33-4c7d-9357-bbc5d94d2a16'::uuid, 'card_description', 'Radiocarbon dating shows that the earliest exposed structures at Göbekli Tepe were built between 9500 and 9000 BCE, towards the end of the Pre-Pottery Neolithic A period.', 'Göbekli Tepe, littered with flint, sets T-shaped stone pillars in its enclosures high on the edge of the Taurus foothills. Its earliest exposed structures rose between 9500 and 9000 BCE.', 'teaser-card-s020:d953e9b3-de33-4c7d-9357-bbc5d94d2a16:card_description', 'teaser-card-s020 (teaser-card): teaser card, 186 characters, checked PASS, web-verified VERIFIED', '5d7d25981a456a18d6e4553c638aa9afb96bdc674f6604247668138e340ca551|cef7de135692101d35a18030e551c7aaf5f7fac6248de3f107c169c5322a46be|cef7de135692101d35a18030e551c7aaf5f7fac6248de3f107c169c5322a46be', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Göbekli Tepe, littered with flint, sets T-shaped stone pillars in its enclosures high on the edge of the Taurus foothills. Its earliest exposed structures rose between 9500 and 9000 BCE."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is littered with flint [S7]; T-shaped stone pillars stand in its enclosures [S8]; it lies high on the edge of the Taurus foothills [S2, S3]; its earliest exposed structures were built between 9500 and 9000 BCE [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Göbekli Tepe is a Neolithic archaeological site with large stone pillar structures, in modern Turkey [SUPPORTED: https://en.wikipedia.org/wiki/G%C3%B6bekli_Tepe]; Göbekli Tepe is littered with flint [SUPPORTED: https://en.wikipedia.org/wiki/G%C3%B6bekli_Tepe]; T-shaped stone pillars are set in the enclosures [SUPPORTED: https://en.wikipedia.org/wiki/G%C3%B6bekli_Tepe]; The site stands high on the edge of the mountains [SUPPORTED: https://en.wikipedia.org/wiki/G%C3%B6bekli_Tepe]; The site lies in the foothills of the Taurus Mountains [SUPPORTED: https://en.wikipedia.org/wiki/G%C3%B6bekli_Tepe]; The earliest exposed structures were built between 9500 and 9000 [SUPPORTED: https://en.wikipedia.org/wiki/G%C3%B6bekli_Tepe]"}]'::jsonb),
    ('db29dbfd-e56d-41ac-a815-161899b03f2b'::uuid, 'card_description', 'A Maya pyramid built around 250 BC, largely destroyed in 2013 by contractors mining it for road gravel. Only the core of the once-massive structure survived.', 'At Nohmul, a Maya pyramid about 17 meters tall rose around 250 BC. Largely abandoned, it seems, by the 5th century, the site was later reoccupied and holds about 700 visible mounds.', 'teaser-card-s020:db29dbfd-e56d-41ac-a815-161899b03f2b:card_description', 'teaser-card-s020 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '86c3fe8a78ed4f7d23e2c2502518db52dd9068af7f75f4833634d5ef208b1e54|8e5876b2063eeda2fbb78c389a4be48a3049c2103fa92545e97c7ab6cd49977c|8e5876b2063eeda2fbb78c389a4be48a3049c2103fa92545e97c7ab6cd49977c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-025", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "At Nohmul, a Maya pyramid about 17 meters tall rose around 250 BC. Largely abandoned, it seems, by the 5th century, the site was later reoccupied and holds about 700 visible mounds."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-025 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Nohmul is a Maya site [S1]; it had a pyramid about 17 meters tall [S2]; the pyramid was built around 250 BC [S2]; by the 5th century the site seems to have been largely abandoned [S4]; it was later reoccupied [S5]; the site has about 700 visible mounds [S7]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-075 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Nohmul is a pre-Columbian Maya archaeological site in northern Belize with a large pyramid [SUPPORTED: https://en.wikipedia.org/wiki/Nohmul]; The Maya pyramid at Nohmul was about 17 meters tall [SUPPORTED: https://en.wikipedia.org/wiki/Nohmul]; The pyramid was built around 250 BC [SUPPORTED: https://en.wikipedia.org/wiki/Nohmul]; By the 5th century the site seems to have been largely abandoned [SUPPORTED: https://en.wikipedia.org/wiki/Nohmul]; The site was later reoccupied [SUPPORTED: https://en.wikipedia.org/wiki/Nohmul]; The site includes about 700 visible mounds [SUPPORTED: https://en.wikipedia.org/wiki/Nohmul]"}]'::jsonb),
    ('db4f2a2b-b4e3-49e2-ab4b-1167a1a83a20'::uuid, 'card_description', 'Castle Dykes Henge is a Class I Neolithic henge earthwork in the Yorkshire Dales National Park in North Yorkshire situated between the villages of Aysgarth and Thornton Rust.', 'In the Yorkshire Dales, Castle Dykes Henge draws a roughly circular Neolithic bank around an internal ditch. Excavation was reported in 1908, yet the henge appears to be mostly intact.', 'teaser-card-s020:db4f2a2b-b4e3-49e2-ab4b-1167a1a83a20:card_description', 'teaser-card-s020 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', 'fa6579fe0826c559f0d750a253c22549a4fdd45add48f99233ae64b3bcee51e9|5506c7d64809e69beca92194e65fcdb0edc31f74c17d33db845810a412a33659|5506c7d64809e69beca92194e65fcdb0edc31f74c17d33db845810a412a33659', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In the Yorkshire Dales, Castle Dykes Henge draws a roughly circular Neolithic bank around an internal ditch. Excavation was reported in 1908, yet the henge appears to be mostly intact."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies in the Yorkshire Dales [S1]; the henge is Neolithic [S1]; the henge has a roughly circular bank [S2]; the bank has an internal ditch [S2]; excavation was reported in 1908 [S3]; the henge appears to be mostly intact despite the reported excavation [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castle Dykes Henge is a henge earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Dykes_Henge]; Castle Dykes Henge lies in the Yorkshire Dales [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Dykes_Henge]; The henge is Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Dykes_Henge]; It has a roughly circular bank [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Dykes_Henge]; The bank surrounds an internal ditch [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Dykes_Henge]; Excavation at the site was reported in 1908 [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Dykes_Henge]; The henge appears to be mostly intact [SUPPORTED: https://en.wikipedia.org/wiki/Castle_Dykes_Henge]"}]'::jsonb),
    ('db61f285-8d98-417e-9f7e-52b6745a2eb6'::uuid, 'card_description', 'The Goatstones is a Bronze-Age four-poster stone circle located near Ravensheugh Crags in Northumberland.', 'North of Hadrian''s Wall, The Goatstones form a Bronze-Age four-poster circle whose smallest stone is decorated with 13 cup marks, the only recorded four-poster circle bearing them.', 'teaser-card-s020:db61f285-8d98-417e-9f7e-52b6745a2eb6:card_description', 'teaser-card-s020 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', 'a1eee5f35870d12c109a3504c17b84c859d71c0a8244ba4668f50c8128474a8e|0d68c713ca291d4edf6f50f045ef36e81b7a90b14cbf27ecb943f66e814750df|0d68c713ca291d4edf6f50f045ef36e81b7a90b14cbf27ecb943f66e814750df', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "North of Hadrian''s Wall, The Goatstones form a Bronze-Age four-poster circle whose smallest stone is decorated with 13 cup marks, the only recorded four-poster circle bearing them."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies north of Hadrian''s Wall [S2]; the Goatstones are a Bronze-Age four-poster stone circle [S1]; the smallest stone is decorated with 13 cup marks [S4]; it is the only recorded four-poster circle bearing cup marks [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Goatstones is a four-poster stone circle (in Northumberland, England) [SUPPORTED: https://en.wikipedia.org/wiki/The_Goatstones]; It lies north of Hadrian''s Wall [SUPPORTED: https://en.wikipedia.org/wiki/The_Goatstones]; It dates to the Bronze Age [SUPPORTED: https://en.wikipedia.org/wiki/The_Goatstones]; The smallest stone is decorated with 13 cup marks [SUPPORTED: https://en.wikipedia.org/wiki/The_Goatstones]; It is the only recorded four-poster stone circle bearing cup marks [SUPPORTED: https://en.wikipedia.org/wiki/The_Goatstones]"}]'::jsonb),
    ('dba6e82d-3388-4b6c-beba-63f8f440ba0b'::uuid, 'card_description', '137-metre hill dominating the flat Somerset Levels, visible for miles. The fort covers 1.6 hectares; the hill has been occupied since at least the Bronze Age around 2000 BC.', 'Before the Somerset Levels were drained, Brent Knoll was an island, the Isle of Frogs. On it, the Iron Age hillfort of Brent Knoll Camp gave up an urn of coins of Trajan and Severus.', 'teaser-card-s020:dba6e82d-3388-4b6c-beba-63f8f440ba0b:card_description', 'teaser-card-s020 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '86d92e24164f80d8d117333212fe4d1fa5e7539dc1080fd1217f05bbbfa76a10|029370f2e8762becd6e0b4e2f8ef7aac70e2c14e80edc45f8cd54b8ae183d55e|029370f2e8762becd6e0b4e2f8ef7aac70e2c14e80edc45f8cd54b8ae183d55e', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Before the Somerset Levels were drained, Brent Knoll was an island, the Isle of Frogs. On it, the Iron Age hillfort of Brent Knoll Camp gave up an urn of coins of Trajan and Severus."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "before the Somerset Levels were drained, Brent Knoll was an island [S3]; the island was known as the Isle of Frogs [S3]; Brent Knoll Camp is an Iron Age hillfort [S1]; an urn of coins of Trajan and Severus was found at the site [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Brent Knoll Camp is an Iron Age hillfort on Brent Knoll, Somerset [SUPPORTED: https://en.wikipedia.org/wiki/Brent_Knoll_Camp]; Before the Somerset Levels were drained, Brent Knoll was an island [SUPPORTED: https://en.wikipedia.org/wiki/Brent_Knoll_Camp]; The island was known as the Isle of Frogs [SUPPORTED: https://en.wikipedia.org/wiki/Brent_Knoll_Camp]; An urn of coins of Trajan and Severus was found at the site [SUPPORTED: https://en.wikipedia.org/wiki/Brent_Knoll_Camp]"}]'::jsonb),
    ('dcb2c5f2-682f-483b-8904-88d3b6fe6119'::uuid, 'card_description', 'The Erechtheion or Temple of Athena Polias is an ancient Greek Ionic temple, on the north side of the Acropolis, Athens.', 'On the north side of the Acropolis, the Erechtheion''s asymmetrical composition defies the canon of Greek classical architecture, and its precise date of construction is still unknown.', 'teaser-card-s020:dcb2c5f2-682f-483b-8904-88d3b6fe6119:card_description', 'teaser-card-s020 (teaser-card): teaser card, 183 characters, checked PASS, web-verified VERIFIED', 'ece8d632907d2a7fa28347c8b3bc634492c6e0cbebc138f8f08078cccc703a13|f953585aa931e62334df92a5a676b75b535800c76036a436978ee7541c1abf0f|f953585aa931e62334df92a5a676b75b535800c76036a436978ee7541c1abf0f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the north side of the Acropolis, the Erechtheion''s asymmetrical composition defies the canon of Greek classical architecture, and its precise date of construction is still unknown."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Erechtheion stands on the north side of the Acropolis [S1]; its composition is asymmetrical [S4]; its composition does not conform to the canon of Greek classical architecture [S4]; its precise date of construction is unknown [S3]; statement that something is unknown (the precise construction date) is made [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Erechtheion is an ancient Greek temple [SUPPORTED: https://en.wikipedia.org/wiki/Erechtheion]; The Erechtheion stands on the north side of the Acropolis [SUPPORTED: https://en.wikipedia.org/wiki/Erechtheion]; The Erechtheion has an asymmetrical composition [SUPPORTED: https://en.wikipedia.org/wiki/Erechtheion]; The asymmetrical composition does not conform to the canon of Greek classical architecture [SUPPORTED: https://en.wikipedia.org/wiki/Erechtheion]; The precise date of construction of the Erechtheion is unknown [SUPPORTED: https://en.wikipedia.org/wiki/Erechtheion]; The start of construction is still only conjectured, not established (no primary evidence) [SUPPORTED: https://en.wikipedia.org/wiki/Erechtheion]"}]'::jsonb),
    ('ddd6cdfa-6891-4f6f-932a-e276f2be47bd'::uuid, 'card_description', 'Founded by Milesians in the late 7th or early 6th century BC on a hill above Crimea, Pantikapaion became the capital of the Bosporan Kingdom. Its name derives from the Scythian word for fish-path.', 'Milesians founded Pantikapaion, a Greek city that minted silver, gold and bronze coins, on a hill later named Mount Mithridat. Here Mithridates took his life as his son turned against him.', 'teaser-card-s020:ddd6cdfa-6891-4f6f-932a-e276f2be47bd:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '320a5490ea8636ea2ae6d78d9c8a235ff1771d7e5881ac22f5e4a5daf4c9fe46|2da76103ab4e85f074c11bc06873a4e8abe84242f10d56ad8acca3e36e9dd08a|2da76103ab4e85f074c11bc06873a4e8abe84242f10d56ad8acca3e36e9dd08a', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Milesians founded Pantikapaion, a Greek city that minted silver, gold and bronze coins, on a hill later named Mount Mithridat. Here Mithridates took his life as his son turned against him."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Milesians founded Pantikapaion [S2]; Pantikapaion was a Greek city [S1]; the city minted silver coins [S4]; the city minted gold and bronze coins [S4]; it was on a hill later named Mount Mithridat [S2]; Mithridates took his life in Pantikapaion [S8]; his son turned against him at that time [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-076 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Pantikapaion was an ancient Greek city [SUPPORTED: https://en.wikipedia.org/wiki/Panticapaeum]; Milesians founded Pantikapaion [SUPPORTED: https://en.wikipedia.org/wiki/Panticapaeum]; It was founded on a hill later named Mount Mithridat [SUPPORTED: https://en.wikipedia.org/wiki/Panticapaeum]; The city minted silver coins [SUPPORTED: https://en.wikipedia.org/wiki/Panticapaeum]; The city minted gold coins [SUPPORTED: https://en.wikipedia.org/wiki/Panticapaeum]; The city minted bronze coins [SUPPORTED: https://en.wikipedia.org/wiki/Panticapaeum]; Mithridates took his own life in Pantikapaion [SUPPORTED: https://en.wikipedia.org/wiki/Panticapaeum]; His son turned against him at the time [SUPPORTED: https://en.wikipedia.org/wiki/Panticapaeum]"}]'::jsonb),
    ('ddeef34a-1bf9-4066-9871-d894d7f7bf1f'::uuid, 'card_description', 'A sanctuary spanning 4,000 years—Megalithic temple, Phoenician shrine, Roman pilgrimage site. The goddess worshipped here changed names but never left.', 'Above Marsaxlokk Bay, Tas-Silġ holds remains covering 4000 years: a Megalithic temple, a Phoenician and Punic sanctuary to Astarte, and a Roman complex to Juno mentioned by Cicero.', 'teaser-card-s020:ddeef34a-1bf9-4066-9871-d894d7f7bf1f:card_description', 'teaser-card-s020 (teaser-card): teaser card, 180 characters, checked PASS, web-verified VERIFIED', '93b50950336f1eb0b92369c85a9bf218398abf02c2646926634648e3be90a6e3|0b53872a3c412b1fc3e53c49c66aea0bb580790502340b5ccc169ffee3b4b880|0b53872a3c412b1fc3e53c49c66aea0bb580790502340b5ccc169ffee3b4b880', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Above Marsaxlokk Bay, Tas-Silġ holds remains covering 4000 years: a Megalithic temple, a Phoenician and Punic sanctuary to Astarte, and a Roman complex to Juno mentioned by Cicero."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies above Marsaxlokk Bay [S1]; the remains cover 4000 years [S2]; there is a Megalithic temple [S3]; there is a Phoenician and Punic sanctuary to Astarte [S3]; in Roman times the site was a complex dedicated to Juno [S4]; the site is mentioned by Cicero [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tas-Silġ is a multi-period sanctuary (temple) site on a hilltop in Malta [SUPPORTED: https://en.wikipedia.org/wiki/Tas-Sil%C4%A1]; The site lies above (overlooks) Marsaxlokk Bay [SUPPORTED: https://en.wikipedia.org/wiki/Tas-Sil%C4%A1]; The site holds remains covering 4000 years [SUPPORTED: https://en.wikipedia.org/wiki/Tas-Sil%C4%A1]; The site includes a Megalithic temple [SUPPORTED: https://en.wikipedia.org/wiki/Tas-Sil%C4%A1]; The site includes a Phoenician and Punic sanctuary to Astarte [SUPPORTED: https://en.wikipedia.org/wiki/Tas-Sil%C4%A1]; In the Roman era the site was a religious complex dedicated to Juno [SUPPORTED: https://en.wikipedia.org/wiki/Tas-Sil%C4%A1]; The Roman temple of Juno is mentioned by Cicero [SUPPORTED: https://en.wikipedia.org/wiki/Tas-Sil%C4%A1]"}]'::jsonb),
    ('de97fdf7-80cc-425c-9c5b-b26b03310155'::uuid, 'card_description', 'Post holes, hearths, and charred hazelnut shells mark this Northumberland cliff camp, dated to 7600 BC. Structural evidence points to repeated seasonal occupation over many generations.', 'Flint tools eroding from a sandy cliff revealed Howick House: a circle of post holes, hearths of burnt nutshells, a home built about 7600 BC and occupied for about 100 years.', 'teaser-card-s020:de97fdf7-80cc-425c-9c5b-b26b03310155:card_description', 'teaser-card-s020 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', 'fc57f97f5f6171269911487dfc729bd43600f939fc694bbc3ade213b57f0063c|dd0b73e395c63f7ba2f3321e1fae26ff9fd75163badb6554933bf0cf9f99c3e4|dd0b73e395c63f7ba2f3321e1fae26ff9fd75163badb6554933bf0cf9f99c3e4', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Flint tools eroding from a sandy cliff revealed Howick House: a circle of post holes, hearths of burnt nutshells, a home built about 7600 BC and occupied for about 100 years."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "flint tools eroding from a sandy cliff led to the discovery of the site [S2]; the site has a circle of post holes [S3]; the site has hearths of burnt nutshells [S3]; the house was built about 7600 BC [S4]; it was occupied for about 100 years [S4]; it was a house lived in, a home [S1, S4, S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Howick House is a Mesolithic house site near Howick in Northumberland, England [SUPPORTED: https://en.wikipedia.org/wiki/Howick_house]; The site was found when flint tools were eroding from a sandy cliff [SUPPORTED: https://en.wikipedia.org/wiki/Howick_house]; The site has a circle of post holes [SUPPORTED: https://en.wikipedia.org/wiki/Howick_house]; The house had hearths containing burnt nutshells [SUPPORTED: https://en.wikipedia.org/wiki/Howick_house]; The building was constructed about 7600 BC [SUPPORTED: https://en.wikipedia.org/wiki/Howick_house]; The house was occupied for about 100 years [SUPPORTED: https://en.wikipedia.org/wiki/Howick_house]"}]'::jsonb),
    ('debb506e-ab0d-4e03-876e-320c31ee59d2'::uuid, 'card_description', 'Minoan cave 400 m above sea level on Mt. Juktas, Crete. Used from Neolithic times as refuge and burial, then inhabited in Early Minoan times.', 'On the southwest slope of Mount Juktas, Stravomyti Cave first saw use in Neolithic times as a refuge and burial, and may once have been a shrine to Artemis, Diktynna or perhaps Eileithyia.', 'teaser-card-s020:debb506e-ab0d-4e03-876e-320c31ee59d2:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', 'b3c0955030d41d3451fb8534b6e08a7a7e7e93d022ecb82083439abcb519d12e|d79677a2fff2aef497122bca16daf2d4359ca36c7a4fc0a9e3650c4eee2bc02b|d79677a2fff2aef497122bca16daf2d4359ca36c7a4fc0a9e3650c4eee2bc02b', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the southwest slope of Mount Juktas, Stravomyti Cave first saw use in Neolithic times as a refuge and burial, and may once have been a shrine to Artemis, Diktynna or perhaps Eileithyia."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the cave is on the southwest slope of Mount Juktas [S2]; it first saw use in Neolithic times [S3]; its first use was as a refuge and burial [S3]; it may once have been a shrine (hedged: may have) [S6]; the deity was Artemis, Diktynna or perhaps Eileithyia (hedged) [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Stravomyti Cave is an ancient cave (Minoan-era cave on Crete, Greece) [SUPPORTED: https://en.wikipedia.org/wiki/Stravomyti_Cave]; The cave is on the southwest slope of Mount Juktas [SUPPORTED: https://en.wikipedia.org/wiki/Stravomyti_Cave]; The cave was first used in Neolithic times [SUPPORTED: https://en.wikipedia.org/wiki/Stravomyti_Cave]; The first (Neolithic) use was as a refuge and burial [SUPPORTED: https://en.wikipedia.org/wiki/Stravomyti_Cave]; The cave may once have been a shrine to Artemis, Diktynna or perhaps Eileithyia (uncertain) [SUPPORTED: https://en.wikipedia.org/wiki/Stravomyti_Cave]"}]'::jsonb),
    ('decbad37-dc89-4adf-926b-19c94a17e50f'::uuid, 'card_description', 'Active from the 7th century BC through the Roman period, this iron-smelting site in Burgundy ranks among the largest ferriers in Europe. Tons of slag remain scattered across the forested terrain.', 'Across 30 ha of Burgundy, the Ferrier of Tannerre-en-Puisaye holds one of the largest iron works in Europe, its ore smelted in bloomeries made of clay and forge-wrought on the spot.', 'teaser-card-s020:decbad37-dc89-4adf-926b-19c94a17e50f:card_description', 'teaser-card-s020 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '1a280675b2183dcfddf871d34cbc8fa28a8d7c7f4c1bc7741899d37ecfa02dc2|9fe4e88478bfd0b3c0b6008bc4929bd9db2933bcdfac2b58a574dab1bb5ee284|9fe4e88478bfd0b3c0b6008bc4929bd9db2933bcdfac2b58a574dab1bb5ee284', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Across 30 ha of Burgundy, the Ferrier of Tannerre-en-Puisaye holds one of the largest iron works in Europe, its ore smelted in bloomeries made of clay and forge-wrought on the spot."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the ferrier is spread over 30 ha [S4]; it lies in Burgundy [S1]; it is one of the largest iron-working sites in Europe [S3]; iron was produced in bloomeries made of clay [S8]; the iron was forge-wrought on the spot [S8]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-077 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Ferrier of Tannerre-en-Puisaye is a historic iron mining and ironworking site in Burgundy, France [SUPPORTED: https://en.wikipedia.org/wiki/Ferrier_of_Tannerre-en-Puisaye]; The site extends across 30 ha [SUPPORTED: https://en.wikipedia.org/wiki/Ferrier_of_Tannerre-en-Puisaye]; It is one of the largest iron works (ferriers) in Europe [SUPPORTED: https://en.wikipedia.org/wiki/Ferrier_of_Tannerre-en-Puisaye]; The iron ore was smelted in bloomeries made of clay [SUPPORTED: https://en.wikipedia.org/wiki/Ferrier_of_Tannerre-en-Puisaye]; The iron was forge-wrought on the spot [SUPPORTED: https://en.wikipedia.org/wiki/Ferrier_of_Tannerre-en-Puisaye]"}]'::jsonb),
    ('df70e98f-a1d1-4998-966a-d9a4ee2a945f'::uuid, 'card_description', 'A temple complex with continuous occupation from 3000 BC to the Inca Empire. A fortress at over 3,800 metres above sea level guards the site''s upper levels.', 'On the right side of the river Tantamayo, over 3.8 km above sea level, Piruro keeps a five-story building, its walls built with stones hewn in squared shape and uniform size.', 'teaser-card-s020:df70e98f-a1d1-4998-966a-d9a4ee2a945f:card_description', 'teaser-card-s020 (teaser-card): teaser card, 174 characters, checked PASS, web-verified VERIFIED', '319f1d2535072543741745293e787cb1df6006cad624cf60b308f45f1f1dfa53|77be1c4778c9ec9f44eca7b4749d1d3e79b2d912ab9734db5dd3df33b3a8a9b8|77be1c4778c9ec9f44eca7b4749d1d3e79b2d912ab9734db5dd3df33b3a8a9b8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On the right side of the river Tantamayo, over 3.8 km above sea level, Piruro keeps a five-story building, its walls built with stones hewn in squared shape and uniform size."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the building stands on the right side of the river Tantamayo [S5]; it lies over 3.8 km above sea level [S5]; Piruro has a five-story building [S6, S7]; its walls are built with stones hewn in squared shape [S6]; the stones are of uniform size [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Piruro is an archaeological site in Peru [SUPPORTED: https://en.wikipedia.org/wiki/Piruro]; The site lies on the right side of the river Tantamayo [SUPPORTED: https://en.wikipedia.org/wiki/Piruro]; The site lies over 3.8 km above sea level [SUPPORTED: https://es.wikipedia.org/wiki/Piruro]; Piruro has a five-story building [SUPPORTED: https://en.wikipedia.org/wiki/Piruro]; Its walls are built with stones hewn in squared shape and uniform size [SUPPORTED: https://en.wikipedia.org/wiki/Piruro]"}]'::jsonb),
    ('df9d4d4a-20d8-4384-ab5b-1e28e625cee4'::uuid, 'card_description', 'The cave is an important prehistoric site which has been occupied by different human groups over time.', 'Near the village of Azykh, the six caves of Azykh Cave are considered one of the most ancient locations of proto-human presence in Eurasia, home to different human groups over time.', 'teaser-card-s020:df9d4d4a-20d8-4384-ab5b-1e28e625cee4:card_description', 'teaser-card-s020 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '3824383038f43f690dc404b81dbf0964e22c4279afc18fec0116de733dc4d57a|1492b5e6c1bc53dc2e3343ae7a81b44b8dd6a05f4f988cd9325f271839490906|1492b5e6c1bc53dc2e3343ae7a81b44b8dd6a05f4f988cd9325f271839490906', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near the village of Azykh, the six caves of Azykh Cave are considered one of the most ancient locations of proto-human presence in Eurasia, home to different human groups over time."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is near the village of Azykh [S2]; it consists of six caves [S1]; it is considered one of the most ancient locations of proto-human presence in Eurasia [S4]; different human groups occupied it over time [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Azykh Cave is a six-cave complex (a cave site) in Azerbaijan, a habitation site of prehistoric humans [SUPPORTED: https://en.wikipedia.org/wiki/Azykh_Cave]; The caves are near the village of Azykh [SUPPORTED: https://en.wikipedia.org/wiki/Azykh_Cave]; It is considered one of the most ancient locations of proto-human presence in Eurasia [SUPPORTED: https://en.wikipedia.org/wiki/Azykh_Cave]; The cave was home to different human groups over time [SUPPORTED: https://en.wikipedia.org/wiki/Azykh_Cave]"}]'::jsonb),
    ('dfd4d30e-1a29-4917-9626-787b823d7748'::uuid, 'card_description', 'A commune inhabited since 6000 BC, with a secret cave of prehistoric paintings whose location is kept confidential. Bronze Age tombs were also found in nearby caves.', 'Upstream of the Gorges du Verdon, Castellane keeps traces of Neolithic nomads dating back to 6000 BC. Later, the Suetrii built an oppidum named Ducelia and mined salt to sell.', 'teaser-card-s020:dfd4d30e-1a29-4917-9626-787b823d7748:card_description', 'teaser-card-s020 (teaser-card): teaser card, 175 characters, checked PASS, web-verified VERIFIED', '5537d32d495f01566806f1b3ab344dd0685e0ab90537f622542aa506372248fc|b177348160fdb7f38cedcdb6f8850cf939c17c5a1e38ed9ab22617dfb86ebf6e|b177348160fdb7f38cedcdb6f8850cf939c17c5a1e38ed9ab22617dfb86ebf6e', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Upstream of the Gorges du Verdon, Castellane keeps traces of Neolithic nomads dating back to 6000 BC. Later, the Suetrii built an oppidum named Ducelia and mined salt to sell."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castellane lies upstream of the Gorges du Verdon [S1]; Neolithic nomads came through the area [S3]; the traces date back to 6000 BC [S3]; the Suetrii later created an oppidum [S5]; the oppidum was named Ducelia [S5]; they mined salt in the area and sold it [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Castellane is a town (a commune) in France [SUPPORTED: https://en.wikipedia.org/wiki/Castellane]; Castellane lies upstream of the Gorges du Verdon [SUPPORTED: https://en.wikipedia.org/wiki/Castellane]; Neolithic nomads came through the Castellane area [SUPPORTED: https://en.wikipedia.org/wiki/Castellane]; The oldest traces of these Neolithic nomads date back to 6000 BC [SUPPORTED: https://en.wikipedia.org/wiki/Castellane]; The Suetrii later built an oppidum near Castellane [SUPPORTED: https://en.wikipedia.org/wiki/Castellane]; The oppidum was named Ducelia [SUPPORTED: https://en.wikipedia.org/wiki/Castellane]; The Suetrii mined salt in the area and sold it [SUPPORTED: https://en.wikipedia.org/wiki/Castellane]"}]'::jsonb),
    ('e0d56737-6459-4329-9ef5-1a46e8d75f10'::uuid, 'card_description', 'The Giant''s Ring dates from the Neolithic period and was built around 2700 BC, before the Egyptian pyramids.', 'Near Belfast, the Giant''s Ring encloses 2.8 hectares within an earthwork bank 3.5 m high, a small passage tomb waiting east of its centre. It was built around 2700 BC.', 'teaser-card-s020:e0d56737-6459-4329-9ef5-1a46e8d75f10:card_description', 'teaser-card-s020 (teaser-card): teaser card, 167 characters, checked PASS, web-verified VERIFIED', 'a33a54ef8a441b0b3af2667381af96ce01909a71cae85c3f90a1db8d36fa01a3|a5aaee9a625f19f49d5af7a38559e3ffca4349cb4f9b78b9c62014cb20f35705|a5aaee9a625f19f49d5af7a38559e3ffca4349cb4f9b78b9c62014cb20f35705', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Near Belfast, the Giant''s Ring encloses 2.8 hectares within an earthwork bank 3.5 m high, a small passage tomb waiting east of its centre. It was built around 2700 BC."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Giant''s Ring is near Belfast [S1]; the enclosure covers 2.8 hectares [S2]; it is surrounded by an earthwork bank 3.5 m high [S2]; a small passage tomb lies east of the centre of the enclosure [S4]; it was built around 2700 BC [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Giant''s Ring is a prehistoric enclosure (a henge monument) near Belfast, Northern Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Ring]; The enclosure covers 2.8 hectares [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Ring]; The enclosure is surrounded by an earthwork bank 3.5 m high [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Ring]; A small passage tomb lies east of the centre of the enclosure [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Ring]; It was built around 2700 BC [SUPPORTED: https://en.wikipedia.org/wiki/Giant%27s_Ring]"}]'::jsonb),
    ('e14d6a17-ef86-403b-af85-be0a2fb8d8a2'::uuid, 'card_description', 'The cave was excavated and the entrance enlarged in 1860 by William Boyd Dawkins who named it after his mentor William Talbot Aveline.', 'Two men digging for a rabbit in 1797 rediscovered Aveline''s Hole, a Mendip cave holding the earliest scientifically dated cemetery in Britain, where some bodies seem to have been adorned.', 'teaser-card-s020:e14d6a17-ef86-403b-af85-be0a2fb8d8a2:card_description', 'teaser-card-s020 (teaser-card): teaser card, 187 characters, checked PASS, web-verified VERIFIED', 'd217e02111c0859a1cdc5e3a1c5f0dedca8691520af894fda0d70f2bc96f635b|e16feb5fc5de811c30f4d142d46c8f55fb595db38c921a9e2512e9caaba5d4b5|e16feb5fc5de811c30f4d142d46c8f55fb595db38c921a9e2512e9caaba5d4b5', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Two men digging for a rabbit in 1797 rediscovered Aveline''s Hole, a Mendip cave holding the earliest scientifically dated cemetery in Britain, where some bodies seem to have been adorned."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "two men digging for a rabbit rediscovered the cave [S5]; the rediscovery was in 1797 [S5]; Aveline''s Hole is a cave in the Mendip Hills [S1]; it holds the earliest scientifically dated cemetery in Britain [S2]; some of the bodies seem to have been adorned [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Aveline''s Hole is a cave in the Mendip Hills, in England [SUPPORTED: https://en.wikipedia.org/wiki/Aveline%27s_Hole]; The cave was rediscovered in 1797 [SUPPORTED: https://en.wikipedia.org/wiki/Aveline%27s_Hole]; It was two men digging for a rabbit who rediscovered the cave [SUPPORTED: https://en.wikipedia.org/wiki/Aveline%27s_Hole]; The cave holds a cemetery, the earliest scientifically dated cemetery in Britain [SUPPORTED: https://en.wikipedia.org/wiki/Aveline%27s_Hole]; Some of the bodies seem to have been adorned [SUPPORTED: https://en.wikipedia.org/wiki/Aveline%27s_Hole]"}]'::jsonb),
    ('e1edddb2-56c8-498b-b926-78642bc312e2'::uuid, 'card_description', 'The settlement was abandoned as part of the Late Bronze Age collapse after a few generations of habitation.', 'On a fortified peninsula in southwest Cyprus, Ancient Greeks worked metal and traded at Maa Palaeokastro, until the Late Bronze Age collapse emptied it after a few generations.', 'teaser-card-s020:e1edddb2-56c8-498b-b926-78642bc312e2:card_description', 'teaser-card-s020 (teaser-card): teaser card, 176 characters, checked PASS, web-verified VERIFIED', 'f1448306bfeb7ce89ad457d015152311b1688a6071f0ab56cb7737d71432d976|5d1605c7101ad92685efab1de0ba381351f874dd5af57b1a63888e096fbbfb1c|5d1605c7101ad92685efab1de0ba381351f874dd5af57b1a63888e096fbbfb1c', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-026", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "On a fortified peninsula in southwest Cyprus, Ancient Greeks worked metal and traded at Maa Palaeokastro, until the Late Bronze Age collapse emptied it after a few generations."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-026 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the settlement lay on a peninsula [S3]; it was fortified [S3]; it lay in southwest Cyprus [S1]; Ancient Greeks occupied it [S2]; metal-working took place there [S4]; trade took place there [S4]; it was abandoned as part of the Late Bronze Age collapse after a few generations [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-078 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Maa Palaeokastro was a settlement in southwest Cyprus [SUPPORTED: https://en.wikipedia.org/wiki/Maa_Palaeokastro]; The settlement was located on a peninsula [SUPPORTED: https://en.wikipedia.org/wiki/Maa_Palaeokastro]; The settlement was fortified [SUPPORTED: https://en.wikipedia.org/wiki/Maa_Palaeokastro]; It was occupied by Ancient Greeks [SUPPORTED: https://en.wikipedia.org/wiki/Maa_Palaeokastro]; Metal was worked at the site [SUPPORTED: https://en.wikipedia.org/wiki/Maa_Palaeokastro]; Trade took place at the site [SUPPORTED: https://en.wikipedia.org/wiki/Maa_Palaeokastro]; The Late Bronze Age collapse ended the settlement (it was abandoned as part of the collapse) [SUPPORTED: https://en.wikipedia.org/wiki/Maa_Palaeokastro]; The settlement was abandoned after a few generations of habitation [SUPPORTED: https://en.wikipedia.org/wiki/Maa_Palaeokastro]"}]'::jsonb),
    ('e2a08d7d-4038-4738-9702-4eb316357521'::uuid, 'card_description', 'Occupied around 35,000 BC, this cave near Châtelperron sits at the boundary between Neanderthal and modern human toolmaking traditions. Its artifacts define the Châtelperronian culture.', 'La Grotte des Fées: two interlinked caves discovered around 1840, perhaps in 1848, during railway construction. Several thousand flint blades and mammoth tusks over 2 metres long were found.', 'teaser-card-s020:e2a08d7d-4038-4738-9702-4eb316357521:card_description', 'teaser-card-s020 (teaser-card): teaser card, 190 characters, checked PASS, web-verified VERIFIED', '658012bf5632641c6b49b5b11eae3344313340aa2da4df2f70fa8a5e5cadc926|c619d916c2f2888eb96fc796b0fe0ae6a6a4348add694d460205fa5672f58468|c619d916c2f2888eb96fc796b0fe0ae6a6a4348add694d460205fa5672f58468', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-rewrite1-002", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "La Grotte des Fées: two interlinked caves discovered around 1840, perhaps in 1848, during railway construction. Several thousand flint blades and mammoth tusks over 2 metres long were found."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check1-002 (check1), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "two interlinked caves were discovered [S4]; discovered around 1840 [S4]; perhaps in 1848 (hedged) [S4]; discovered during railway construction [S4]; several thousand flint blades were found [S6]; mammoth tusks over 2 metres long were found [S6]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "La Grotte des Fées is a cave site (caves) in France, at Châtelperron in the department of Allier [SUPPORTED: https://en.wikipedia.org/wiki/La_Grotte_des_F%C3%A9es]; The site consists of two interlinked caves [SUPPORTED: https://journals.openedition.org/adlfi/126548]; The caves were discovered around 1840, perhaps in 1848 [SUPPORTED: https://en.wikipedia.org/wiki/La_Grotte_des_F%C3%A9es]; The caves were discovered during railway construction [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/La_Grotte_des_F%C3%A9es]; Several thousand flint blades were found [SUPPORTED: https://en.wikipedia.org/wiki/La_Grotte_des_F%C3%A9es]; Mammoth tusks over 2 metres long were found [SUPPORTED: https://en.wikipedia.org/wiki/La_Grotte_des_F%C3%A9es]"}]'::jsonb),
    ('e3df9803-11c3-47ca-8cd2-39265d32470b'::uuid, 'card_description', 'Possibly 48,000 BC. A sandstone rock shelter in Arnhem Land - possibly the oldest site of human habitation on the continent, on Mirarr Aboriginal land within sight of Kakadu National Park.', 'Madjedbebe, a sandstone rock shelter in Arnhem Land, is possibly the oldest site of human habitation in Australia. Over 100,000 artefacts came from its earth, from ochre to seeds.', 'teaser-card-s020:e3df9803-11c3-47ca-8cd2-39265d32470b:card_description', 'teaser-card-s020 (teaser-card): teaser card, 179 characters, checked PASS, web-verified VERIFIED', '9aa44dc1ee33a45cc5513e8fecec2cdb214504a42db66430873cd04aec6d1b35|b20cc4c5b31e0dbacacb83bba10373b193e868e96d6a21167371897a7a727988|b20cc4c5b31e0dbacacb83bba10373b193e868e96d6a21167371897a7a727988', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Madjedbebe, a sandstone rock shelter in Arnhem Land, is possibly the oldest site of human habitation in Australia. Over 100,000 artefacts came from its earth, from ochre to seeds."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Madjedbebe is a sandstone rock shelter [S1]; it is in Arnhem Land [S1]; it is possibly the oldest site of human habitation in Australia [S1]; more than 100,000 artefacts came out of the ground there [S4]; the artefacts include ochre [S4]; the artefacts include seeds [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Madjedbebe is a rock shelter (a site of human habitation), located in Arnhem Land [SUPPORTED: https://en.wikipedia.org/wiki/Madjedbebe]; The rock shelter is of sandstone [SUPPORTED: https://en.wikipedia.org/wiki/Madjedbebe]; The site lies in Arnhem Land, in Australia [SUPPORTED: https://en.wikipedia.org/wiki/Madjedbebe]; It is possibly the oldest site of human habitation in Australia [SUPPORTED: https://en.wikipedia.org/wiki/Madjedbebe]; More than 100,000 artefacts have come from the site''s excavated deposits [SUPPORTED: https://en.wikipedia.org/wiki/Madjedbebe]; The finds include ochre [SUPPORTED, no proving quote: https://en.wikipedia.org/wiki/Madjedbebe]; The finds include seeds [SUPPORTED: https://en.wikipedia.org/wiki/Madjedbebe]"}]'::jsonb),
    ('e3fc8870-e13e-40bd-8d81-455b5e30b97b'::uuid, 'card_description', 'Foel Drygarn is an Iron Age hillfort, within which are three Bronze Age burial cairns.', 'Within Foel Drygarn Hillfort, an Iron Age fort in Pembrokeshire, lie three Bronze Age burial cairns and at least 227 hut platforms, traces of a long period of occupation.', 'teaser-card-s020:e3fc8870-e13e-40bd-8d81-455b5e30b97b:card_description', 'teaser-card-s020 (teaser-card): teaser card, 170 characters, checked PASS, web-verified VERIFIED', '39693121f94ac06ff1891619f1188a2db85517f8b6e2d594423b74ea92c42922|813405d118de09238e863c2d79aebc83b8cdd34987ab05e535fb6b5d60328cd8|813405d118de09238e863c2d79aebc83b8cdd34987ab05e535fb6b5d60328cd8', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Within Foel Drygarn Hillfort, an Iron Age fort in Pembrokeshire, lie three Bronze Age burial cairns and at least 227 hut platforms, traces of a long period of occupation."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Foel Drygarn is an Iron Age fort [S1]; it is in Pembrokeshire [S2]; three Bronze Age burial cairns lie within it [S1]; at least 227 hut platforms lie within it [S4]; the remains are traces of a long period of occupation [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-079 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Foel Drygarn is an Iron Age hillfort (a fort) [SUPPORTED: https://en.wikipedia.org/wiki/Foel_Drygarn]; The hillfort is in Pembrokeshire (Wales) [SUPPORTED: https://en.wikipedia.org/wiki/Foel_Drygarn]; Within the fort lie three Bronze Age burial cairns [SUPPORTED: https://en.wikipedia.org/wiki/Foel_Drygarn]; The three summit cairns are interpreted as Bronze Age burial cairns [SUPPORTED: https://coflein.gov.uk/en/sites/94948]; The fort contains at least 227 hut platforms [SUPPORTED: https://en.wikipedia.org/wiki/Foel_Drygarn]; The hut platforms are traces of a long period of occupation [SUPPORTED: https://en.wikipedia.org/wiki/Foel_Drygarn]"}]'::jsonb),
    ('e406449f-9274-4ab6-ba10-0d4ea77fa7af'::uuid, 'card_description', 'At the south-western Mendip Hills edge near Wells, this hilltop enclosure has two or three interlinked sub-enclosures with an attached field system. It may predate the city now spread below it.', 'A Scheduled Ancient Monument, King''s Castle is a hilltop settlement near Wells in Somerset, its interlinked enclosures never archaeologically excavated. Was it the city''s precursor?', 'teaser-card-s020:e406449f-9274-4ab6-ba10-0d4ea77fa7af:card_description', 'teaser-card-s020 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '26278d3ccea0887a0c9e30fbf0f191dd4107564416b97231b36a7d35094d5462|6c562414ddd32a8782944c1bee8f4600d637b2e4b049bdec5dec1dd73beda416|6c562414ddd32a8782944c1bee8f4600d637b2e4b049bdec5dec1dd73beda416', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "A Scheduled Ancient Monument, King''s Castle is a hilltop settlement near Wells in Somerset, its interlinked enclosures never archaeologically excavated. Was it the city''s precursor?"}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "King''s Castle is a Scheduled Ancient Monument [S4]; it is a hilltop settlement [S1]; it lies near Wells [S1]; it lies in Somerset [S1]; its enclosures are interlinked [S3]; it has never been archaeologically excavated [S3]; it may have been the precursor of the city (Wells), asked as a question [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "King''s Castle is a hilltop settlement (an enclosed hilltop settlement) [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Castle,_Wells]; King''s Castle is near Wells [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Castle,_Wells]; King''s Castle is in Somerset [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Castle,_Wells]; King''s Castle is a Scheduled Ancient Monument [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Castle,_Wells]; The site consists of interlinked enclosures [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Castle,_Wells]; The site has never been archaeologically excavated [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Castle,_Wells]; It is an open question whether the settlement was the precursor of the city of Wells [SUPPORTED: https://en.wikipedia.org/wiki/King%27s_Castle,_Wells]"}]'::jsonb),
    ('e4f22a09-abfb-43d9-a7af-e87c033ae455'::uuid, 'card_description', 'Excavations in the late 1960s and early 1970s revealed seven "marbles", four pendants, two beads, a used flint flake, a bone chisel, and fragments of bone pins and points.', 'Above the River Boyne, Newgrange shows a façade made mostly of white quartz, ringed by engraved kerbstones. Its stone passage leads to a cruciform chamber where burnt bones were found.', 'teaser-card-s020:e4f22a09-abfb-43d9-a7af-e87c033ae455:card_description', 'teaser-card-s020 (teaser-card): teaser card, 184 characters, checked PASS, web-verified VERIFIED', '910de6130269f603038bbcb691577b3cb192d4622428e0ae968b6f7b28df41eb|e71cf9602962f528e054fb9de3ee801cb3adff8b8262d54eb3570b5e2a68c57f|e71cf9602962f528e054fb9de3ee801cb3adff8b8262d54eb3570b5e2a68c57f', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Above the River Boyne, Newgrange shows a façade made mostly of white quartz, ringed by engraved kerbstones. Its stone passage leads to a cruciform chamber where burnt bones were found."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Newgrange lies above (overlooks) the River Boyne [S1]; it has a façade made mostly of white quartz [S5]; the façade is ringed by engraved kerbstones [S5]; it has a stone passage [S3]; the passage leads to a cruciform chamber [S3]; burnt bones were found in the chamber [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-010 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Newgrange is a prehistoric monument (passage tomb) in County Meath, Ireland [SUPPORTED: https://en.wikipedia.org/wiki/Newgrange]; Newgrange stands above the River Boyne [SUPPORTED: https://en.wikipedia.org/wiki/Newgrange]; Newgrange has a facade [SUPPORTED: https://en.wikipedia.org/wiki/Newgrange]; The facade is made mostly of white quartz [SUPPORTED: https://en.wikipedia.org/wiki/Newgrange]; The facade is ringed by engraved kerbstones [SUPPORTED: https://en.wikipedia.org/wiki/Newgrange]; Newgrange has a stone passage [SUPPORTED: https://en.wikipedia.org/wiki/Newgrange]; The passage leads to a cruciform chamber [SUPPORTED: https://en.wikipedia.org/wiki/Newgrange]; Burnt bones were found in the chamber [SUPPORTED: https://en.wikipedia.org/wiki/Newgrange]"}]'::jsonb),
    ('e5051a8b-714a-4878-869d-6190e20380cd'::uuid, 'card_description', 'A linear earthwork stretching nearly 10 km, built by the Catuvellauni tribe as a defense against the Romans. Today only fragments survive among suburban streets.', 'Trace Grim''s Ditch, also called Grim''s Dyke or Grimes Dike, a linear earthwork in the London Borough of Harrow whose highest point lies close to the county top of historic Middlesex.', 'teaser-card-s020:e5051a8b-714a-4878-869d-6190e20380cd:card_description', 'teaser-card-s020 (teaser-card): teaser card, 182 characters, checked PASS, web-verified VERIFIED', '581a53a57e1efb05ffc4db26595fbd02893a912d75296eaa34659aa80c932024|7882dbad7cd3dfd1f3dab46e15a29e84ba36f5943598fa7814c8b67704305a34|7882dbad7cd3dfd1f3dab46e15a29e84ba36f5943598fa7814c8b67704305a34', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Trace Grim''s Ditch, also called Grim''s Dyke or Grimes Dike, a linear earthwork in the London Borough of Harrow whose highest point lies close to the county top of historic Middlesex."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Grim''s Ditch is also called Grim''s Dyke [S1]; Grim''s Ditch is also called Grimes Dike [S1]; it is a linear earthwork [S1]; it is in the London Borough of Harrow [S1]; its highest point lies close to the county top of historic Middlesex [S2]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Grim''s Ditch at Harrow is a linear earthwork [SUPPORTED: https://en.wikipedia.org/wiki/Grim%27s_Ditch_(Harrow)]; The earthwork lies in the London Borough of Harrow [SUPPORTED: https://en.wikipedia.org/wiki/Grim%27s_Ditch_(Harrow)]; The earthwork is also called Grim''s Dyke [SUPPORTED: https://en.wikipedia.org/wiki/Grim%27s_Ditch_(Harrow)]; The earthwork is also called Grimes Dike [SUPPORTED: https://en.wikipedia.org/wiki/Grim%27s_Ditch_(Harrow)]; The highest point of the earthwork lies close to the county top of the historic county of Middlesex [SUPPORTED: https://en.wikipedia.org/wiki/Grim%27s_Ditch_(Harrow)]; Historic Middlesex has a county top (its highest point) at Bushey Heath, at the edge of the county [SUPPORTED: https://en.wikipedia.org/wiki/Bushey_Heath]"}]'::jsonb),
    ('e507b1a6-966b-4dec-88fc-e167e3915821'::uuid, 'card_description', 'Built around 1450 BC by Thutmose III and extended by Amenhotep II and Thutmose IV, this is the oldest pharaonic temple surviving in Nubia. Its interior reliefs are finely cut and retain vivid pigment.', 'In Nubia stands the Temple of Amada, one of the oldest Egyptian temples there, built by Thutmose III. Akhenaten had the name Amun destroyed within its walls; Seti I restored it.', 'teaser-card-s020:e507b1a6-966b-4dec-88fc-e167e3915821:card_description', 'teaser-card-s020 (teaser-card): teaser card, 177 characters, checked PASS, web-verified VERIFIED', 'acf3d9c8f6f26da01086e365d055a4801b79dae3aa29de51fa51445207a0281a|cf8573d7f428833a2c8c976053c2b783576163f4c55f63720d39dab64a0feadd|cf8573d7f428833a2c8c976053c2b783576163f4c55f63720d39dab64a0feadd', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "In Nubia stands the Temple of Amada, one of the oldest Egyptian temples there, built by Thutmose III. Akhenaten had the name Amun destroyed within its walls; Seti I restored it."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the Temple of Amada stands in Nubia [S1]; it is one of the oldest Egyptian temples in Nubia [S1]; it was built by Thutmose III [S2]; Akhenaten had the name Amun destroyed within the temple [S5]; Seti I restored the name [S5]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The Temple of Amada is an Egyptian temple in Nubia [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Amada]; It is one of the oldest Egyptian temples in Nubia [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Amada]; The temple was built by Thutmose III [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Amada]; Akhenaten had the name Amun destroyed within the temple walls [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Amada]; Seti I restored the name of Amun in the temple [SUPPORTED: https://en.wikipedia.org/wiki/Temple_of_Amada]"}]'::jsonb),
    ('e569fdb5-f2fd-4054-8aec-74d21e99a70f'::uuid, 'card_description', 'A Neolithic passage grave near the Boyne Valley megaliths. Unlike its famous neighbors, this tomb started as a settlement that was converted into a burial site.', 'Around 2 km north of Dowth lies Townleyhall Passage Grave, one chamber merging with its passage. Its Carrowkeel ware gave the first indication that Ireland''s passage graves were Neolithic.', 'teaser-card-s020:e569fdb5-f2fd-4054-8aec-74d21e99a70f:card_description', 'teaser-card-s020 (teaser-card): teaser card, 188 characters, checked PASS, web-verified VERIFIED', '3a8c376744cbe494ad595ff0236bc09fa315ab3e6755fd58081b001147d491ac|981f07b33a4276837162a0ed0a3246b9e894339194698f606882b2c82311d151|981f07b33a4276837162a0ed0a3246b9e894339194698f606882b2c82311d151', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Around 2 km north of Dowth lies Townleyhall Passage Grave, one chamber merging with its passage. Its Carrowkeel ware gave the first indication that Ireland''s passage graves were Neolithic."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Townleyhall Passage Grave lies around 2 km north of Dowth [S1]; the tomb has a single chamber [S3]; the chamber merges with its passage [S3]; Carrowkeel ware pottery was found at the tomb [S4]; the Carrowkeel ware gave the first indication that Ireland''s passage graves were Neolithic [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Townleyhall Passage Grave is a passage grave (a chamber tomb) [SUPPORTED: https://en.wikipedia.org/wiki/Townleyhall_passage_grave]; It lies around 2 km north of Dowth [SUPPORTED: https://en.wikipedia.org/wiki/Townleyhall_passage_grave]; Its tomb has a single chamber [SUPPORTED: https://en.wikipedia.org/wiki/Townleyhall_passage_grave]; The chamber merges with its passage [SUPPORTED: https://en.wikipedia.org/wiki/Townleyhall_passage_grave]; Carrowkeel ware pottery was found at Townleyhall [SUPPORTED: https://en.wikipedia.org/wiki/Townleyhall_passage_grave]; The Carrowkeel ware gave the first indication that Ireland''s passage graves were Neolithic [SUPPORTED: https://en.wikipedia.org/wiki/Townleyhall_passage_grave]"}]'::jsonb),
    ('e578e7e9-a9ec-48d0-9f9f-64f3f1b64a5e'::uuid, 'card_description', '1st–4th century AD. Vats cut into the floor produced garum — fermented fish gut sauce — from local mackerel and tuna. The southern tip of Hispania was one of Rome''s biggest garum hubs.', 'Salt and fish met on the seafront of Algeciras, at the Roman Fish Salting Factory. A site of archaeological and historical interest, it was declared a Bien de Interés Cultural site.', 'teaser-card-s020:e578e7e9-a9ec-48d0-9f9f-64f3f1b64a5e:card_description', 'teaser-card-s020 (teaser-card): teaser card, 181 characters, checked PASS, web-verified VERIFIED', '74867211a5b18d2e121afd123c7a69364956e7c4b5f351b1f21061d8cceefba5|4b577ae5b43029ee1ae3c8bc01be1f07e7ccf04df3a7f75d7b753758ea52b782|4b577ae5b43029ee1ae3c8bc01be1f07e7ccf04df3a7f75d7b753758ea52b782', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-rewrite-v-004", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Salt and fish met on the seafront of Algeciras, at the Roman Fish Salting Factory. A site of archaeological and historical interest, it was declared a Bien de Interés Cultural site."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-v-004 (check-v), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site is the Roman Fish Salting Factory (a salting factory for fish) [S1]; salt and fish met there, i.e. fish was salted at the factory [S1]; it stands on the seafront of Algeciras [S1]; it is a site of archaeological and historical interest [S3]; it was declared a Bien de Interés Cultural site [S3]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify2-011 (verify2), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "The site is a Roman fish salting factory in Algeciras, Spain (a salting factory established by the Romans) [SUPPORTED: https://en.wikipedia.org/wiki/Roman_fish_salting_factory]; The factory stands on the seafront of Algeciras [SUPPORTED: https://en.wikipedia.org/wiki/Roman_fish_salting_factory]; The factory is Roman in date (founded in the 1st century AD, in use under Rome) [SUPPORTED: https://es.wikipedia.org/wiki/Factor%C3%ADa_romana_de_salazones_(Algeciras)]; Fish were salted at the Roman factory in Algeciras (fish and salt met there) [SUPPORTED: https://en.wikipedia.org/wiki/Fish_sauce]; The site is a site of archaeological and historical interest [SUPPORTED: https://en.wikipedia.org/wiki/Roman_fish_salting_factory]; The site was declared a Bien de Interés Cultural (BIC) site [SUPPORTED: https://www.boe.es/diario_boe/txt.php?id=BOE-A-2004-1506]"}]'::jsonb),
    ('e5bb0a42-df89-47d8-9ac4-669df257592a'::uuid, 'card_description', 'A village hidden inside a massive cave on Monte Tiscali, with round and rectangular dwellings from the 1st millennium BC. It was reoccupied in the 1st century BC and used through the Middle Ages.', 'Within a large cave in Monte Tiscali, Sardinia, the Nuragic Village of Tiscali keeps the remains of round dwellings from the first millennium BC, first documented in 1910.', 'teaser-card-s020:e5bb0a42-df89-47d8-9ac4-669df257592a:card_description', 'teaser-card-s020 (teaser-card): teaser card, 171 characters, checked PASS, web-verified VERIFIED', '78de46a4bc0b3ad3666acb876dbf5134865994894e4cf622bc9ff36e82924882|afb6fd8bc4191afa40ca1bf6317eb71f9caed66c45d37b359f941a61318f8802|afb6fd8bc4191afa40ca1bf6317eb71f9caed66c45d37b359f941a61318f8802', '[{"source": "lane WB run wb-ws-2026-09-27-06: writer teaser-wb-ws-2026-09-27-06-write-027", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Within a large cave in Monte Tiscali, Sardinia, the Nuragic Village of Tiscali keeps the remains of round dwellings from the first millennium BC, first documented in 1910."}, {"source": "lane WB run wb-ws-2026-09-27-06: checker teaser-wb-ws-2026-09-27-06-check-027 (check), PASS", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "the site lies within a large cave [S2]; the cave is in Monte Tiscali [S2]; it is in Sardinia [S1]; it keeps the remains of round dwellings [S3]; the dwellings date from the first millennium BC [S3]; the site was first documented in 1910 [S4]"}, {"source": "lane WB run wb-ws-2026-09-27-06: verifier teaser-wb-ws-2026-09-27-06-verify-080 (verify), VERIFIED", "url": "output/remediation/teaser/runs/wb-ws-2026-09-27-06/OUTCOMES.jsonl", "quote": "Tiscali is a village-type archaeological site in Sardinia [SUPPORTED: https://en.wikipedia.org/wiki/Tiscali_(village)]; The village is Nuragic [SUPPORTED: https://www.sardegnaturismo.it/en/explore/nuragic-village-tiscali]; The village lies within a large cave in Monte Tiscali [SUPPORTED: https://en.wikipedia.org/wiki/Tiscali_(village)]; The site keeps the remains of round dwellings [SUPPORTED: https://en.wikipedia.org/wiki/Tiscali_(village)]; The dwellings date from the first millennium BC [SUPPORTED: https://en.wikipedia.org/wiki/Tiscali_(village)]; The site was first documented in 1910 [SUPPORTED: https://en.wikipedia.org/wiki/Tiscali_(village)]"}]'::jsonb);

DO $$
DECLARE
    bad      INTEGER;
    moved    INTEGER := 0;
    expected INTEGER := 100;
    r        RECORD;
BEGIN
    -- expected is the plan's own row count, rendered here, and not a second count of the
    -- temp table the loop below iterates: counting the same table twice would make the
    -- comparison after the loop a tautology. The instance that makes a short loop
    -- unreachable is apply_remediation_change, which raises unless exactly one row
    -- matched; this guard is what reports a loop that changed fewer rows than the plan.

    -- scope guard 1: every planned row is a card_stats row of a curated site that still exists
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN card_stats t ON t.site_id = p.site_id
      LEFT JOIN unified_sites u ON u.id = p.site_id
     WHERE t.site_id IS NULL OR u.id IS NULL OR u.source_id <> 'ancient_nerds';
    IF bad > 0 THEN
        -- the source name is a RAISE argument, never part of the quoted message: a name
        -- spliced into the message text only parses while the name happens to contain no
        -- quote, which is a property of today's value and not of this code. G0's guard is
        -- the shape this one copies.
        RAISE EXCEPTION 'teaser card: % planned row(s) are not % sites', bad, 'ancient_nerds';
    END IF;

    -- scope guard 2: the plan is a set of real changes, each one writable in its column
    -- (compared in the column's own type; CASE, because only CASE fixes the order in
    -- which the casts are evaluated)
    SELECT count(*) INTO bad FROM _teaser_card_plan p
     WHERE p.new_value = '' OR CASE p.column_name
                WHEN 'card_description' THEN p.new_value::character varying IS NOT DISTINCT FROM p.old_value::character varying OR length(p.new_value) > 200
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) are not writable changes', bad;
    END IF;

    -- scope guard 3: every planned row still holds the old value the plan names
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.old_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the planned old value', bad;
    END IF;

    -- scope guard 5: every planned row still holds the input its value was derived from
    SELECT count(*) INTO bad
      FROM (SELECT DISTINCT site_id, premise FROM _teaser_card_plan) p JOIN unified_sites u ON u.id = p.site_id
     WHERE (coalesce(u.raw_data -> '_card_provenance' ->> 'text_sha256', '') || '|' || coalesce(u.raw_data -> '_card_provenance' ->> 'desc_sha256', '') || '|' || encode(sha256(convert_to(coalesce(u.description, ''), 'UTF8')), 'hex')) IS DISTINCT FROM p.premise;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) no longer hold the premise the plan derived its value from', bad;
    END IF;

    -- the only writer: the conditional UPDATE and its journal row commit together, and
    -- the function raises unless exactly one row matched
    FOR r IN SELECT * FROM _teaser_card_plan ORDER BY site_id, column_name LOOP
        moved := moved + apply_remediation_change(
            'card_stats', r.column_name, 'site_id', r.site_id::text,
            r.old_value, r.new_value,
            'WB/teaser-card', 'wb-teaser-card-s020', r.change_key, 'opus-checked', r.evidence, r.site_id);
    END LOOP;

    IF moved <> expected THEN
        RAISE EXCEPTION 'teaser card: % row(s) changed, % planned', moved, expected;
    END IF;

    -- invariant 1: every planned row now holds the new value
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p JOIN card_stats t ON t.site_id = p.site_id
     WHERE CASE p.column_name
                WHEN 'card_description' THEN t.card_description IS DISTINCT FROM p.new_value::character varying
                ELSE true END;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) do not hold the new value', bad;
    END IF;

    -- invariant 2: the journal and the data agree, row for row, in both directions
    SELECT count(*) INTO bad
      FROM _teaser_card_plan p LEFT JOIN remediation_change_log l
        ON l.row_pk = p.site_id::text AND l.table_name = 'card_stats'
       AND l.column_name = p.column_name
       AND l.run_stamp = 'wb-teaser-card-s020'
     WHERE l.id IS NULL
        OR l.new_value IS DISTINCT FROM p.new_value
        OR l.old_value IS DISTINCT FROM p.old_value;
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: % planned row(s) have no matching journal row', bad;
    END IF;

    SELECT count(*) INTO bad FROM remediation_change_log l
     WHERE l.run_stamp = 'wb-teaser-card-s020'
       AND (l.table_name <> 'card_stats' OR l.column_name NOT IN ('card_description'));
    IF bad > 0 THEN
        RAISE EXCEPTION 'teaser card: this run stamp journalled % row(s) outside card_stats.(card_description)', bad;
    END IF;

    RAISE NOTICE 'teaser card: % of % planned cell(s) changed and journalled over 100 curated site(s)',
        moved, expected;
END $$;

ROLLBACK;
-- after ROLLBACK: nothing may have changed
SELECT 'journal rows for this run stamp' AS metric, count(*)::text AS value
  FROM remediation_change_log WHERE run_stamp = 'wb-teaser-card-s020'
UNION ALL
SELECT 'curated sites whose teaser provenance does not hash their live card', count(*)::text
  FROM unified_sites
 WHERE source_id = 'ancient_nerds' AND raw_data ? '_card_provenance' AND NOT EXISTS (SELECT 1 FROM card_stats cs WHERE cs.site_id = unified_sites.id AND encode(sha256(convert_to(cs.card_description, 'UTF8')), 'hex') = unified_sites.raw_data -> '_card_provenance' ->> 'text_sha256')
UNION ALL
SELECT 'curated sites', count(*)::text
  FROM unified_sites WHERE source_id = 'ancient_nerds'
UNION ALL
-- `_teaser_card_plan` is a CREATE TEMP TABLE, so it lives in this session's `pg_temp_N` schema and
-- `nspname = 'public'` could never match it - the old form of this read was 0 whatever happened.
-- `to_regclass('pg_temp....')` resolves the current session's temp schema and is NULL when the
-- table is gone, so this reads 1 exactly when a leftover exists.
SELECT 'temp table _teaser_card_plan left behind',
       (to_regclass('pg_temp._teaser_card_plan') IS NOT NULL)::int::text
